const App: React.FC = () => {
  const [isAdminView, setIsAdminView] = useState(false);

  // Verifica se o usuário já estava no modo admin via URL ou localStorage
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('admin') === 'true' || localStorage.getItem('admin_session') === 'active') {
      setIsAdminView(true);
    }
  }, []);

  if (isAdminView) {
    return <AdminPanel onClose={() => {
      setIsAdminView(false);
      localStorage.removeItem('admin_session');
    }} />;
  }

  return (
    <div className="min-h-screen">
      <Navbar onAdminClick={() => setIsAdminView(true)} />

      <Hero />

      <div className="relative w-full h-24 bg-background-dark overflow-visible z-20">
