  const [activeTab, setActiveTab] = useState<'agenda' | 'artigos' | 'midia'>('agenda');
  const [loading, setLoading] = useState(false);

  // Estados de Dados
  const [events, setEvents] = useState<any[]>([]);
  const [articles, setArticles] = useState<any[]>([]);

  // Estado do Formulário de Evento
  const [eventForm, setEventForm] = useState({
    id: null as string | null,
    day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', featured: false
  });

  // Estado do Formulário de Artigo
  const [articleForm, setArticleForm] = useState({
    id: null as string | null,
    category: 'História', title: '', content: '', image_url: ''
  });

  // Estado de Mídia (Social)
  const [socialLink, setSocialLink] = useState({ url: '', type: 'youtube' as 'youtube' | 'instagram' });

  useEffect(() => {
    if (isLoggedIn) {
      fetchData();
    }
  }, [isLoggedIn, activeTab]);

  const fetchData = async () => {
    setLoading(true);
    if (activeTab === 'agenda') {
      const { data } = await supabase.from('events').select('*').order('created_at', { ascending: false });
      setEvents(data || []);
    } else if (activeTab === 'artigos') {
      const { data } = await supabase.from('articles').select('*').order('created_at', { ascending: false });
      setArticles(data || []);
    }
    setLoading(false);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else {
      alert('Credenciais Master incorretas!');
    }
  };

  const handleSaveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (eventForm.id) {
        const { error } = await supabase.from('events').update(eventForm).eq('id', eventForm.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('events').insert([eventForm]);
        if (error) throw error;
      }
      alert('Evento salvo com sucesso!');
      setEventForm({ id: null, day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', featured: false });
      fetchData();
