import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';

interface EventData {
  id: string;
  day: string;
  month: string;
  title: string;
  location: string;
  image_url: string;
  label?: string;
  label_color?: string;
  featured?: boolean;
  price?: string;
  ticket_url?: string;
}

interface EventCardProps {
  day: string;
  month: string;
  title: string;
  location: string;
  image: string;
  label?: string;
  labelColor?: string;
  align?: 'start' | 'end';
  price?: string;
  ticket_url?: string;
  width?: string;
  featured?: boolean;
}

const EventCard: React.FC<EventCardProps> = ({ 
  day, 
  month, 
  title, 
  location, 
  image, 
  label, 
  labelColor = 'accent-red', 
  align = 'start', 
  price, 
  ticket_url,
  width = 'w-[90%]',
  featured = false 
}) => {
  const isStart = align === 'start';

  return (
    <article className={`group relative w-full md:${width} ${isStart ? 'self-start' : 'self-end'} bg-card-dark rounded-xl p-4 md:p-0 flex flex-col md:flex-row overflow-hidden hover:bg-surface-brown transition-all duration-500 shadow-lg shadow-black/50 border border-white/5 hover:border-primary/30`}>
      {/* Date Column */}
      <div className={`w-full md:w-32 ${featured ? 'bg-primary/10' : 'bg-white/5'} flex flex-row md:flex-col items-center justify-center p-4 gap-2 border-b md:border-b-0 md:border-r ${featured ? 'border-primary/20' : 'border-white/10'} shrink-0`}>
        <span className={`${featured ? 'text-primary' : 'text-white/60'} font-bold text-lg uppercase tracking-widest`}>{month}</span>
        <span className="text-white font-black text-4xl md:text-5xl">{day}</span>
      </div>

      {/* Content */}
      <div className="flex-1 p-6 flex flex-col justify-between gap-6">
        <div>
          <div className="flex justify-between items-start mb-2">
            {label && (
              <span className={`bg-${labelColor}/20 text-${labelColor} text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider`}>
                {label}
              </span>
            )}
            {!label && featured && (
               <span className="text-primary text-[10px] font-bold px-2 py-1 border border-primary/30 rounded uppercase tracking-wider">Destaque</span>
            )}
            <span className="material-symbols-outlined text-white/30 cursor-pointer hover:text-primary transition-colors">favorite</span>
          </div>
          <h3 className="text-2xl md:text-3xl font-bold text-white mb-2 leading-tight group-hover:text-primary transition-colors">{title}</h3>
          <div className="flex items-center gap-2 text-white/60 text-sm">
            <span className="material-symbols-outlined text-lg">location_on</span>
            <span>{location}</span>
          </div>
        </div>

        <div className="flex items-center justify-between mt-auto">
          {price ? (
             <p className="text-sm text-white/40">{price}</p>
          ) : (
            <div className="flex -space-x-2">
              <img alt="Attendee" className="w-8 h-8 rounded-full border-2 border-card-dark" src="https://i.pravatar.cc/150?u=1"/>
              <img alt="Attendee" className="w-8 h-8 rounded-full border-2 border-card-dark" src="https://i.pravatar.cc/150?u=2"/>
              <img alt="Attendee" className="w-8 h-8 rounded-full border-2 border-card-dark" src="https://i.pravatar.cc/150?u=3"/>
              <span className="w-8 h-8 rounded-full border-2 border-card-dark bg-white/10 flex items-center justify-center text-[10px] font-bold text-white/80">+2k</span>
            </div>
          )}

          <a 
            href={ticket_url || "#"} 
            target={ticket_url ? "_blank" : undefined}
            rel="noopener noreferrer"
            className={`bg-${featured ? 'primary' : 'white/10'} ${featured ? 'text-white hover:bg-white hover:text-black' : 'text-white hover:bg-primary'} text-sm font-bold px-6 py-3 rounded-lg transition-all border ${featured ? 'border-transparent' : 'border-white/10'} hover:border-transparent transform hover:scale-105 inline-block text-center`}
          >
            {featured ? 'COMPRAR' : 'INGRESSOS'}
          </a>
        </div>
      </div>

      {/* Image Side */}
      <div className="w-full md:w-64 h-48 md:h-auto shrink-0 relative overflow-hidden order-first md:order-last">
        <div 
          className="absolute inset-0 bg-cover bg-center transition-transform duration-[1.5s] group-hover:scale-110" 
          style={{ backgroundImage: `url('${image}')` }}
        ></div>
        <div className="absolute inset-0 bg-gradient-to-l from-transparent to-card-dark/80 md:to-transparent"></div>
      </div>
    </article>
  );
};

const EventList: React.FC = () => {
  const [events, setEvents] = useState<EventData[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchEvents() {
      try {
        const { data, error } = await supabase
          .from('events')
          .select('*')
          .order('featured', { ascending: false });

        if (error) throw error;

        if (data && data.length > 0) {
          setEvents(data);
        } else {
          throw new Error("No data found");
        }
      } catch (err) {
        console.warn('Usando eventos de fallback:', err);
        setEvents([
          {
            id: '1',
            day: '18',
            month: 'NOV',
            title: 'Samba da Ouvidor',
            location: 'Rua do Ouvidor, Rio de Janeiro',
            image_url: 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?auto=format&fit=crop&q=80&w=800',
            label: 'Mais Procurado',
            featured: true,
            price: 'Entrada Gratuita'
          },
          {
            id: '2',
            day: '22',
            month: 'NOV',
            title: 'Pagode da 27',
            location: 'Grajaú, São Paulo',
            image_url: 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&q=80&w=800',
            featured: false,
            price: 'R$ 20,00'
          }
        ]);
      } finally {
        setLoading(false);
      }
    }

    fetchEvents();
  }, []);

  return (
    <section className="w-full">
      <div className="max-w-6xl mx-auto mb-16 relative">
        <div className="absolute -left-10 -top-10 text-[8rem] md:text-[10rem] font-black text-white/[0.03] select-none pointer-events-none whitespace-nowrap">
          AGENDA
        </div>
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 relative z-10">
          <div>
            <h2 className="text-4xl md:text-6xl font-black text-white leading-[0.9] tracking-tight">
              ONDE A RODA<br/>
              <span className="text-outline">ACONTECE</span>
            </h2>
            <p className="text-primary font-bold mt-4 tracking-widest text-sm uppercase">Sua programação semanal de samba</p>
          </div>
          <div className="h-px bg-white/20 flex-1 mx-8 hidden md:block"></div>
        </div>
      </div>

      <div className="max-w-5xl mx-auto flex flex-col gap-10 md:gap-12">
        {loading ? (
          <div className="flex flex-col gap-8 animate-pulse">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-64 bg-white/5 rounded-xl w-full"></div>
            ))}
          </div>
        ) : (
          events.map((event, index) => (
            <EventCard 
              key={event.id}
              day={event.day}
              month={event.month}
              title={event.title}
              location={event.location}
              image={event.image_url}
              label={event.label}
              labelColor={event.label_color}
              align={index % 2 === 0 ? 'start' : 'end'}
              featured={event.featured}
              price={event.price}
              ticket_url={event.ticket_url}
              width={index % 3 === 1 ? 'w-[95%]' : index % 3 === 2 ? 'w-[88%]' : 'w-[92%]'}
            />
          ))
        )}
      </div>
    </section>
  );
};

export default EventList;

