  onClose: () => void;
}

interface ActivityItem {
  id: string;
  title: string;
  created_at: string;
  type: 'evento' | 'post';
  status: string;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'media' | 'eventos'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [recentActivity, setRecentActivity] = useState<ActivityItem[]>([]);

  // Estados para formulários
  const [quickPost, setQuickPost] = useState('');
  const [isMonetized, setIsMonetized] = useState(false);
  const [showEventModal, setShowEventModal] = useState(false);
  const [eventForm, setEventForm] = useState({
    day: '', month: '', title: '', location: '', image_url: '', price: '', featured: false
  });

  useEffect(() => {
    if (isLoggedIn) {
      fetchActivity();
    }
  }, [isLoggedIn]);

  const fetchActivity = async () => {
    try {
      const { data, error } = await supabase
        .from('events')
        .select('id, title, created_at')
        .order('created_at', { ascending: false })
        .limit(5);

      if (error) throw error;

      const mapped = (data || []).map(item => ({
        id: item.id,
        title: item.title,
        created_at: item.created_at,
        type: 'evento' as const,
        status: 'Ativo'
      }));

      setRecentActivity(mapped);
    } catch (err) {
      console.error("Erro ao carregar atividade:", err);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else {
      alert('Credenciais Master incorretas!');
    }
  };

  const handleQuickPost = async () => {
    if (!quickPost.trim()) return;
    setLoading(true);
    try {
      // Nota: Assume-se que existe uma tabela 'posts' ou similar. 
      // Se não houver, estamos registrando como um evento simples para demonstração
      const { error } = await supabase.from('events').insert([{
        title: quickPost,
        day: new Date().getDate().toString(),
        month: 'POST',
        location: 'Feed Geral',
        image_url: 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?q=80&w=800',
        featured: isMonetized
      }]);

      if (error) throw error;
      alert('Publicação realizada com sucesso!');
      setQuickPost('');
      fetchActivity();
    } catch (err: any) {
      alert('Erro ao publicar: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.from('events').insert([eventForm]);
      if (error) throw error;
      alert('Evento cadastrado com sucesso!');
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', price: '', featured: false });
      setShowEventModal(false);
      fetchActivity();
    } catch (err: any) {
      alert('Erro: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-4 bg-noise">
        <div className="w-full max-w-md bg-card-dark border border-white/10 rounded-3xl p-8 shadow-2xl">
          <div className="flex justify-center mb-8">
            <span className="material-symbols-outlined text-primary text-6xl">admin_panel_settings</span>
          </div>
          <h2 className="text-2xl font-black text-center mb-8 tracking-tighter">ACESSO MASTER ADMIN</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="text-xs font-bold text-white/40 uppercase mb-2 block">Usuário Master</label>
              <input 
                type="text" 
                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:border-primary outline-none text-white"
                value={loginForm.user}
                onChange={e => setLoginForm({...loginForm, user: e.target.value})}
              />
            </div>
            <div>
              <label className="text-xs font-bold text-white/40 uppercase mb-2 block">Senha</label>
              <input 
                type="password" 
                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 focus:border-primary outline-none text-white"
                value={loginForm.pass}
                onChange={e => setLoginForm({...loginForm, pass: e.target.value})}
              />
            </div>
            <button type="submit" className="w-full bg-primary hover:bg-white hover:text-black py-4 rounded-xl font-bold transition-all mt-4 text-white">
              ENTRAR NO PAINEL
            </button>
            <button type="button" onClick={onClose} className="w-full text-white/40 text-sm hover:text-white transition-colors py-2">
              Voltar para o site
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-neutral-900 font-body text-white">
      {/* Sidebar */}
      <aside className="hidden w-72 flex-col justify-between border-r border-white/5 lg:flex flex-shrink-0 z-20 shadow-2xl bg-[#171717] relative">
        <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'radial-gradient(rgba(184, 135, 0, 0.1) 1px, transparent 1px)', backgroundSize: '24px 24px' }}></div>

        <div className="flex flex-col gap-6 p-6 relative z-10">
          <div className="flex items-center gap-3">
            <div className="relative size-10 overflow-hidden rounded-full border border-primary/30">
              <span className="material-symbols-outlined text-primary text-2xl absolute inset-0 flex items-center justify-center">surround_sound</span>
            </div>
            <div className="flex flex-col">
              <h1 className="font-display text-lg font-bold uppercase leading-none tracking-wide text-white">Tem Samba Aí</h1>
              <span className="text-xs font-medium text-primary tracking-wider uppercase opacity-80">Admin Console</span>
            </div>
          </div>

          <nav className="flex flex-col gap-2 mt-4">
            <button 
              onClick={() => setActiveTab('dashboard')}
              className={`group flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-bold transition-all ${activeTab === 'dashboard' ? 'bg-primary/10 text-white ring-1 ring-primary/20' : 'text-neutral-400 hover:bg-white/5 hover:text-white'}`}
            >
              <span className={`material-symbols-outlined text-[20px] ${activeTab === 'dashboard' ? 'text-primary' : 'group-hover:text-primary'}`}>dashboard</span>
              Dashboard
            </button>
            <button 
              onClick={() => setActiveTab('media')}
              className={`group flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-bold transition-all ${activeTab === 'media' ? 'bg-primary/10 text-white ring-1 ring-primary/20' : 'text-neutral-400 hover:bg-white/5 hover:text-white'}`}
            >
              <span className={`material-symbols-outlined text-[20px] ${activeTab === 'media' ? 'text-primary' : 'group-hover:text-primary'}`}>perm_media</span>
              Media Hub
            </button>
            <button 
              onClick={() => setActiveTab('eventos')}
              className={`group flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-bold transition-all ${activeTab === 'eventos' ? 'bg-primary/10 text-white ring-1 ring-primary/20' : 'text-neutral-400 hover:bg-white/5 hover:text-white'}`}
            >
              <span className={`material-symbols-outlined text-[20px] ${activeTab === 'eventos' ? 'text-primary' : 'group-hover:text-primary'}`}>calendar_month</span>
              Eventos
            </button>
          </nav>
        </div>

        <div className="border-t border-white/5 p-6 relative z-10">
          <div className="flex items-center justify-between gap-3 rounded-xl bg-[#2C2C2C] p-3 ring-1 ring-white/5">
            <div className="flex items-center gap-3">
              <div className="h-9 w-9 overflow-hidden rounded-full bg-neutral-700 flex items-center justify-center">
                <span className="material-symbols-outlined text-white/40">person</span>
              </div>
              <div className="flex flex-col">
                <span className="text-sm font-bold text-white">Admin Master</span>
                <span className="text-[10px] text-neutral-400">Editor Chefe</span>
              </div>
            </div>
            <button onClick={() => { localStorage.removeItem('admin_session'); onClose(); }} className="text-neutral-400 hover:text-white">
              <span className="material-symbols-outlined text-[20px]">logout</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex h-full flex-1 flex-col overflow-y-auto bg-neutral-900 relative">
        <div className="absolute top-0 left-0 w-full h-80 bg-gradient-to-b from-primary/10 via-primary/5 to-transparent pointer-events-none z-0"></div>

        <div className="relative z-10 flex min-h-full flex-col p-6 lg:p-10 max-w-[1600px] mx-auto w-full">
          <header className="flex flex-wrap items-center justify-between gap-6 mb-8">
            <nav className="flex items-center gap-2 text-sm">
              <span className="font-medium text-neutral-500">Admin</span>
