          </header>

          <div className="mb-10">
            <h2 className="font-display text-3xl font-black tracking-tight text-white mb-6">Ações Rápidas</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <button onClick={() => setShowEventModal(true)} className="group flex flex-col items-center justify-center gap-3 rounded-2xl bg-[#2C2C2C] p-6 ring-1 ring-white/5 transition-all hover:bg-primary hover:text-neutral-900 hover:ring-primary">
                <span className="material-symbols-outlined text-[32px] text-primary group-hover:text-neutral-900">calendar_add_on</span>
                <span className="font-bold text-sm">Novo Evento</span>
              </button>
              <button className="group flex flex-col items-center justify-center gap-3 rounded-2xl bg-[#2C2C2C] p-6 ring-1 ring-white/5 transition-all hover:bg-primary hover:text-neutral-900 hover:ring-primary">
                <span className="material-symbols-outlined text-[32px] text-primary group-hover:text-neutral-900">video_library</span>
                <span className="font-bold text-sm">Upload Vídeo</span>
              </button>
              <button className="group flex flex-col items-center justify-center gap-3 rounded-2xl bg-[#2C2C2C] p-6 ring-1 ring-white/5 transition-all hover:bg-primary hover:text-neutral-900 hover:ring-primary">
                <span className="material-symbols-outlined text-[32px] text-primary group-hover:text-neutral-900">add_a_photo</span>
