            {/* Quick Post */}
            <div className="flex flex-col gap-4 rounded-2xl bg-gradient-to-br from-[#2C2C2C] to-neutral-900 p-6 ring-1 ring-white/5 shadow-xl relative overflow-hidden">
              <div className="absolute top-0 right-0 w-24 h-24 bg-primary/5 rounded-full -mr-10 -mt-10 blur-xl"></div>
              <h3 className="font-display text-lg font-bold text-white mb-2 relative z-10">Post Rápido / Comunidade</h3>
