export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

interface ActivityItem {
  id: string;
  title: string;
  created_at: string;
  type: string;
  status: string;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'media' | 'eventos'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [recentActivity, setRecentActivity] = useState<ActivityItem[]>([]);

  // Estados para formulários
  const [quickPost, setQuickPost] = useState('');
  const [isFeaturedPost, setIsFeaturedPost] = useState(false);
  const [showEventModal, setShowEventModal] = useState(false);
  const [eventForm, setEventForm] = useState({
    day: '', month: '', title: '', location: '', image_url: '', price: '', featured: false, label: ''
  });

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchActivity();
    }
  }, [isLoggedIn]);

  const fetchActivity = async () => {
    try {
      const { data, error } = await supabase
        .from('events')
        .select('id, title, created_at, featured')
        .order('created_at', { ascending: false })
        .limit(8);

      if (error) throw error;

      const mapped = (data || []).map(item => ({
        id: item.id,
        title: item.title,
        created_at: item.created_at,
        type: item.featured ? 'Destaque' : 'Comum',
        status: 'Ativo'
      }));

      setRecentActivity(mapped);
    } catch (err) {
      console.error("Erro ao carregar atividade:", err);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
