import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';

interface EventData {
  id: string;
  day: string;
  month: string;
  title: string;
  location: string;
  image_url: string;
  label?: string;
  label_color?: string;
  featured?: boolean;
  price?: string;
  created_at?: string;
}

interface InteractiveAgendaProps {
  onBack: () => void;
}

const InteractiveAgenda: React.FC<InteractiveAgendaProps> = ({ onBack }) => {
  const [events, setEvents] = useState<EventData[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('Todos');

  useEffect(() => {
    async function fetchAllEvents() {
      setLoading(true);
      try {
        const { data, error } = await supabase
          .from('events')
          .select('*')
          .order('created_at', { ascending: false });

        if (error) throw error;
        setEvents(data || []);
      } catch (err) {
        console.error("Erro ao carregar agenda:", err);
      } finally {
        setLoading(false);
      }
    }
    fetchAllEvents();
    window.scrollTo(0, 0);
  }, []);

  const filteredEvents = filter === 'Todos' 
    ? events 
    : events.filter(e => e.location.toLowerCase().includes(filter.toLowerCase()));

  return (
    <div className="antialiased selection:bg-primary selection:text-white bg-background-dark min-h-screen">
      {/* Navigation */}
      <nav className="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-3xl">
