import React, { useState, useEffect } from 'react';

interface SocialActionsProps {
  contentId: string;
}

const SocialActions: React.FC<SocialActionsProps> = ({ contentId }) => {
  const [likes, setLikes] = useState(0);
  const [hasLiked, setHasLiked] = useState(false);
  const [showCommentInput, setShowCommentInput] = useState(false);
  const [comment, setComment] = useState('');
  const [instagram, setInstagram] = useState('');
  const [commentsList, setCommentsList] = useState<{user: string, text: string}[]>([]);

  useEffect(() => {
    // Carregar identidade salva
    const savedInsta = localStorage.getItem('user_insta');
    if (savedInsta) setInstagram(savedInsta);

    // Carregar curtidas simuladas
    const randomLikes = Math.floor(Math.random() * 500) + 50;
    setLikes(randomLikes);

    // Simular alguns comentários iniciais
    setCommentsList([
      { user: 'samba_raiz', text: 'Simplesmente incrível! Axé! 🙌' },
      { user: 'pagodeiro_br', text: 'Melhor curadoria que já vi no site.' }
    ]);
  }, [contentId]);

  const handleLike = () => {
    if (!instagram) {
      const input = prompt("Para curtir e comentar, digite seu @ do Instagram:");
      if (input) {
        const formatted = input.startsWith('@') ? input : `@${input}`;
        setInstagram(formatted);
        localStorage.setItem('user_insta', formatted);
      } else return;
    }

    setHasLiked(!hasLiked);
    setLikes(prev => hasLiked ? prev - 1 : prev + 1);
  };

  const handleComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!comment.trim()) return;

    if (!instagram) {
      const input = prompt("Digite seu @ do Instagram para publicar:");
      if (input) {
        const formatted = input.startsWith('@') ? input : `@${input}`;
        setInstagram(formatted);
        localStorage.setItem('user_insta', formatted);
      } else return;
    }

    setCommentsList(prev => [{ user: instagram.replace('@',''), text: comment }, ...prev]);
    setComment('');
    alert('Comentário publicado com sucesso!');
  };

  return (
    <div className="w-full space-y-4">
      {/* Action Bar */}
      <div className="flex items-center gap-6">
        <button 
          onClick={handleLike}
          className={`flex items-center gap-2 group transition-all ${hasLiked ? 'text-primary' : 'text-white/40 hover:text-white'}`}
        >
          <span className={`material-symbols-outlined text-2xl ${hasLiked ? 'filled' : ''} transition-transform group-active:scale-125`}>
            {hasLiked ? 'favorite' : 'favorite'}
          </span>
          <span className="text-[10px] font-black uppercase tracking-widest">{likes} curtidas</span>
        </button>

        <button 
          onClick={() => setShowCommentInput(!showCommentInput)}
          className="flex items-center gap-2 text-white/40 hover:text-white transition-all group"
        >
          <span className="material-symbols-outlined text-2xl group-hover:rotate-12 transition-transform">chat_bubble</span>
          <span className="text-[10px] font-black uppercase tracking-widest">{commentsList.length} comentários</span>
        </button>

        <button className="flex items-center gap-2 text-white/40 hover:text-white transition-all">
          <span className="material-symbols-outlined text-2xl">share</span>
        </button>

        {instagram && (
          <div className="ml-auto">
             <span className="text-[9px] font-black text-primary uppercase tracking-tighter opacity-50">Logado como {instagram}</span>
          </div>
        )}
      </div>

      {/* Comment Input */}
      {showCommentInput && (
        <div className="pt-4 animate-fade-in-up">
          <form onSubmit={handleComment} className="flex gap-2">
            <input 
              type="text" 
              value={comment}
              onChange={e => setComment(e.target.value)}
              placeholder="Escreva um comentário..."
              className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:border-primary outline-none"
            />
            <button type="submit" className="bg-primary text-white px-4 py-2 rounded-xl">
              <span className="material-symbols-outlined text-sm">send</span>
            </button>
          </form>

          {/* Mini-feed */}
          <div className="mt-6 space-y-4 max-h-[150px] overflow-y-auto pr-2 no-scrollbar">
            {commentsList.map((c, i) => (
              <div key={i} className="flex gap-3 text-sm border-l border-white/10 pl-4 py-1">
                <span className="text-primary font-bold text-xs">@{c.user}</span>
                <span className="text-white/60 font-light">{c.text}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

