Com certeza! Para que o site funcione, você precisa criar as tabelas no seu projeto do Supabase. Sem elas, o site não consegue salvar nem ler nada.

Copie o código abaixo e cole no **SQL Editor** do seu painel do Supabase:

```sql
-- 1. Tabela de Eventos
CREATE TABLE events (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at TIMESTAMPTZ DEFAULT now(),
  day TEXT,
  month TEXT,
  title TEXT NOT NULL,
  location TEXT,
  image_url TEXT,
  label TEXT,
  label_color TEXT DEFAULT 'primary',
  featured BOOLEAN DEFAULT false,
  price TEXT
);

-- 2. Tabela de Vídeos
CREATE TABLE videos (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at TIMESTAMPTZ DEFAULT now(),
  title TEXT NOT NULL,
  category TEXT,
  thumbnail TEXT,
  video_url TEXT,
  duration TEXT
);

-- 3. Tabela de Artigos (Seção Leia)
CREATE TABLE articles (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at TIMESTAMPTZ DEFAULT now(),
  title TEXT NOT NULL,
  excerpt TEXT,
  content TEXT,
  category TEXT,
  read_time TEXT,
  image_url TEXT
);

-- 4. Tabela de Interações (Curtidas e Comentários)
CREATE TABLE interactions (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at TIMESTAMPTZ DEFAULT now(),
  content_id TEXT NOT NULL,
  user_insta TEXT NOT NULL,
  type TEXT NOT NULL, -- 'like' ou 'comment'
  text TEXT -- Apenas para comentários
);

-- 5. Configurar Políticas de Segurança (RLS) para acesso público
-- Isso permite que o site leia os dados e os usuários comentem/curtam sem precisar de login formal.

ALTER TABLE events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir leitura pública" ON events FOR SELECT USING (true);
CREATE POLICY "Permitir tudo para admin" ON events FOR ALL USING (true);

ALTER TABLE videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir leitura pública" ON videos FOR SELECT USING (true);
CREATE POLICY "Permitir tudo para admin" ON videos FOR ALL USING (true);

ALTER TABLE articles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir leitura pública" ON articles FOR SELECT USING (true);
CREATE POLICY "Permitir tudo para admin" ON articles FOR ALL USING (true);

ALTER TABLE interactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Permitir leitura pública" ON interactions FOR SELECT USING (true);
CREATE POLICY "Permitir inserção pública" ON interactions FOR INSERT WITH CHECK (true);
CREATE POLICY "Permitir deleção pública" ON interactions FOR DELETE USING (true);
```

