                    <button type="submit" disabled={loading} className="w-full bg-primary py-5 rounded-xl font-black uppercase text-white hover:bg-primary-dark transition-all text-sm tracking-widest">{loading ? 'Enviando ao Editorial...' : 'Publicar no Editorial Digital'}</button>
                </form>

                <div className="space-y-4">
                    <h3 className="text-white/20 text-[10px] font-black uppercase tracking-[0.3em] mb-4">Artigos no Ar</h3>
                    {items.map(item => (
                        <div key={item.id} className="bg-card-dark p-6 rounded-2xl border border-white/5 flex justify-between items-center hover:bg-white/5 transition-all group">
                            <div className="flex gap-6 items-center">
                                <img src={item.image_url} className="w-20 h-20 object-cover rounded-xl" alt="" />
                                <div>
                                    <h4 className="text-lg font-black uppercase tracking-tighter group-hover:text-primary transition-colors">{item.title}</h4>
                                    <p className="text-[10px] text-white/40 uppercase tracking-widest">{item.category} • {item.read_time}</p>
                                </div>
                            </div>
                            <button onClick={() => handleDelete(item.id)} className="text-red-500 font-black text-[10px] uppercase hover:underline p-4">Excluir Artigo</button>
                        </div>
                    ))}
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

