            <input type="password" placeholder="Senha" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-bold uppercase hover:bg-primary-dark transition-all">Acessar Painel</button>
            <button type="button" onClick={onClose} className="w-full text-white/40 text-xs py-2 uppercase hover:text-white transition-all text-center">Voltar ao site</button>
          </form>
        </div>
      </div>
    );
