};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline' | 'checking'>('checking');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Stats
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') setIsLoggedIn(true);
    checkConnection();
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) {
        setDbStatus('offline');
        setErrorMessage(error.message);
      } else {
        setDbStatus('online');
        setErrorMessage(null);
      }
    } catch (err: any) {
      setDbStatus('offline');
      setErrorMessage(err.message);
    }
  };

  const fetchStats = async () => {
    const { count: eCount } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: vCount } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: aCount } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: eCount || 0, videos: vCount || 0, articles: aCount || 0 });
  };

  const fetchItems = async () => {
    setLoading(true);
    let table = '';
    if (activeTab === 'eventos') table = 'events';
    else if (activeTab === 'videos') table = 'videos';
    else if (activeTab === 'posts') table = 'articles';
    else { setLoading(false); return; }

    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      console.error(`Erro ao buscar:`, err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else {
      alert('Credenciais incorretas!');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Excluir permanentemente?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      fetchItems();
      fetchStats();
    } catch (err: any) {
      alert('Erro ao excluir: ' + err.message);
    }
  };

  const handleSaveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.from('events').insert([eventForm]);
      if (error) throw error;
      alert('✅ Evento publicado com sucesso!');
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '' });
      fetchItems();
      fetchStats();
    } catch (err: any) { alert('Erro: ' + err.message); } finally { setLoading(false); }
  };

  const handleSaveVideo = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.from('videos').insert([videoForm]);
      if (error) throw error;
      alert('✅ Vídeo publicado!');
      setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
      fetchItems();
      fetchStats();
    } catch (err: any) { alert('Erro: ' + err.message); } finally { setLoading(false); }
  };

  const handleSavePost = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.from('articles').insert([postForm]);
      if (error) throw error;
      alert('✅ Artigo publicado no Editorial!');
      setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });
      fetchItems();
      fetchStats();
    } catch (err: any) { alert('Erro: ' + err.message); } finally { setLoading(false); }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-card-dark border border-white/10 rounded-3xl p-8 shadow-2xl">
          <div className="flex justify-center mb-6">
            <span className="material-symbols-outlined text-primary text-5xl">surround_sound</span>
          </div>
          <h2 className="text-2xl font-black text-center mb-8 text-white uppercase tracking-tighter">Login Master</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="Usuário" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none focus:border-primary" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="Senha" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none focus:border-primary" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-bold uppercase hover:bg-primary-dark transition-all shadow-lg shadow-primary/20">Acessar Painel</button>
            <button type="button" onClick={onClose} className="w-full text-white/40 text-xs py-2 uppercase hover:text-white transition-all text-center">Voltar ao site</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 bg-card-dark border-r border-white/5 p-6 flex flex-col gap-8 shrink-0">
        <div className="flex items-center gap-2">
          <span className="material-symbols-outlined text-primary">admin_panel_settings</span>
          <h1 className="font-black text-sm uppercase tracking-tighter">Gestão Master</h1>
        </div>
        <nav className="flex flex-col gap-2">
          {[
            {id:'dashboard',l:'Dashboard',i:'dashboard'},
            {id:'eventos',l:'Agenda',i:'calendar_month'},
            {id:'videos',l:'Galeria Vídeos',i:'video_library'},
            {id:'posts',l:'Editorial',i:'article'}
          ].map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id as any)} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-white/40 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-sm">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>
        <div className="mt-auto pt-4 border-t border-white/5">
          <div className="flex items-center gap-2 mb-4 px-2">
            <div className={`w-2 h-2 rounded-full ${dbStatus === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></div>
            <span className="text-[8px] uppercase font-black opacity-40">{dbStatus === 'online' ? 'Conectado' : 'Erro DB'}</span>
          </div>
          <button onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="w-full flex items-center gap-3 px-4 py-3 text-red-500 text-[10px] font-black uppercase hover:bg-red-500/10 rounded-xl transition-all">
             <span className="material-symbols-outlined text-sm">logout</span> Sair do Sistema
          </button>
        </div>
      </aside>

      {/* Content Area */}
      <main className="flex-1 overflow-y-auto p-10 bg-noise relative">
        <header className="flex justify-between items-center mb-12">
            <div>
              <h2 className="text-4xl font-black uppercase tracking-tighter">{activeTab}</h2>
              <p className="text-[10px] text-white/40 uppercase font-black tracking-widest mt-1">Gerenciamento de conteúdo em tempo real</p>
            </div>
            <div className="flex gap-4">
              <button onClick={checkConnection} className="p-2 bg-white/5 border border-white/10 rounded-full hover:bg-white/10 transition-all">
                <span className={`material-symbols-outlined ${dbStatus === 'checking' ? 'animate-spin' : ''}`}>sync</span>
              </button>
              <button onClick={onClose} className="px-6 py-2 bg-primary border border-primary/20 rounded-full text-[10px] font-black uppercase hover:bg-white hover:text-black transition-all">Visualizar Site</button>
