      setErrorMessage(err.message);
    }
  };

  const fetchStats = async () => {
    const { count: eCount } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: vCount } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: aCount } = await supabase.from('articles').select('*', { count: 'exact', head: true });
