import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import SocialActions from './SocialActions';

interface VideoItem {
  id: string;
  title: string;
  category: string;
  thumbnail: string;
  duration: string;
  video_url: string;
}

const VideoGallery: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [activeCategory, setActiveCategory] = useState('Todos');
  const [videos, setVideos] = useState<VideoItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedVideo, setSelectedVideo] = useState<string | null>(null);

  useEffect(() => {
    async function fetchVideos() {
      try {
        const { data, error } = await supabase.from('videos').select('*').order('created_at', { ascending: false });
        if (error) throw error;
        setVideos(data || []);
      } catch (err) { console.warn(err); } finally { setLoading(false); }
    }
    fetchVideos();
    window.scrollTo(0, 0);
  }, []);

  const getEmbedUrl = (url: string) => {
    if (url.includes('youtube.com/watch?v=')) return url.replace('watch?v=', 'embed/');
    if (url.includes('youtu.be/')) return url.replace('youtu.be/', 'youtube.com/embed/');
    if (url.includes('vimeo.com/')) return url.replace('vimeo.com/', 'player.vimeo.com/video/');
    return url;
  };

  const filteredVideos = activeCategory === 'Todos' ? videos : videos.filter(v => v.category === activeCategory);

  return (
    <div className="min-h-screen bg-background-dark font-display text-white">
      {selectedVideo && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl">
          <button onClick={() => setSelectedVideo(null)} className="absolute top-6 right-6 text-white hover:text-primary transition-colors">
            <span className="material-symbols-outlined text-4xl">close</span>
          </button>
          <div className="w-full max-w-5xl aspect-video rounded-2xl overflow-hidden bg-black shadow-2xl">
            <iframe src={`${getEmbedUrl(selectedVideo)}?autoplay=1`} className="w-full h-full" allow="autoplay; encrypted-media" allowFullScreen></iframe>
          </div>
        </div>
      )}

      <nav className="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-3xl">
        <div className="bg-black/80 backdrop-blur-xl border border-white/10 rounded-full px-8 py-3 flex items-center justify-between">
          <button onClick={onBack} className="flex items-center gap-2 group">
             <span className="material-symbols-outlined text-primary">surround_sound</span>
             <span className="font-black text-sm uppercase tracking-tighter">Tem Samba Aí</span>
          </button>
          <button onClick={onBack} className="bg-primary text-white text-[10px] font-black px-4 py-2 rounded-full uppercase">Voltar</button>
        </div>
      </nav>

      <header className="pt-40 pb-20 px-6 max-w-7xl mx-auto text-center">
        <h1 className="text-6xl md:text-9xl font-black tracking-tighter uppercase leading-[0.8] mb-8">ASSISTA <br/><span className="text-outline">AO RITMO</span></h1>
        <div className="flex flex-wrap justify-center gap-3 mt-12">
          {['Todos', 'Ao Vivo', 'Tutorial', 'Entrevista', 'Documentário'].map(cat => (
            <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${activeCategory === cat ? 'bg-primary border-primary text-white' : 'bg-transparent border-white/10 text-white/60'}`}>{cat}</button>
          ))}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 pb-40 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12">
        {loading ? <div className="col-span-full text-center py-20 animate-pulse text-white/20 font-black">Carregando Acervo...</div> : 
          filteredVideos.map(video => (
          <div key={video.id} className="group space-y-4">
            <div onClick={() => setSelectedVideo(video.video_url)} className="cursor-pointer block relative aspect-video rounded-[2rem] overflow-hidden border border-white/5 shadow-2xl">
              <img src={video.thumbnail} alt={video.title} className="w-full h-full object-cover opacity-70 transition-transform duration-700 group-hover:scale-110" />
              <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <div className="bg-primary text-white w-16 h-16 rounded-full flex items-center justify-center shadow-2xl scale-90 group-hover:scale-100 transition-transform">
                  <span className="material-symbols-outlined text-3xl filled">play_arrow</span>
                </div>
              </div>
            </div>
            <div className="px-2">
              <h3 className="text-2xl font-black uppercase tracking-tighter leading-tight mb-4 group-hover:text-primary transition-colors">{video.title}</h3>
              <SocialActions contentId={`video-${video.id}`} />
            </div>
          </div>
        ))}
      </main>
    </div>
  );
};

