import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [dbStatus, setDbStatus] = useState<'online' | 'offline' | 'checking'>('checking');

  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') setIsLoggedIn(true);
    checkConnection();
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      setDbStatus(error ? 'offline' : 'online');
    } catch { setDbStatus('offline'); }
  };

  const fetchStats = async () => {
    const { count: eCount } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: vCount } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: aCount } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: eCount || 0, videos: vCount || 0, articles: aCount || 0 });
  };

  const fetchItems = async () => {
    setLoading(true);
    let table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    if (activeTab === 'dashboard') { setLoading(false); return; }

    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else { alert('Acesso negado!'); }
  };

  // Generic Save/Update Function
  const handleSave = async (e: React.FormEvent, table: string, formData: any, setForm: any, defaultForm: any) => {
    e.preventDefault();
    setLoading(true);
    try {
      let error;
      if (editingId) {
        const { error: err } = await supabase.from(table).update(formData).eq('id', editingId);
        error = err;
      } else {
        const { error: err } = await supabase.from(table).insert([formData]);
        error = err;
      }

      if (error) throw error;

      alert(editingId ? '✅ Atualizado com sucesso!' : '✅ Publicado com sucesso!');
      setForm(defaultForm);
      setEditingId(null);
      fetchItems();
      fetchStats();
    } catch (err: any) {
      alert('Erro: ' + err.message);
    } finally { setLoading(false); }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Excluir este item permanentemente?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      fetchItems();
      fetchStats();
    } catch (err: any) { alert(err.message); }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-card-dark border border-white/10 rounded-3xl p-8 shadow-2xl">
          <div className="flex justify-center mb-6"><span className="material-symbols-outlined text-primary text-5xl">surround_sound</span></div>
          <h2 className="text-2xl font-black text-center mb-8 text-white uppercase">Login Master</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="Usuário" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none focus:border-primary" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="Senha" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none focus:border-primary" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-bold uppercase hover:bg-primary-dark">Entrar</button>
            <button type="button" onClick={onClose} className="w-full text-white/40 text-xs py-2 uppercase">Voltar ao site</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      <aside className="w-64 bg-card-dark border-r border-white/5 p-6 flex flex-col gap-8 shrink-0">
        <div className="flex items-center gap-2"><span className="material-symbols-outlined text-primary">admin_panel_settings</span><h1 className="font-black text-sm uppercase">Gestão Master</h1></div>
        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Dashboard',i:'dashboard'},{id:'eventos',l:'Agenda',i:'calendar_month'},{id:'videos',l:'Vídeos',i:'video_library'},{id:'posts',l:'Editorial',i:'article'}].map(t => (
            <button key={t.id} onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === t.id ? 'bg-primary text-white' : 'text-white/40 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-sm">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>
        <button onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="mt-auto flex items-center gap-3 px-4 py-3 text-red-500 text-[10px] font-black uppercase hover:bg-red-500/10 rounded-xl">
           <span className="material-symbols-outlined text-sm">logout</span> Sair
        </button>
      </aside>

      <main className="flex-1 overflow-y-auto p-10 bg-noise relative">
        <header className="flex justify-between items-center mb-12">
            <h2 className="text-4xl font-black uppercase">{editingId ? `Editando ${activeTab}` : activeTab}</h2>
            <button onClick={onClose} className="px-6 py-2 bg-primary rounded-full text-[10px] font-black uppercase">Visualizar Site</button>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {[{ label: 'Eventos', val: stats.events, icon: 'event' }, { label: 'Vídeos', val: stats.videos, icon: 'play_circle' }, { label: 'Editorial', val: stats.articles, icon: 'auto_stories' }].map((s, idx) => (
              <div key={idx} className="bg-card-dark p-8 rounded-[2rem] border border-white/5 flex items-center justify-between">
                <div><p className="text-[10px] font-black uppercase text-white/30 mb-1">{s.label}</p><p className="text-4xl font-black">{s.val}</p></div>
                <span className="material-symbols-outlined text-4xl text-primary opacity-20">{s.icon}</span>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'eventos' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <form onSubmit={(e) => handleSave(e, 'events', eventForm, setEventForm, { day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' })} className="bg-card-dark p-8 rounded-[2rem] border border-white/10 space-y-4 h-fit">
              <h3 className="text-primary font-black uppercase text-xs mb-4">{editingId ? 'Atualizar Evento' : 'Novo Evento'}</h3>
              <div className="grid grid-cols-2 gap-4">
                <input type="text" placeholder="Dia (15)" className="bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} required />
                <input type="text" placeholder="Mês (DEZ)" className="bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} required />
              </div>
              <input type="text" placeholder="Título da Roda" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} required />
              <input type="text" placeholder="Local/Cidade" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} required />
              <input type="text" placeholder="URL da Capa" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.image_url} onChange={e => setEventForm({...eventForm, image_url: e.target.value})} required />
              <input type="text" placeholder="Link de Ingressos/Venda" className="w-full bg-white/5 border border-primary/30 rounded-xl p-3 text-white outline-none" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
              <div className="flex gap-2">
                <button type="submit" disabled={loading} className="flex-1 bg-primary py-4 rounded-xl font-black uppercase text-white">{editingId ? 'Salvar Alterações' : 'Publicar na Agenda'}</button>
                {editingId && <button type="button" onClick={() => {setEditingId(null); setEventForm({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' });}} className="bg-white/5 px-6 rounded-xl font-black uppercase text-xs">Cancelar</button>}
              </div>
            </form>
            <div className="space-y-3">
              <h4 className="text-[10px] font-black uppercase text-white/30 mb-2">Eventos Publicados</h4>
              {items.map(i => (
                <div key={i.id} className="bg-card-dark p-4 rounded-xl border border-white/5 flex justify-between items-center group">
                  <div className="flex flex-col"><span className="text-xs font-bold uppercase">{i.title}</span><span className="text-[9px] text-white/40">{i.day} {i.month}</span></div>
                  <div className="flex gap-2">
                    <button onClick={() => startEdit(i)} className="text-primary p-2 hover:bg-primary/10 rounded-lg"><span className="material-symbols-outlined text-sm">edit</span></button>
                    <button onClick={() => handleDelete(i.id)} className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg"><span className="material-symbols-outlined text-sm">delete</span></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'videos' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <form onSubmit={(e) => handleSave(e, 'videos', videoForm, setVideoForm, { title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' })} className="bg-card-dark p-8 rounded-[2rem] border border-white/10 space-y-4 h-fit">
              <h3 className="text-primary font-black uppercase text-xs mb-4">{editingId ? 'Atualizar Vídeo' : 'Novo Vídeo'}</h3>
              <input type="text" placeholder="Título" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} required />
              <input type="text" placeholder="Link YouTube/Vimeo" className="w-full bg-white/5 border border-primary/30 rounded-xl p-3 text-white outline-none" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} required />
              <input type="text" placeholder="Thumbnail URL" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={videoForm.thumbnail} onChange={e => setVideoForm({...videoForm, thumbnail: e.target.value})} required />
              <div className="flex gap-2">
                <button type="submit" disabled={loading} className="flex-1 bg-primary py-4 rounded-xl font-black uppercase text-white">{editingId ? 'Salvar Vídeo' : 'Adicionar à Galeria'}</button>
