            <form onSubmit={(e) => handleSave(e, 'articles', postForm, setPostForm, { title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' })} className="bg-card-dark p-8 rounded-[2rem] border border-white/10 space-y-4 h-fit">
              <h3 className="text-primary font-black uppercase text-xs mb-4">{editingId ? 'Atualizar Artigo' : 'Nova História'}</h3>
              <input type="text" placeholder="Título" className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-white font-bold" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} required />
              <input type="text" placeholder="Resumo curto" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} required />
              <textarea placeholder="Conteúdo completo..." className="w-full h-48 bg-white/5 border border-white/10 rounded-xl p-4 text-white resize-none" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} required />
              <input type="text" placeholder="URL da Capa" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white" value={postForm.image_url} onChange={e => setPostForm({...postForm, image_url: e.target.value})} required />
              <div className="flex gap-2">
                <button type="submit" disabled={loading} className="flex-1 bg-primary py-4 rounded-xl font-black uppercase text-white">{editingId ? 'Salvar Artigo' : 'Publicar Editorial'}</button>
                {editingId && <button type="button" onClick={() => {setEditingId(null); setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });}} className="bg-white/5 px-6 rounded-xl font-black uppercase text-xs">Cancelar</button>}
              </div>
            </form>
            <div className="space-y-3">
              {items.map(i => (
                <div key={i.id} className="bg-card-dark p-4 rounded-xl border border-white/5 flex justify-between items-center group">
                  <span className="text-xs font-bold line-clamp-1">{i.title}</span>
                  <div className="flex gap-2">
                    <button onClick={() => startEdit(i)} className="text-primary p-2 hover:bg-primary/10 rounded-lg"><span className="material-symbols-outlined text-sm">edit</span></button>
                    <button onClick={() => handleDelete(i.id)} className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg"><span className="material-symbols-outlined text-sm">delete</span></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

