                      <input type="text" placeholder="Mês (ex: DEZ)" className="bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} required />
                    </div>
                    <input type="text" placeholder="Título do Evento" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} required />
                    <input type="text" placeholder="Local" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} required />
                    <input type="text" placeholder="URL da Capa" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.image_url} onChange={e => setEventForm({...eventForm, image_url: e.target.value})} required />
                    <input type="text" placeholder="Link de Ingressos (URL Completa)" className="w-full bg-white/5 border border-primary/30 rounded-xl p-3 text-white outline-none" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
