                    <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} required />
                    <input type="text" placeholder="Link do YouTube" className="w-full bg-white/5 border border-primary/30 rounded-xl p-3 text-white outline-none" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} required />
                    <input type="text" placeholder="Thumbnail (URL)" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={videoForm.thumbnail} onChange={e => setVideoForm({...videoForm, thumbnail: e.target.value})} required />
                  </>
                )}

                {activeTab === 'posts' && (
                  <>
                    <input type="text" placeholder="Título do Post" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none font-bold" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} required />
                    <input type="text" placeholder="Resumo" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} required />
                    <textarea placeholder="Conteúdo..." className="w-full h-40 bg-white/5 border border-white/10 rounded-xl p-3 text-white resize-none" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} required />
                    <input type="text" placeholder="Imagem de Capa (URL)" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={postForm.image_url} onChange={e => setPostForm({...postForm, image_url: e.target.value})} required />
                  </>
                )}

                <div className="flex gap-2">
                  <button type="submit" disabled={loading} className="flex-1 bg-primary py-4 rounded-xl font-black uppercase text-white hover:bg-primary-dark transition-colors">{loading ? 'Aguarde...' : editingId ? 'Salvar Alterações' : 'Publicar Agora'}</button>
                  {editingId && <button type="button" onClick={() => { setEditingId(null); setEventForm({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' }); setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' }); setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' }); }} className="bg-white/10 px-6 rounded-xl font-black uppercase text-xs">Cancelar</button>}
                </div>
              </form>
            </div>

            <div className="space-y-4">
              <h4 className="text-[10px] font-black uppercase text-white/30 tracking-widest">Itens Publicados</h4>
              <div className="space-y-2">
                {items.length === 0 ? <p className="text-white/10 text-xs">Nenhum item encontrado.</p> : items.map(i => (
                  <div key={i.id} className="bg-card-dark p-4 rounded-xl border border-white/5 flex justify-between items-center group">
                    <div className="flex flex-col overflow-hidden">
                      <span className="text-xs font-bold uppercase truncate">{i.title}</span>
                      {i.day && <span className="text-[8px] text-white/30">{i.day} {i.month}</span>}
                    </div>
                    <div className="flex gap-2 shrink-0">
                      <button onClick={() => startEdit(i)} className="text-primary p-2 hover:bg-primary/10 rounded-lg"><span className="material-symbols-outlined text-sm">edit</span></button>
                      <button onClick={() => handleDelete(i.id)} className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg"><span className="material-symbols-outlined text-sm">delete</span></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

