  return (
    <article className={`group relative w-full md:${width} ${isStart ? 'self-start' : 'self-end'} bg-card-dark rounded-xl flex flex-col md:flex-row overflow-hidden hover:bg-surface-brown transition-all duration-500 border border-white/5 hover:border-primary/30`}>
      <div className={`w-full md:w-32 bg-white/5 flex flex-row md:flex-col items-center justify-center p-4 gap-2 border-b md:border-b-0 md:border-r border-white/10 shrink-0`}>
        <span className="text-white/60 font-bold text-lg uppercase tracking-widest">{month}</span>
        <span className="text-white font-black text-4xl md:text-5xl">{day}</span>
      </div>

      <div className="flex-1 p-6 flex flex-col justify-between gap-6">
        <div>
          <div className="flex justify-between items-start mb-2">
            {label && <span className="bg-primary/20 text-primary text-[10px] font-bold px-2 py-1 rounded uppercase">{label}</span>}
            <span className="material-symbols-outlined text-white/30 hover:text-primary transition-colors cursor-pointer">favorite</span>
          </div>
          <h3 className="text-2xl font-bold text-white mb-2 uppercase tracking-tighter group-hover:text-primary">{title}</h3>
          <div className="flex items-center gap-2 text-white/60 text-sm">
            <span className="material-symbols-outlined text-lg">location_on</span>
            <span>{location}</span>
          </div>
        </div>

        <div className="flex items-center justify-between mt-auto">
          <p className="text-[10px] font-black uppercase text-white/40">{price || 'ENTRADA FRANCA'}</p>
          <button onClick={handleAction} className={`bg-primary text-white text-[10px] font-black px-6 py-3 rounded-lg transition-all hover:scale-105 uppercase tracking-widest`}>
            {ticket_url ? 'INGRESSOS' : 'SAIBA MAIS'}
