        </div>
      </div>

      <div className="w-full md:w-64 h-48 md:h-auto shrink-0 relative overflow-hidden order-first md:order-last">
        <img src={image} className="absolute inset-0 w-full h-full object-cover opacity-70 group-hover:scale-110 transition-transform duration-1000" alt={title} />
