import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  // Files for Upload
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') setIsLoggedIn(true);
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const fetchStats = async () => {
    const { count: eCount } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: vCount } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: aCount } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: eCount || 0, videos: vCount || 0, articles: aCount || 0 });
  };

  const fetchItems = async () => {
    setLoading(true);
    let table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    if (activeTab === 'dashboard') { setLoading(false); return; }

    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err) { console.error("Erro ao buscar itens:", err); } finally { setLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else { alert('Acesso negado!'); }
  };

  // Helper to upload file to Supabase Storage
  const uploadImage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}.${fileExt}`;
    const filePath = `${fileName}`;

    const { error: uploadError } = await supabase.storage
      .from('uploads')
      .upload(filePath, file);

    if (uploadError) throw uploadError;

    const { data } = supabase.storage
      .from('uploads')
      .getPublicUrl(filePath);

    return data.publicUrl;
  };

  const sanitizeData = (data: any) => {
    const cleaned = { ...data };
    delete cleaned.id;
    delete cleaned.created_at;
    return cleaned;
  };

  const handleSave = async (e: React.FormEvent, table: string, formData: any, setForm: any, defaultForm: any) => {
    e.preventDefault();
    setLoading(true);

    try {
      let finalImageUrl = formData.image_url || formData.thumbnail;

      // If a new file is selected, upload it first
      if (selectedFile) {
        finalImageUrl = await uploadImage(selectedFile);
      }

      const payload = sanitizeData(formData);
      if (table === 'events' || table === 'articles') payload.image_url = finalImageUrl;
      if (table === 'videos') payload.thumbnail = finalImageUrl;

      let error;
      if (editingId) {
        const { error: err } = await supabase.from(table).update(payload).eq('id', editingId);
        error = err;
      } else {
        const { error: err } = await supabase.from(table).insert([payload]);
        error = err;
      }

      if (error) throw error;

      alert('✅ Sucesso!');
      setForm(defaultForm);
      setEditingId(null);
      setSelectedFile(null);
      fetchItems();
      fetchStats();
    } catch (err: any) {
      console.error("Erro:", err);
      alert('Erro ao salvar: ' + (err.message || 'Verifique se o bucket "uploads" existe no Supabase.'));
    } finally { setLoading(false); }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Excluir permanentemente?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      fetchItems();
      fetchStats();
    } catch (err: any) { alert(err.message); }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-card-dark border border-white/10 rounded-3xl p-8 shadow-2xl">
          <h2 className="text-2xl font-black text-center mb-8 text-white uppercase tracking-tighter">Login Master</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="Usuário" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="Senha" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-bold uppercase">Entrar</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      <aside className="w-64 bg-card-dark border-r border-white/5 p-6 flex flex-col gap-8 shrink-0">
        <div className="flex items-center gap-2 font-black text-sm uppercase"><span className="material-symbols-outlined text-primary">admin_panel_settings</span> Gestão Master</div>
        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'dashboard'},{id:'eventos',l:'Agenda',i:'calendar_month'},{id:'videos',l:'Vídeos',i:'video_library'},{id:'posts',l:'Editorial',i:'article'}].map(t => (
            <button key={t.id} onClick={() => { setActiveTab(t.id as any); setEditingId(null); setSelectedFile(null); }} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === t.id ? 'bg-primary text-white' : 'text-white/40 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-sm">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>
        <button onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="mt-auto flex items-center gap-3 px-4 py-3 text-red-500 text-[10px] font-black uppercase">Sair</button>
      </aside>

      <main className="flex-1 overflow-y-auto p-10 relative">
        <header className="flex justify-between items-center mb-12">
            <h2 className="text-4xl font-black uppercase">{editingId ? `Editando Registro` : activeTab}</h2>
            <button onClick={onClose} className="px-6 py-2 bg-primary rounded-full text-[10px] font-black uppercase">Voltar ao Site</button>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {[{ label: 'Eventos', val: stats.events, icon: 'event' }, { label: 'Vídeos', val: stats.videos, icon: 'play_circle' }, { label: 'Artigos', val: stats.articles, icon: 'auto_stories' }].map((s, idx) => (
              <div key={idx} className="bg-card-dark p-8 rounded-3xl border border-white/5 flex items-center justify-between">
                <div><p className="text-[10px] font-black uppercase text-white/30 mb-1">{s.label}</p><p className="text-4xl font-black">{s.val}</p></div>
                <span className="material-symbols-outlined text-4xl text-primary opacity-20">{s.icon}</span>
              </div>
            ))}
          </div>
        )}

        {(activeTab === 'eventos' || activeTab === 'videos' || activeTab === 'posts') && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <div className="space-y-6">
              <form 
                onSubmit={(e) => {
                  if(activeTab === 'eventos') handleSave(e, 'events', eventForm, setEventForm, { day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' });
                  if(activeTab === 'videos') handleSave(e, 'videos', videoForm, setVideoForm, { title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
                  if(activeTab === 'posts') handleSave(e, 'articles', postForm, setPostForm, { title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });
                }} 
                className="bg-card-dark p-8 rounded-3xl border border-white/10 space-y-4"
              >
                <h3 className="text-primary font-black uppercase text-xs mb-4">{editingId ? 'Atualizar' : 'Novo Cadastro'}</h3>

                {/* Upload Image Section */}
                <div className="p-4 bg-white/5 border border-dashed border-white/10 rounded-2xl text-center">
                  <input type="file" id="fileUpload" className="hidden" accept="image/*" onChange={(e) => setSelectedFile(e.target.files?.[0] || null)} />
                  <label htmlFor="fileUpload" className="cursor-pointer flex flex-col items-center gap-2">
                    <span className="material-symbols-outlined text-3xl text-primary">{selectedFile ? 'check_circle' : 'add_photo_alternate'}</span>
                    <span className="text-[10px] font-black uppercase tracking-widest">
                      {selectedFile ? `Arquivo: ${selectedFile.name}` : 'Upload de Imagem (Recomendado)'}
                    </span>
                  </label>
                </div>

                {activeTab === 'eventos' && (
                  <>
                    <div className="grid grid-cols-2 gap-4">
                      <input type="text" placeholder="Dia (ex: 15)" className="bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} required />
                      <input type="text" placeholder="Mês (ex: DEZ)" className="bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} required />
                    </div>
                    <input type="text" placeholder="Título da Roda" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} required />
                    <input type="text" placeholder="Local" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} required />
                    <input type="text" placeholder="URL da Capa (ou use upload acima)" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={eventForm.image_url} onChange={e => setEventForm({...eventForm, image_url: e.target.value})} />
                    <input type="text" placeholder="Link de Ingressos" className="w-full bg-white/5 border border-primary/30 rounded-xl p-3 text-white outline-none" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
                  </>
                )}

                {activeTab === 'videos' && (
                  <>
                    <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} required />
                    <input type="text" placeholder="Link do YouTube" className="w-full bg-white/5 border border-primary/30 rounded-xl p-3 text-white outline-none" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} required />
                    <input type="text" placeholder="URL Thumbnail (ou use upload acima)" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={videoForm.thumbnail} onChange={e => setVideoForm({...videoForm, thumbnail: e.target.value})} />
                  </>
                )}

                {activeTab === 'posts' && (
                  <>
                    <input type="text" placeholder="Título" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none font-bold" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} required />
                    <input type="text" placeholder="Resumo" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} required />
                    <textarea placeholder="Conteúdo..." className="w-full h-40 bg-white/5 border border-white/10 rounded-xl p-3 text-white resize-none" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} required />
                    <input type="text" placeholder="URL Capa (ou use upload acima)" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-white outline-none" value={postForm.image_url} onChange={e => setPostForm({...postForm, image_url: e.target.value})} />
                  </>
                )}

                <div className="flex gap-2">
                  <button type="submit" disabled={loading} className="flex-1 bg-primary py-4 rounded-xl font-black uppercase text-white hover:bg-primary-dark transition-colors">{loading ? 'Enviando...' : 'Salvar Registro'}</button>
                  {editingId && <button type="button" onClick={() => { setEditingId(null); setSelectedFile(null); }} className="bg-white/10 px-6 rounded-xl font-black uppercase text-xs">Cancelar</button>}
                </div>
              </form>
            </div>

            <div className="space-y-4">
              <h4 className="text-[10px] font-black uppercase text-white/30 tracking-widest">Publicados</h4>
              <div className="space-y-2">
                {items.map(i => (
                  <div key={i.id} className="bg-card-dark p-4 rounded-xl border border-white/5 flex justify-between items-center group">
                    <div className="flex flex-col overflow-hidden">
                      <span className="text-xs font-bold uppercase truncate">{i.title}</span>
                      <span className="text-[8px] text-white/30 truncate">{i.image_url || i.thumbnail}</span>
                    </div>
                    <div className="flex gap-2 shrink-0">
                      <button onClick={() => startEdit(i)} className="text-primary p-2 hover:bg-primary/10 rounded-lg"><span className="material-symbols-outlined text-sm">edit</span></button>
                      <button onClick={() => handleDelete(i.id)} className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg"><span className="material-symbols-outlined text-sm">delete</span></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';

interface VideoData {
  id: string;
  title: string;
  category: string;
  thumbnail: string;
  video_url: string;
}

const WatchSection: React.FC<{ onViewAll: () => void }> = ({ onViewAll }) => {
  const [videos, setVideos] = useState<VideoData[]>([]);
  const [selectedVideo, setSelectedVideo] = useState<string | null>(null);

  useEffect(() => {
    async function fetchRecentVideos() {
      const { data } = await supabase.from('videos').select('*').limit(3).order('created_at', { ascending: false });
      if (data) setVideos(data);
    }
    fetchRecentVideos();
  }, []);

  const getYouTubeId = (url: string) => {
    // regex atualizada para suportar watch, embed, shorts e youtu.be
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=|shorts\/)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const getEmbedUrl = (url: string) => {
    const ytId = getYouTubeId(url);
    if (ytId) return `https://www.youtube.com/embed/${ytId}?autoplay=1&rel=0&modestbranding=1`;

    if (url.includes('vimeo.com/')) {
      const vimeoId = url.split('/').pop()?.split('?')[0];
      return `https://player.vimeo.com/video/${vimeoId}?autoplay=1`;
    }
    return url;
  };

  return (
    <section className="max-w-7xl mx-auto px-6 mb-32" id="assista">
      {selectedVideo && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-fade-in">
          <button onClick={() => setSelectedVideo(null)} className="absolute top-10 right-10 text-white hover:text-primary transition-colors">
            <span className="material-symbols-outlined text-4xl">close</span>
          </button>
          <div className="w-full max-w-5xl aspect-video rounded-3xl overflow-hidden bg-black shadow-2xl border border-white/10">
            <iframe 
              src={getEmbedUrl(selectedVideo)} 
              className="w-full h-full" 
              allow="autoplay; encrypted-media; picture-in-picture" 
              allowFullScreen
              title="Video Player"
            ></iframe>
          </div>
        </div>
      )}

      <div className="flex items-end justify-between mb-12 border-b border-white/5 pb-6">
        <h2 className="text-4xl md:text-6xl font-black text-white tracking-tighter flex items-center gap-4 uppercase">
          <span className="material-symbols-outlined text-primary text-5xl md:text-7xl filled">play_circle</span>
          Assista
        </h2>
        <button onClick={onViewAll} className="text-primary hover:text-white transition-colors font-bold text-xs uppercase tracking-widest flex items-center gap-2">
          Ver acervo completo
          <span className="material-symbols-outlined text-lg">arrow_right_alt</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 auto-rows-[300px]">
        {videos.length > 0 ? (
          <>
            <div onClick={() => setSelectedVideo(videos[0].video_url)} className="cursor-pointer md:col-span-2 md:row-span-2 relative group overflow-hidden rounded-[2.5rem] bg-card-dark border border-white/5">
              <img src={videos[0].thumbnail} className="absolute inset-0 w-full h-full object-cover opacity-60 transition-transform duration-1000 group-hover:scale-105" alt={videos[0].title} />
              <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent"></div>
              <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <div className="bg-primary text-white p-6 rounded-full shadow-2xl"><span className="material-symbols-outlined text-4xl filled">play_arrow</span></div>
              </div>
              <div className="absolute bottom-0 left-0 p-10">
                <span className="text-primary text-[10px] font-black uppercase mb-2 block">{videos[0].category}</span>
                <h3 className="text-3xl font-black text-white uppercase tracking-tighter">{videos[0].title}</h3>
              </div>
            </div>

            {videos.slice(1).map(video => (
              <div key={video.id} onClick={() => setSelectedVideo(video.video_url)} className="cursor-pointer relative group overflow-hidden rounded-[2rem] bg-card-dark border border-white/5">
                <img src={video.thumbnail} className="absolute inset-0 w-full h-full object-cover opacity-50 group-hover:opacity-80 transition-all" alt={video.title} />
                <div className="absolute bottom-0 p-6">
                  <span className="text-primary text-[10px] font-black uppercase mb-1 block">{video.category}</span>
                  <h3 className="text-xl font-bold text-white uppercase">{video.title}</h3>
                </div>
              </div>
            ))}
          </>
        ) : (
          <div className="col-span-full py-20 text-center text-white/10 uppercase font-black text-xs">Nenhum vídeo publicado ainda.</div>
        )}
      </div>
    </section>
  );
};

export default WatchSection;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'online' | 'offline' | 'checking'>('checking');

  // Files for Upload
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') setIsLoggedIn(true);
    checkConnection();
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) {
        console.error("Erro de conexão:", error);
        setDbStatus('offline');
      } else {
        setDbStatus('online');
      }
    } catch (err) {
      setDbStatus('offline');
    }
  };

  const fetchStats = async () => {
    try {
      const { count: eCount } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: vCount } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: aCount } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: eCount || 0, videos: vCount || 0, articles: aCount || 0 });
    } catch (err) {
      console.warn("Erro ao buscar estatísticas. Verifique as tabelas.");
    }
  };

  const fetchItems = async () => {
    setLoading(true);
    let table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    if (activeTab === 'dashboard') { setLoading(false); return; }

    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      console.error(`Erro na tabela ${table}:`, err.message);
    } finally { setLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else { alert('Acesso negado!'); }
  };

  const uploadImage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
    const filePath = `${fileName}`;

    const { error: uploadError } = await supabase.storage
      .from('uploads')
      .upload(filePath, file);

    if (uploadError) {
      console.error("Erro no upload:", uploadError);
      throw new Error(`Erro no Storage: ${uploadError.message}. Verifique se o bucket 'uploads' é público.`);
    }

    const { data } = supabase.storage
      .from('uploads')
      .getPublicUrl(filePath);

    return data.publicUrl;
  };

  const sanitizePayload = (data: any) => {
    const payload = { ...data };
    // Removemos campos que o Supabase não aceita em um insert/update direto
    delete payload.id;
    delete payload.created_at;
    return payload;
  };

  const handleSave = async (e: React.FormEvent, table: string, formData: any, setForm: any, defaultForm: any) => {
    e.preventDefault();
    setLoading(true);

    try {
      let finalImageUrl = table === 'videos' ? formData.thumbnail : formData.image_url;

      // Se houver arquivo selecionado, faz o upload primeiro
      if (selectedFile) {
        finalImageUrl = await uploadImage(selectedFile);
      }

      const payload = sanitizePayload(formData);

      // Atribui a URL final ao campo correto
      if (table === 'videos') {
        payload.thumbnail = finalImageUrl;
      } else {
        payload.image_url = finalImageUrl;
      }

      let result;
      if (editingId) {
        result = await supabase.from(table).update(payload).eq('id', editingId);
      } else {
        result = await supabase.from(table).insert([payload]);
      }

      if (result.error) throw result.error;

      alert('✅ Publicado com sucesso no Tem Samba Aí!');
      setForm(defaultForm);
      setEditingId(null);
      setSelectedFile(null);
      fetchItems();
      fetchStats();
    } catch (err: any) {
      console.error("Erro Fatal:", err);
      alert(`⚠️ FALHA NO SISTEMA:\n\n${err.message || 'Erro desconhecido'}\n\nVerifique se as tabelas existem no seu Supabase.`);
    } finally { setLoading(false); }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Deseja realmente excluir? Esta ação é irreversível.')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      fetchItems();
      fetchStats();
    } catch (err: any) { alert("Erro ao deletar: " + err.message); }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-4 bg-noise">
        <div className="w-full max-w-md bg-card-dark border border-white/10 rounded-3xl p-8 shadow-2xl">
          <div className="flex justify-center mb-6">
            <span className="material-symbols-outlined text-primary text-5xl filled">surround_sound</span>
          </div>
          <h2 className="text-2xl font-black text-center mb-8 text-white uppercase tracking-tighter">Acesso Master</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="Usuário" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none focus:border-primary" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="Senha" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white outline-none focus:border-primary" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-bold uppercase hover:bg-primary-dark transition-all">Entrar no Painel</button>
            <button type="button" onClick={onClose} className="w-full text-white/40 text-[10px] py-2 uppercase tracking-widest">Voltar ao Site</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      <aside className="w-64 bg-card-dark border-r border-white/5 p-6 flex flex-col gap-8 shrink-0 relative z-20 shadow-2xl">
        <div className="flex items-center gap-2 font-black text-sm uppercase">
          <span className="material-symbols-outlined text-primary">admin_panel_settings</span> 
          <span>Gestão Master</span>
        </div>

        <div className="px-4 py-2 bg-white/5 rounded-xl border border-white/10 flex items-center gap-3">
          <div className={`w-2 h-2 rounded-full ${dbStatus === 'online' ? 'bg-green-500 shadow-[0_0_10px_green]' : dbStatus === 'checking' ? 'bg-yellow-500 animate-pulse' : 'bg-red-500'}`}></div>
          <span className="text-[9px] font-black uppercase tracking-widest text-white/40">Status DB: {dbStatus}</span>
        </div>

        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'dashboard'},{id:'eventos',l:'Agenda',i:'calendar_month'},{id:'videos',l:'Vídeos',i:'video_library'},{id:'posts',l:'Editorial',i:'article'}].map(t => (
            <button key={t.id} onClick={() => { setActiveTab(t.id as any); setEditingId(null); setSelectedFile(null); }} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-white/40 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-sm">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>

        <button onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="mt-auto flex items-center gap-3 px-4 py-3 text-red-500 text-[10px] font-black uppercase hover:bg-red-500/10 rounded-xl transition-all">
           <span className="material-symbols-outlined text-sm">logout</span> Sair
        </button>
      </aside>

      <main className="flex-1 overflow-y-auto p-10 relative bg-noise">
        <header className="flex justify-between items-center mb-12">
            <div>
              <h2 className="text-4xl font-black uppercase tracking-tighter">{editingId ? `Editando` : activeTab}</h2>
              <p className="text-[10px] text-white/30 uppercase tracking-[0.3em] mt-1">Sincronizado com Supabase Cloud</p>
            </div>
            <button onClick={onClose} className="px-6 py-2 bg-primary/20 border border-primary/40 rounded-full text-[10px] font-black uppercase hover:bg-primary hover:text-white transition-all">Ver Site</button>
        </header>

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-fade-in">
            {[{ label: 'Eventos Ativos', val: stats.events, icon: 'event' }, { label: 'Vídeos na Galeria', val: stats.videos, icon: 'play_circle' }, { label: 'Crônicas Escritas', val: stats.articles, icon: 'auto_stories' }].map((s, idx) => (
              <div key={idx} className="bg-card-dark p-8 rounded-[2rem] border border-white/5 flex items-center justify-between group hover:border-primary/20 transition-all">
                <div><p className="text-[10px] font-black uppercase text-white/30 mb-1">{s.label}</p><p className="text-5xl font-black">{s.val}</p></div>
                <span className="material-symbols-outlined text-5xl text-primary opacity-10 group-hover:opacity-40 transition-all filled">{s.icon}</span>
              </div>
            ))}
          </div>
        )}

        {(activeTab === 'eventos' || activeTab === 'videos' || activeTab === 'posts') && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-5 space-y-6">
              <form 
                onSubmit={(e) => {
                  if(activeTab === 'eventos') handleSave(e, 'events', eventForm, setEventForm, { day: '', month: '', title: '', location: '', image_url: '', featured: false, price: '', label: '', ticket_url: '' });
                  if(activeTab === 'videos') handleSave(e, 'videos', videoForm, setVideoForm, { title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
                  if(activeTab === 'posts') handleSave(e, 'articles', postForm, setPostForm, { title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });
                }} 
                className="bg-card-dark p-8 rounded-[2.5rem] border border-white/10 space-y-5 shadow-2xl sticky top-0"
              >
                <h3 className="text-primary font-black uppercase text-xs mb-4 flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-primary animate-pulse"></span>
                  {editingId ? 'Atualizar Registro' : 'Novo Cadastro'}
                </h3>

                {/* Upload Image Section */}
