          </div>
        )}

        {(activeTab === 'eventos' || activeTab === 'videos' || activeTab === 'posts') && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-5">
              <form onSubmit={handleSave} className="bg-card-dark p-8 rounded-[2rem] border border-white/10 space-y-4 shadow-2xl">
