                      <input type="text" placeholder="Mês (DEZ)" className="bg-white/5 border border-white/10 rounded-xl p-4 text-white outline-none focus:border-primary" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} required />
