                          <input type="text" placeholder="Mês (ex: OUT)" className="bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} />
                        </div>
                        <input type="text" placeholder="Título do Samba" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                        <input type="text" placeholder="Local" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} />
                      </>
                    )}

                    {activeTab === 'videos' && (
                      <>
                        <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                        <input type="text" placeholder="URL do YouTube" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                        <select className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={videoForm.category} onChange={e => setVideoForm({...videoForm, category: e.target.value})}>
