                    {activeTab === 'posts' && (
                      <>
                        <input type="text" placeholder="Título do Artigo" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                        <textarea placeholder="Resumo curto..." className="w-full bg-white/5 border border-white/10 p-4 rounded-xl h-24 resize-none" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} />
                        <textarea placeholder="Texto completo..." className="w-full bg-white/5 border border-white/10 p-4 rounded-xl h-48 resize-none" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                      </>
                    )}

                    <div className="p-4 border-2 border-dashed border-white/10 rounded-2xl flex flex-col items-center gap-2 bg-white/5">
                      <input type="file" id="fileInp" className="hidden" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
                      <label htmlFor="fileInp" className="cursor-pointer text-center">
                        <span className="material-symbols-outlined text-3xl text-primary">{selectedFile ? 'check_circle' : 'photo_camera'}</span>
                        <p className="text-[10px] font-black uppercase mt-1">{selectedFile ? selectedFile.name : 'Subir Capa'}</p>
                      </label>
                    </div>

                    <button 
                      onClick={handleManualSubmit}
                      disabled={loading} 
                      className="w-full bg-primary text-white py-5 rounded-2xl font-black uppercase tracking-widest text-xs hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                    >
                      {loading ? "Processando..." : (editingId ? 'Salvar Alterações' : 'Publicar Agora')}
                    </button>
                    {editingId && <button onClick={() => setEditingId(null)} className="w-full py-2 text-[10px] font-black uppercase opacity-30">Cancelar</button>}
                  </div>
                </div>
              </div>

              <div className="lg:col-span-7 space-y-4">
                <h3 className="text-[10px] font-black uppercase tracking-widest text-white/20 mb-6">Listagem de Itens ({items.length})</h3>
                <div className="space-y-3">
                  {items.length === 0 ? <div className="text-center py-20 opacity-20 font-black uppercase text-xs">Vazio</div> : items.map(i => (
                    <div key={i.id} className="bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between group">
                      <div className="flex items-center gap-4">
                        <img src={i.thumbnail || i.image_url} className="w-12 h-12 rounded-lg object-cover opacity-50" />
                        <div className="flex flex-col truncate">
                          <span className="text-xs font-bold uppercase truncate">{i.title}</span>
                          <span className="text-[9px] text-white/20 font-bold uppercase">{i.location || i.category}</span>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => startEdit(i)} className="text-primary p-2"><span className="material-symbols-outlined text-sm">edit</span></button>
                        <button onClick={() => handleDelete(i.id)} className="text-red-500 p-2"><span className="material-symbols-outlined text-sm">delete</span></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

