                          <input type="text" placeholder="Dia (12)" className="bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} />
                          <input type="text" placeholder="Mês (OUT)" className="bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} />
                        </div>
                        <input type="text" placeholder="Título da Roda de Samba" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                        <input type="text" placeholder="Local / Cidade" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} />
                        <input type="text" placeholder="Link do Ingresso (Opcional)" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
                      </>
                    )}

                    {activeTab === 'videos' && (
                      <>
                        <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                        <input type="text" placeholder="URL do YouTube" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                        <select className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm text-white/50" value={videoForm.category} onChange={e => setVideoForm({...videoForm, category: e.target.value})}>
                          <option value="Ao Vivo">Ao Vivo</option>
                          <option value="Tutorial">Tutorial / Aula</option>
                          <option value="Entrevista">Entrevista</option>
                          <option value="Documentário">Documentário</option>
