                    )}

                    {activeTab === 'posts' && (
                      <>
                        <input type="text" placeholder="Título da Crônica / Artigo" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                        <textarea placeholder="Resumo para a vitrine (curto)" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl h-24 resize-none outline-none focus:border-primary text-sm" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} />
                        <textarea placeholder="Texto completo do artigo..." className="w-full bg-white/5 border border-white/10 p-4 rounded-xl h-48 resize-none outline-none focus:border-primary text-sm" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
