                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'checking' | 'ok' | 'error'>('checking');
  const [logs, setLogs] = useState<string[]>(["Sessão iniciada"]);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 5));
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
      checkConnection();
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { data, error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('ok');
      addLog("Conexão com Banco de Dados: OK");
    } catch (err: any) {
      setDbStatus('error');
      addLog("ERRO DE CONEXÃO: " + err.message);
    }
  };

  const fetchStats = async () => {
    try {
      const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
    } catch (err) {}
  };

  const fetchItems = async () => {
    if (activeTab === 'dashboard') return;
    setListLoading(true);
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
      addLog(`Lista ${table} atualizada`);
    } catch (err: any) {
      addLog(`Erro ao carregar lista: ${err.message}`);
    } finally { setListLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
      checkConnection();
    } else {
      alert('Usuário ou senha inválidos.');
    }
  };

  const getYTThumbnail = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=|shorts\/)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? `https://img.youtube.com/vi/${match[2]}/maxresdefault.jpg` : '';
  };

  const uploadToStorage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}-${Date.now()}.${fileExt}`;
    addLog(`Enviando arquivo: ${fileName}...`);
    const { error: uploadError } = await supabase.storage.from('uploads').upload(fileName, file);
    if (uploadError) throw new Error(`Upload Falhou: ${uploadError.message}`);
    const { data } = supabase.storage.from('uploads').getPublicUrl(fileName);
    return data.publicUrl;
  };

  const handleManualSubmit = async () => {
    if (loading) return;
    setLoading(true);
    addLog("Iniciando publicação...");

    try {
      const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };

      if (!currentData.title) {
        setLoading(false);
        addLog("Erro: Título obrigatório");
        alert("O campo Título é obrigatório.");
        return;
      }

      let finalImg = "";
      if (selectedFile) {
        finalImg = await uploadToStorage(selectedFile);
        addLog("Imagem salva com sucesso");
      } else if (activeTab === 'videos' && currentData.video_url) {
        finalImg = getYTThumbnail(currentData.video_url);
      } else {
        finalImg = activeTab === 'videos' ? currentData.thumbnail : currentData.image_url;
      }

      const payload: any = { ...currentData };
      delete payload.id;
      delete payload.created_at;

      if (activeTab === 'videos') {
        payload.thumbnail = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      } else {
        payload.image_url = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      }

      addLog(`Salvando na tabela ${table}...`);

      let response;
      if (editingId) {
        response = await supabase.from(table).update(payload).eq('id', editingId);
      } else {
        response = await supabase.from(table).insert([payload]);
      }

      if (response.error) throw new Error(response.error.message);

      addLog("✅ SUCESSO!");
      alert("Publicação realizada com sucesso!");

      setEditingId(null);
      setSelectedFile(null);
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '' });
      setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
      setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

      await fetchItems();
      await fetchStats();

    } catch (err: any) {
      addLog(`❌ ERRO: ${err.message}`);
      alert(`Falha ao publicar: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });

    document.getElementById('admin-form-container')?.scrollIntoView({ behavior: 'smooth' });
    addLog(`Editando: ${item.title}`);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Deseja realmente excluir este item?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    addLog(`Excluindo item ${id}...`);
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) {
      addLog(`Erro ao excluir: ${error.message}`);
      alert(error.message);
    } else {
      addLog("Item excluído.");
      fetchItems();
      fetchStats();
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-8 rounded-3xl shadow-2xl">
          <h2 className="text-xl font-black text-center mb-8 uppercase tracking-widest text-primary">Admin Login</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="Usuário" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="Senha" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs">Acessar Sistema</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      {/* Sidebar */}
      <aside className="w-64 bg-card-dark border-r border-white/5 p-6 flex flex-col gap-6 shrink-0">
        <div className="flex items-center gap-2 font-black text-sm uppercase text-primary mb-4">
          <span className="material-symbols-outlined">shield_person</span> 
          <span>Master Admin</span>
        </div>

        <nav className="flex flex-col gap-1">
          {[{id:'dashboard',l:'Resumo',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie'},{id:'posts',l:'Crônicas',i:'description'}].map(t => (
            <button key={t.id} type="button" onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-white/30 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-sm">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>

        <div className="mt-auto space-y-4">
          <div className="p-4 bg-white/5 rounded-2xl border border-white/5">
            <p className="text-[8px] font-black uppercase text-white/30 mb-2">Logs do Sistema</p>
            <div className="space-y-1">
              {logs.map((log, i) => (
                <p key={i} className="text-[8px] font-medium text-white/50 truncate">{log}</p>
              ))}
            </div>
          </div>
          <button type="button" onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="w-full text-red-500 text-[10px] font-black uppercase text-center py-3 border border-red-500/20 rounded-xl hover:bg-red-500/10">Sair</button>
        </div>
      </aside>

      {/* Main */}
      <main className="flex-1 overflow-y-auto p-12 bg-noise">
        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-center mb-12">
            <div>
              <h1 className="text-4xl font-black uppercase tracking-tighter">{editingId ? 'Editar Item' : (activeTab === 'dashboard' ? 'Painel de Controle' : `Gerenciar ${activeTab}`)}</h1>
              <div className="flex items-center gap-2 mt-2">
                <div className={`w-2 h-2 rounded-full ${dbStatus === 'ok' ? 'bg-green-500 animate-pulse' : dbStatus === 'checking' ? 'bg-yellow-500' : 'bg-red-500'}`}></div>
                <span className="text-[9px] font-black uppercase text-white/30 tracking-widest">
                  {dbStatus === 'ok' ? 'Banco Conectado' : dbStatus === 'checking' ? 'Verificando...' : 'Erro no Banco'}
                </span>
              </div>
            </div>
            <button type="button" onClick={onClose} className="bg-white/5 border border-white/10 px-6 py-2 rounded-full text-[10px] font-black uppercase hover:bg-primary transition-all">Fechar</button>
          </header>

          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[{l:'Eventos',v:stats.events,i:'event'},{l:'Vídeos',v:stats.videos,i:'movie'},{l:'Crônicas',v:stats.articles,i:'description'}].map((s, idx) => (
                <div key={idx} className="bg-card-dark p-8 rounded-3xl border border-white/5 flex items-center justify-between shadow-xl">
                  <div><p className="text-[10px] font-black uppercase text-white/20 mb-1">{s.l}</p><p className="text-5xl font-black">{s.v}</p></div>
                  <span className="material-symbols-outlined text-4xl text-primary/20 filled">{s.i}</span>
                </div>
              ))}
              <div className="md:col-span-3 bg-white/5 border border-white/10 p-8 rounded-3xl">
                <h4 className="font-black uppercase text-xs mb-4">Estado da Conectividade</h4>
                <button type="button" onClick={checkConnection} className="bg-primary/20 text-primary border border-primary/20 px-6 py-2 rounded-lg text-[10px] font-black uppercase hover:bg-primary hover:text-white transition-all">Testar Banco de Dados</button>
              </div>
            </div>
          )}

          {(activeTab === 'eventos' || activeTab === 'videos' || activeTab === 'posts') && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
              <div className="lg:col-span-5" id="admin-form-container">
                <div className="bg-card-dark p-8 rounded-[2.5rem] border border-white/10 space-y-4 shadow-2xl relative sticky top-0">
                  <div className="absolute top-0 left-0 w-1 h-full bg-primary"></div>

                  <div className="space-y-4">
                    {activeTab === 'eventos' && (
                      <>
                        <div className="grid grid-cols-2 gap-4">
                          <input type="text" placeholder="Dia (ex: 12)" className="bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} />
                          <input type="text" placeholder="Mês (ex: OUT)" className="bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} />
                        </div>
                        <input type="text" placeholder="Título da Roda" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                        <input type="text" placeholder="Local" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} />
                        <input type="text" placeholder="Link do Ingresso (URL)" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
                      </>
                    )}

                    {activeTab === 'videos' && (
                      <>
                        <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                        <input type="text" placeholder="URL do YouTube" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                        <select className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm text-white/50" value={videoForm.category} onChange={e => setVideoForm({...videoForm, category: e.target.value})}>
                          <option value="Ao Vivo">Ao Vivo</option>
                          <option value="Tutorial">Tutorial</option>
                        </select>
                      </>
                    )}

                    {activeTab === 'posts' && (
                      <>
                        <input type="text" placeholder="Título do Artigo" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl outline-none focus:border-primary text-sm" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                        <textarea placeholder="Resumo..." className="w-full bg-white/5 border border-white/10 p-4 rounded-xl h-24 resize-none outline-none focus:border-primary text-sm" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} />
                        <textarea placeholder="Conteúdo completo..." className="w-full bg-white/5 border border-white/10 p-4 rounded-xl h-48 resize-none outline-none focus:border-primary text-sm" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                      </>
                    )}

                    <div className="p-4 border-2 border-dashed border-white/10 rounded-2xl flex flex-col items-center gap-2 bg-white/5">
                      <input type="file" id="fileInp" className="hidden" accept="image/*" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
                      <label htmlFor="fileInp" className="cursor-pointer text-center w-full">
                        <span className="material-symbols-outlined text-3xl text-primary">{selectedFile ? 'check_circle' : 'add_a_photo'}</span>
                        <p className="text-[10px] font-black uppercase mt-1 text-white/40">{selectedFile ? selectedFile.name : 'Subir Imagem'}</p>
                      </label>
                    </div>

                    <button 
                      type="button"
                      onClick={handleManualSubmit}
                      disabled={loading} 
                      className={`w-full py-5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all flex items-center justify-center gap-3 ${loading ? 'bg-white/10 cursor-wait' : 'bg-primary text-white hover:brightness-110 active:scale-95 shadow-xl shadow-primary/20'}`}
                    >
                      {loading ? 'Salvando...' : (editingId ? 'Salvar Alterações' : 'Publicar Agora')}
                    </button>
                    {editingId && (
                      <button type="button" onClick={() => setEditingId(null)} className="w-full py-2 text-[10px] font-black uppercase opacity-30 hover:opacity-100">Cancelar</button>
                    )}
                  </div>
                </div>
              </div>

              <div className="lg:col-span-7">
                <div className="flex items-center justify-between mb-6">
                   <h3 className="text-[10px] font-black uppercase tracking-widest text-white/20">Itens Cadastrados ({items.length})</h3>
                   {listLoading && <span className="w-4 h-4 border-2 border-primary/20 border-t-primary rounded-full animate-spin"></span>}
                </div>
                <div className="space-y-3">
                  {items.length === 0 ? (
                    <div className="text-center py-20 border border-dashed border-white/5 rounded-3xl opacity-20 font-black uppercase text-xs">Vazio</div>
                  ) : items.map(i => (
                    <div key={i.id} className={`bg-card-dark p-4 rounded-2xl border border-white/5 flex items-center justify-between group hover:border-primary/40 transition-all ${editingId === i.id ? 'border-primary' : ''}`}>
                      <div className="flex items-center gap-4 overflow-hidden">
                        <img src={i.thumbnail || i.image_url} className="w-12 h-12 rounded-xl object-cover shrink-0 opacity-50 group-hover:opacity-100 transition-opacity" />
                        <div className="truncate">
                          <p className="text-xs font-bold uppercase truncate">{i.title}</p>
                          <p className="text-[9px] text-white/20 font-bold uppercase">{i.location || i.category}</p>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button type="button" onClick={() => startEdit(i)} className="text-primary p-2 hover:bg-primary/10 rounded-lg"><span className="material-symbols-outlined text-sm">edit</span></button>
                        <button type="button" onClick={() => handleDelete(i.id)} className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg"><span className="material-symbols-outlined text-sm">delete</span></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

