  const uploadToStorage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}-${Date.now()}.${fileExt}`;
    addLog(`Enviando arquivo: ${fileName}...`);

    const { error: uploadError } = await supabase.storage.from('uploads').upload(fileName, file, {
      cacheControl: '3600',
      upsert: false
    });

    if (uploadError) {
      if (uploadError.message.includes('row-level security')) {
        setShowSqlHelp(true);
        throw new Error("Erro de RLS: Você precisa configurar as permissões de Storage no Supabase.");
      }
      throw new Error(`Upload Falhou: ${uploadError.message}`);
    }

    const { data } = supabase.storage.from('uploads').getPublicUrl(fileName);
    return data.publicUrl;
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    addLog("Iniciando publicação...");

    try {
      const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };

      if (!currentData.title) {
        setLoading(false);
        addLog("Erro: Título obrigatório");
        alert("O campo Título é obrigatório.");
        return;
      }

      let finalImg = "";
      if (selectedFile) {
        finalImg = await uploadToStorage(selectedFile);
        addLog("Imagem salva com sucesso");
      } else if (activeTab === 'videos' && currentData.video_url) {
        finalImg = getYTThumbnail(currentData.video_url);
      } else {
        finalImg = activeTab === 'videos' ? currentData.thumbnail : currentData.image_url;
      }

      const payload: any = { ...currentData };
      delete payload.id;
      delete payload.created_at;

      // Sanitizar dados
      if (activeTab === 'videos') {
        payload.thumbnail = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      } else {
        payload.image_url = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      }

      addLog(`Salvando na tabela ${table}...`);

      let response;
      if (editingId) {
        response = await supabase.from(table).update(payload).eq('id', editingId);
      } else {
        response = await supabase.from(table).insert([payload]);
      }

      if (response.error) throw new Error(response.error.message);

      addLog("✅ SUCESSO!");

      // Resetar formulário
      setEditingId(null);
      setSelectedFile(null);
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
      setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
      setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

      // Atualizar lista e estatísticas
      await fetchItems();
      await fetchStats();

      alert("Publicação realizada com sucesso!");

    } catch (err: any) {
      addLog(`❌ ERRO: ${err.message}`);
      alert(`Falha ao publicar: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });

    document.getElementById('admin-form-container')?.scrollIntoView({ behavior: 'smooth' });
    addLog(`Editando: ${item.title}`);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Deseja realmente excluir este item permanentemente?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    addLog(`Excluindo item ${id}...`);
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) {
      addLog(`Erro ao excluir: ${error.message}`);
      alert(error.message);
    } else {
      addLog("Item excluído.");
      fetchItems();
      fetchStats();
    }
  };

  const sqlFixCode = `-- EXECUTE ISSO NO SQL EDITOR DO SUPABASE
-- 1. Permissões para o Storage (Imagens)
INSERT INTO storage.buckets (id, name, public) 
VALUES ('uploads', 'uploads', true)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "Acesso Publico Upload" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico View" ON storage.objects FOR SELECT USING (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico Update" ON storage.objects FOR UPDATE USING (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico Delete" ON storage.objects FOR DELETE USING (bucket_id = 'uploads');

-- 2. Permissões para as Tabelas
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interactions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Acesso Total Eventos" ON public.events FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Videos" ON public.videos FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Artigos" ON public.articles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Interacoes" ON public.interactions FOR ALL USING (true) WITH CHECK (true);`;

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-8 rounded-3xl shadow-2xl relative overflow-hidden">
          <div className="absolute -top-10 -right-10 w-32 h-32 bg-primary/10 rounded-full blur-3xl"></div>
          <h2 className="text-xl font-black text-center mb-8 uppercase tracking-widest text-primary">Acesso Master</h2>
          <form onSubmit={handleLogin} className="space-y-4 relative z-10">
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-white/30 ml-2">Usuário</label>
              <input type="text" placeholder="admin" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none focus:border-primary transition-colors" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-white/30 ml-2">Senha</label>
              <input type="password" placeholder="••••••••" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none focus:border-primary transition-colors" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            </div>
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs shadow-lg shadow-primary/20 hover:brightness-110 active:scale-95 transition-all">Entrar no Painel</button>
          </form>
          <p className="text-center text-white/10 text-[9px] mt-6 uppercase font-bold tracking-widest">Tem Samba Aí © 2025</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      {/* Sidebar */}
      <aside className="w-72 bg-card-dark border-r border-white/5 p-8 flex flex-col gap-8 shrink-0 relative">
        <div className="flex items-center gap-3 font-black text-sm uppercase text-primary">
          <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
             <span className="material-symbols-outlined text-sm">shield_person</span> 
          </div>
          <span>Mestre Admin</span>
        </div>

        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie'},{id:'posts',l:'Crônicas',i:'description'}].map(t => (
            <button key={t.id} type="button" onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-4 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-xl shadow-primary/20 scale-105' : 'text-white/30 hover:bg-white/5 hover:text-white/60'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>

        <div className="mt-auto space-y-6">
          <div className="p-5 bg-black/40 rounded-3xl border border-white/5">
            <p className="text-[9px] font-black uppercase text-white/20 mb-3 tracking-widest flex items-center gap-2">
               <span className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse"></span> Terminal de Logs
            </p>
            <div className="space-y-2 max-h-32 overflow-y-auto no-scrollbar">
              {logs.map((log, i) => (
                <p key={i} className="text-[8px] font-medium text-white/40 leading-tight border-l border-primary/20 pl-2">{log}</p>
              ))}
            </div>
          </div>
          <button type="button" onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="w-full text-red-500/60 hover:text-red-500 text-[10px] font-black uppercase text-center py-4 border border-red-500/10 rounded-2xl hover:bg-red-500/5 transition-all">Sair do Sistema</button>
        </div>
      </aside>

      {/* Main Container */}
      <main className="flex-1 overflow-y-auto p-12 bg-noise relative">
        {showSqlHelp && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/90 backdrop-blur-sm">
            <div className="bg-card-dark border border-primary/30 p-8 rounded-[2.5rem] max-w-2xl w-full shadow-2xl">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black text-primary uppercase tracking-tighter">Corrigir Permissões (RLS)</h3>
                <button onClick={() => setShowSqlHelp(false)} className="text-white/20 hover:text-white transition-colors"><span className="material-symbols-outlined">close</span></button>
              </div>
              <p className="text-white/60 text-sm mb-6 leading-relaxed">Detectamos um erro de segurança no seu banco de dados. Para que o upload de fotos funcione, você precisa copiar o código abaixo e colar no <strong>SQL Editor</strong> do seu painel Supabase e clicar em <strong>RUN</strong>.</p>
              <pre className="bg-black/60 p-4 rounded-2xl text-[10px] text-primary font-mono overflow-x-auto border border-white/10 mb-6 h-48 no-scrollbar select-all">
                {sqlFixCode}
              </pre>
              <button onClick={() => { navigator.clipboard.writeText(sqlFixCode); alert("Código copiado!"); }} className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs">Copiar Código SQL</button>
            </div>
          </div>
        )}

        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-16">
            <div>
              <p className="text-primary font-black uppercase text-[10px] tracking-[0.4em] mb-2">Administração Master</p>
              <h1 className="text-5xl font-black uppercase tracking-tighter leading-none">
                {editingId ? 'Editar Conteúdo' : (activeTab === 'dashboard' ? 'Dashboard' : `Gerenciar ${activeTab}`)}
              </h1>
            </div>
            <div className="flex items-center gap-6">
               <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-4 py-2 rounded-full">
                  <div className={`w-2 h-2 rounded-full ${dbStatus === 'ok' ? 'bg-green-500' : 'bg-red-500'} shadow-[0_0_10px_rgba(34,197,94,0.4)]`}></div>
                  <span className="text-[10px] font-black uppercase text-white/40 tracking-widest">{dbStatus === 'ok' ? 'Online' : 'Erro DB'}</span>
               </div>
               <button type="button" onClick={onClose} className="bg-white text-black px-6 py-2.5 rounded-full text-[10px] font-black uppercase hover:bg-primary hover:text-white transition-all shadow-xl">Voltar ao Site</button>
            </div>
          </header>

          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {[{l:'Eventos Ativos',v:stats.events,i:'event',c:'from-primary/20 to-transparent'},{l:'Galeria de Vídeos',v:stats.videos,i:'movie',c:'from-blue-500/10 to-transparent'},{l:'Artigos Escritos',v:stats.articles,i:'description',c:'from-green-500/10 to-transparent'}].map((s, idx) => (
                <div key={idx} className={`bg-card-dark p-10 rounded-[3rem] border border-white/5 flex flex-col gap-4 shadow-2xl relative overflow-hidden bg-gradient-to-br ${s.c}`}>
                  <span className="material-symbols-outlined text-4xl text-primary/40 absolute top-8 right-8">{s.i}</span>
                  <p className="text-[10px] font-black uppercase text-white/20 tracking-widest">{s.l}</p>
                  <p className="text-6xl font-black tracking-tighter">{s.v}</p>
                  <div className="mt-4 flex items-center gap-2 text-[9px] font-black text-primary uppercase">
                     <span>Ver detalhes</span>
                     <span className="material-symbols-outlined text-xs">arrow_forward</span>
                  </div>
                </div>
              ))}
              <div className="md:col-span-3 mt-4">
                 <button onClick={() => setShowSqlHelp(true)} className="flex items-center gap-4 bg-primary/10 border border-primary/20 p-6 rounded-3xl w-full group hover:bg-primary/20 transition-all text-left">
                    <div className="w-12 h-12 rounded-2xl bg-primary flex items-center justify-center shrink-0 shadow-lg shadow-primary/40">
                       <span className="material-symbols-outlined text-white">database</span>
                    </div>
                    <div>
                       <h4 className="font-black uppercase text-sm text-primary tracking-tight">Precisa configurar o banco de dados?</h4>
                       <p className="text-white/40 text-[10px] font-bold uppercase tracking-widest">Clique aqui para ver o código SQL de correção de permissões.</p>
                    </div>
                    <span className="material-symbols-outlined ml-auto group-hover:translate-x-2 transition-transform">chevron_right</span>
                 </button>
              </div>
            </div>
          )}

          {(activeTab === 'eventos' || activeTab === 'videos' || activeTab === 'posts') && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
              {/* Form Side */}
              <div className="lg:col-span-5" id="admin-form-container">
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/10 space-y-6 shadow-2xl relative sticky top-12 overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1.5 bg-primary"></div>

                  <div className="space-y-5">
                    {activeTab === 'eventos' && (
                      <>
                        <div className="grid grid-cols-2 gap-4">
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-white/20 ml-2">Dia (ex: 12)</label>
                            <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[9px] font-black uppercase text-white/20 ml-2">Mês (ex: OUT)</label>
                            <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold uppercase" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} />
                          </div>
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Nome da Roda de Samba</label>
                          <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Local / Endereço</label>
                          <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">URL dos Ingressos (Opcional)</label>
                          <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
                        </div>
                      </>
                    )}

                    {activeTab === 'videos' && (
                      <>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Título do Vídeo</label>
                          <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Link do YouTube</label>
                          <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Categoria</label>
                          <select className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm text-white/50 font-bold" value={videoForm.category} onChange={e => setVideoForm({...videoForm, category: e.target.value})}>
                            <option value="Ao Vivo">Ao Vivo</option>
                            <option value="Tutorial">Tutorial</option>
                            <option value="Documentário">Documentário</option>
                          </select>
                        </div>
                      </>
                    )}

                    {activeTab === 'posts' && (
                      <>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Título da Crônica</label>
                          <input type="text" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Resumo Curto (Vitrine)</label>
                          <textarea className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl h-24 resize-none outline-none focus:border-primary text-sm font-light" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} />
                        </div>
                        <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-white/20 ml-2">Texto Completo</label>
                          <textarea className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl h-48 resize-none outline-none focus:border-primary text-sm font-light" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                        </div>
                      </>
                    )}

                    <div className="p-6 border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center gap-3 bg-white/5 hover:bg-white/10 transition-colors group cursor-pointer relative">
                      <input type="file" id="fileInp" className="hidden" accept="image/*" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
                      <label htmlFor="fileInp" className="cursor-pointer text-center w-full">
                        <div className="w-12 h-12 rounded-2xl bg-primary/20 flex items-center justify-center mx-auto mb-2">
                           <span className="material-symbols-outlined text-primary">{selectedFile ? 'check_circle' : 'photo_camera'}</span>
                        </div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-white/60">
                          {selectedFile ? selectedFile.name : 'Selecionar Capa / Foto'}
                        </p>
                      </label>
                    </div>

                    <button 
                      type="button"
                      onClick={handleManualSubmit}
                      disabled={loading} 
                      className={`w-full py-5 rounded-2xl font-black uppercase tracking-[0.3em] text-xs transition-all flex items-center justify-center gap-4 ${loading ? 'bg-white/10 cursor-wait' : 'bg-primary text-white hover:scale-[1.02] active:scale-95 shadow-2xl shadow-primary/30'}`}
                    >
                      {loading ? (
                        <>
                          <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                          Processando...
                        </>
                      ) : (
                        <>
                          <span className="material-symbols-outlined text-lg">{editingId ? 'save' : 'publish'}</span>
                          {editingId ? 'Salvar Alterações' : 'Publicar Agora'}
                        </>
                      )}
                    </button>
                    {editingId && (
                      <button type="button" onClick={() => { setEditingId(null); setSelectedFile(null); }} className="w-full py-2 text-[9px] font-black uppercase opacity-20 hover:opacity-100 transition-all tracking-widest">Cancelar Edição</button>
                    )}
                  </div>
                </div>
              </div>

              {/* List Side */}
              <div className="lg:col-span-7">
                <div className="flex items-center justify-between mb-8">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/20">Registros Ativos ({items.length})</h3>
                   {listLoading && <div className="w-4 h-4 border-2 border-primary/20 border-t-primary rounded-full animate-spin"></div>}
                </div>

                <div className="space-y-4">
                  {items.length === 0 && !listLoading ? (
                    <div className="text-center py-40 bg-white/5 rounded-[3rem] border border-dashed border-white/10 opacity-30 flex flex-col items-center gap-4">
                       <span className="material-symbols-outlined text-5xl">inventory_2</span>
                       <p className="font-black uppercase text-xs tracking-widest">Nenhum item encontrado</p>
                    </div>
                  ) : items.map(i => (
                    <div key={i.id} className={`bg-card-dark p-6 rounded-[2rem] border border-white/5 flex items-center justify-between group hover:border-primary/40 transition-all animate-fade-in-up ${editingId === i.id ? 'ring-2 ring-primary border-transparent' : ''}`}>
                      <div className="flex items-center gap-6 overflow-hidden">
                        <div className="w-16 h-16 rounded-2xl bg-white/5 overflow-hidden shrink-0 border border-white/5">
                          <img src={i.thumbnail || i.image_url} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" alt={i.title} />
                        </div>
                        <div className="truncate">
                          <p className="text-sm font-black uppercase truncate tracking-tight text-white/90">{i.title}</p>
                          <p className="text-[9px] text-primary/60 font-black uppercase tracking-widest mt-1">
                             {activeTab === 'eventos' ? `${i.day} ${i.month} — ${i.location}` : i.category}
                          </p>
                        </div>
                      </div>
                      <div className="flex gap-3 shrink-0 opacity-40 group-hover:opacity-100 transition-opacity">
                        <button type="button" onClick={() => startEdit(i)} className="w-10 h-10 rounded-xl bg-white/5 text-primary hover:bg-primary hover:text-white transition-all flex items-center justify-center">
                          <span className="material-symbols-outlined text-lg">edit</span>
                        </button>
                        <button type="button" onClick={() => handleDelete(i.id)} className="w-10 h-10 rounded-xl bg-white/5 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center">
                          <span className="material-symbols-outlined text-lg">delete</span>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'checking' | 'ok' | 'error'>('checking');
  const [logs, setLogs] = useState<string[]>(["Sessão iniciada"]);
  const [showSqlHelp, setShowSqlHelp] = useState(false);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 10));
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
      checkConnection();
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('ok');
      addLog("Conexão com Banco de Dados: OK");
    } catch (err: any) {
      setDbStatus('error');
      addLog("ERRO DE CONEXÃO: " + err.message);
    }
  };

  const fetchStats = async () => {
    try {
      const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
    } catch (err) {}
  };

  const fetchItems = async () => {
    if (activeTab === 'dashboard') return;
    setListLoading(true);
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
      addLog(`Lista ${table} atualizada`);
    } catch (err: any) {
      addLog(`Erro ao carregar lista: ${err.message}`);
    } finally { setListLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
      checkConnection();
    } else {
      alert('Usuário ou senha inválidos.');
    }
  };

  const getYTThumbnail = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=|shorts\/)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? `https://img.youtube.com/vi/${match[2]}/maxresdefault.jpg` : '';
  };

  const uploadToStorage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}-${Date.now()}.${fileExt}`;
    addLog(`Tentando upload de: ${fileName}...`);

    const { error: uploadError } = await supabase.storage.from('uploads').upload(fileName, file, {
      cacheControl: '3600',
      upsert: false
    });

    if (uploadError) {
      addLog(`❌ Falha no Storage: ${uploadError.message}`);
      if (uploadError.message.includes('row-level security') || uploadError.message.includes('policy')) {
        setShowSqlHelp(true);
        throw new Error("Erro de RLS: O Supabase bloqueou o upload por falta de permissão.");
      }
      throw new Error(`Upload Falhou: ${uploadError.message}`);
    }

    const { data } = supabase.storage.from('uploads').getPublicUrl(fileName);
    return data.publicUrl;
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    addLog("Iniciando publicação...");

    try {
      const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };

      if (!currentData.title) {
        setLoading(false);
        addLog("Erro: Título ausente");
        alert("O campo Título é obrigatório.");
        return;
      }

      let finalImg = "";
      if (selectedFile) {
        finalImg = await uploadToStorage(selectedFile);
        addLog("Imagem processada com sucesso");
      } else if (activeTab === 'videos' && currentData.video_url) {
        finalImg = getYTThumbnail(currentData.video_url);
      } else {
        finalImg = activeTab === 'videos' ? currentData.thumbnail : currentData.image_url;
      }

      const payload: any = { ...currentData };
      delete payload.id;
      delete payload.created_at;

      if (activeTab === 'videos') {
        payload.thumbnail = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      } else {
        payload.image_url = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      }

      addLog(`Enviando dados para tabela: ${table}...`);

      let response;
      if (editingId) {
        response = await supabase.from(table).update(payload).eq('id', editingId);
      } else {
        response = await supabase.from(table).insert([payload]);
      }

      if (response.error) {
        addLog(`❌ Erro no Banco: ${response.error.message}`);
        throw new Error(response.error.message);
      }

      addLog("✅ Publicado com sucesso!");

      setEditingId(null);
      setSelectedFile(null);
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
      setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
      setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

      await fetchItems();
      await fetchStats();

      alert("Sucesso! O conteúdo já está no ar.");

    } catch (err: any) {
      addLog(`❌ Erro Fatal: ${err.message}`);
      alert(`Erro: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });

    document.getElementById('admin-form-container')?.scrollIntoView({ behavior: 'smooth' });
    addLog(`Modo edição: ${item.title}`);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Excluir este item permanentemente?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    addLog(`Excluindo ${id}...`);
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) {
      addLog(`Erro ao excluir: ${error.message}`);
      alert(error.message);
    } else {
      addLog("Excluído.");
      fetchItems();
      fetchStats();
    }
  };

  const sqlFixCode = `-- SCRIPT DE CORREÇÃO TOTAL (LIMPA E RECRIA PERMISSÕES)
-- 1. LIMPAR POLÍTICAS ANTIGAS (EVITA ERRO 42710)
DROP POLICY IF EXISTS "Acesso Publico Upload" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico View" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico Update" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico Delete" ON storage.objects;

DROP POLICY IF EXISTS "Acesso Total Eventos" ON public.events;
DROP POLICY IF EXISTS "Acesso Total Videos" ON public.videos;
DROP POLICY IF EXISTS "Acesso Total Artigos" ON public.articles;
DROP POLICY IF EXISTS "Acesso Total Interacoes" ON public.interactions;

-- 2. CONFIGURAR STORAGE (BUCKET 'uploads')
INSERT INTO storage.buckets (id, name, public) 
VALUES ('uploads', 'uploads', true)
ON CONFLICT (id) DO UPDATE SET public = true;

CREATE POLICY "Acesso Publico Upload" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico View" ON storage.objects FOR SELECT USING (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico Update" ON storage.objects FOR UPDATE USING (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico Delete" ON storage.objects FOR DELETE USING (bucket_id = 'uploads');

-- 3. CONFIGURAR TABELAS (PUBLICAS PARA O ADMIN)
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interactions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Acesso Total Eventos" ON public.events FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Videos" ON public.videos FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Artigos" ON public.articles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Interacoes" ON public.interactions FOR ALL USING (true) WITH CHECK (true);`;

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-8 rounded-3xl shadow-2xl">
          <h2 className="text-xl font-black text-center mb-8 uppercase tracking-widest text-primary">Acesso Master</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="admin" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none focus:border-primary" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="master-samba-2025" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none focus:border-primary" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs">Acessar Painel</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      {/* Sidebar */}
      <aside className="w-72 bg-card-dark border-r border-white/5 p-8 flex flex-col gap-8 shrink-0 relative">
        <div className="flex items-center gap-3 font-black text-sm uppercase text-primary">
          <span className="material-symbols-outlined text-sm">shield_person</span> 
          <span>Mestre Admin</span>
        </div>

        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Dashboard',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie'},{id:'posts',l:'Crônicas',i:'description'}].map(t => (
            <button key={t.id} type="button" onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-4 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-xl shadow-primary/20 scale-105' : 'text-white/30 hover:bg-white/5 hover:text-white/60'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>

        <div className="mt-auto space-y-4">
          <div className="p-4 bg-black/40 rounded-2xl border border-white/5">
            <p className="text-[8px] font-black uppercase text-white/30 mb-2">Monitor do Sistema</p>
            <div className="space-y-1 max-h-24 overflow-y-auto no-scrollbar">
              {logs.map((log, i) => (
                <p key={i} className="text-[8px] font-medium text-white/40 leading-tight truncate">{log}</p>
              ))}
            </div>
          </div>
          <button type="button" onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="w-full text-red-500/60 hover:text-red-500 text-[10px] font-black uppercase text-center py-4 border border-red-500/10 rounded-2xl">Sair</button>
        </div>
      </aside>

      {/* Main Container */}
      <main className="flex-1 overflow-y-auto p-12 bg-noise relative">
        {showSqlHelp && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-md">
            <div className="bg-card-dark border border-primary/30 p-10 rounded-[3rem] max-w-2xl w-full shadow-2xl animate-fade-in-up">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black text-primary uppercase tracking-tighter">Corrigir Erro de Permissão</h3>
                <button onClick={() => setShowSqlHelp(false)} className="text-white/20 hover:text-white transition-colors"><span className="material-symbols-outlined">close</span></button>
              </div>
              <p className="text-white/60 text-sm mb-6 leading-relaxed">
                O Supabase bloqueou o envio da foto por segurança (erro de RLS).<br/><br/>
                Para resolver, copie o código abaixo, vá ao <strong>SQL Editor</strong> do seu Supabase, cole tudo e clique em <strong>RUN</strong>.
              </p>
              <pre className="bg-black/60 p-5 rounded-2xl text-[10px] text-primary font-mono overflow-x-auto border border-white/10 mb-6 h-64 no-scrollbar select-all">
                {sqlFixCode}
              </pre>
              <button onClick={() => { navigator.clipboard.writeText(sqlFixCode); alert("Script copiado! Agora cole e execute no Supabase."); }} className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs">Copiar Script Corretor</button>
            </div>
          </div>
        )}

        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-16">
            <div>
              <p className="text-primary font-black uppercase text-[10px] tracking-[0.4em] mb-2">Administração Master</p>
              <h1 className="text-5xl font-black uppercase tracking-tighter leading-none">
                {editingId ? 'Editar Item' : (activeTab === 'dashboard' ? 'Dashboard' : `Gerenciar ${activeTab}`)}
              </h1>
            </div>
            <div className="flex items-center gap-6">
               <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-4 py-2 rounded-full">
                  <div className={`w-2 h-2 rounded-full ${dbStatus === 'ok' ? 'bg-green-500' : 'bg-red-500'} animate-pulse`}></div>
                  <span className="text-[10px] font-black uppercase text-white/40 tracking-widest">{dbStatus === 'ok' ? 'Online' : 'Erro DB'}</span>
               </div>
               <button type="button" onClick={onBack} className="bg-white text-black px-6 py-2.5 rounded-full text-[10px] font-black uppercase hover:bg-primary hover:text-white transition-all">Sair do Painel</button>
            </div>
          </header>

          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {[{l:'Eventos Ativos',v:stats.events,i:'event'},{l:'Vídeos',v:stats.videos,i:'movie'},{l:'Crônicas',v:stats.articles,i:'description'}].map((s, idx) => (
                <div key={idx} className={`bg-card-dark p-10 rounded-[3rem] border border-white/5 flex flex-col gap-4 shadow-2xl relative overflow-hidden`}>
                  <span className="material-symbols-outlined text-4xl text-primary/20 absolute top-8 right-8">{s.i}</span>
                  <p className="text-[10px] font-black uppercase text-white/20 tracking-widest">{s.l}</p>
                  <p className="text-6xl font-black tracking-tighter">{s.v}</p>
                </div>
              ))}
              <div className="md:col-span-3 mt-4">
                 <button onClick={() => setShowSqlHelp(true)} className="flex items-center gap-4 bg-primary/10 border border-primary/20 p-8 rounded-3xl w-full text-left group transition-all hover:bg-primary/20">
                    <div className="w-12 h-12 rounded-2xl bg-primary flex items-center justify-center shrink-0">
                       <span className="material-symbols-outlined text-white">build</span>
                    </div>
                    <div>
                       <h4 className="font-black uppercase text-sm text-primary">Corrigir Permissões do Banco de Dados</h4>
                       <p className="text-white/40 text-[10px] font-bold uppercase tracking-widest">Se você não consegue enviar fotos, use este script para liberar o acesso.</p>
                    </div>
                 </button>
              </div>
            </div>
          )}

          {(activeTab === 'eventos' || activeTab === 'videos' || activeTab === 'posts') && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
              <div className="lg:col-span-5" id="admin-form-container">
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/10 space-y-6 shadow-2xl relative sticky top-12 overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1.5 bg-primary"></div>

                  <div className="space-y-5">
                    {activeTab === 'eventos' && (
                      <>
                        <div className="grid grid-cols-2 gap-4">
                          <input type="text" placeholder="Dia (12)" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} />
                          <input type="text" placeholder="Mês (OUT)" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold uppercase" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} />
                        </div>
                        <input type="text" placeholder="Nome da Roda" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                        <input type="text" placeholder="Local / Cidade" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} />
                        <input type="text" placeholder="URL Ingressos (Opcional)" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={eventForm.ticket_url} onChange={e => setEventForm({...eventForm, ticket_url: e.target.value})} />
                      </>
                    )}

                    {activeTab === 'videos' && (
                      <>
                        <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                        <input type="text" placeholder="Link YouTube" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                        <select className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm text-white/50 font-bold" value={videoForm.category} onChange={e => setVideoForm({...videoForm, category: e.target.value})}>
                          <option value="Ao Vivo">Ao Vivo</option>
                          <option value="Tutorial">Tutorial</option>
                        </select>
                      </>
                    )}

                    {activeTab === 'posts' && (
                      <>
                        <input type="text" placeholder="Título" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl outline-none focus:border-primary text-sm font-bold" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                        <textarea placeholder="Resumo..." className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl h-24 resize-none outline-none focus:border-primary text-sm" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} />
                        <textarea placeholder="Texto completo..." className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl h-48 resize-none outline-none focus:border-primary text-sm" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                      </>
                    )}

                    <div className="p-6 border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center gap-2 bg-white/5 group cursor-pointer">
                      <input type="file" id="fileInp" className="hidden" accept="image/*" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
                      <label htmlFor="fileInp" className="cursor-pointer text-center w-full">
                        <span className="material-symbols-outlined text-3xl text-primary">{selectedFile ? 'check_circle' : 'photo_camera'}</span>
                        <p className="text-[10px] font-black uppercase mt-1 text-white/40">{selectedFile ? selectedFile.name : 'Subir Foto'}</p>
                      </label>
                    </div>

                    <button type="button" onClick={handleManualSubmit} disabled={loading} className={`w-full py-5 rounded-2xl font-black uppercase tracking-[0.3em] text-xs transition-all flex items-center justify-center gap-4 ${loading ? 'bg-white/10' : 'bg-primary text-white hover:scale-[1.02] shadow-2xl shadow-primary/30'}`}>
                      {loading ? 'Salvando...' : (editingId ? 'Atualizar Item' : 'Publicar Agora')}
                    </button>
                    {editingId && (
                      <button type="button" onClick={() => setEditingId(null)} className="w-full py-2 text-[9px] font-black uppercase opacity-20 hover:opacity-100 transition-all">Cancelar</button>
                    )}
                  </div>
                </div>
              </div>

              <div className="lg:col-span-7">
                <div className="flex items-center justify-between mb-8">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/20">Cadastrados ({items.length})</h3>
                   {listLoading && <div className="w-4 h-4 border-2 border-primary/20 border-t-primary rounded-full animate-spin"></div>}
                </div>
                <div className="space-y-4">
                  {items.map(i => (
                    <div key={i.id} className={`bg-card-dark p-6 rounded-[2rem] border border-white/5 flex items-center justify-between group hover:border-primary/40 transition-all ${editingId === i.id ? 'ring-2 ring-primary border-transparent' : ''}`}>
                      <div className="flex items-center gap-6 overflow-hidden">
                        <img src={i.thumbnail || i.image_url} className="w-16 h-16 rounded-2xl object-cover opacity-60 group-hover:opacity-100 transition-opacity shrink-0" alt={i.title} />
                        <div className="truncate">
                          <p className="text-sm font-black uppercase truncate text-white/90">{i.title}</p>
                          <p className="text-[9px] text-primary/60 font-black uppercase mt-1">{i.location || i.category}</p>
                        </div>
                      </div>
                      <div className="flex gap-3 shrink-0">
                        <button type="button" onClick={() => startEdit(i)} className="w-10 h-10 rounded-xl bg-white/5 text-primary hover:bg-primary hover:text-white transition-all flex items-center justify-center"><span className="material-symbols-outlined text-lg">edit</span></button>
                        <button type="button" onClick={() => handleDelete(i.id)} className="w-10 h-10 rounded-xl bg-white/5 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center"><span className="material-symbols-outlined text-lg">delete</span></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'checking' | 'ok' | 'error'>('checking');
  const [logs, setLogs] = useState<string[]>(["Sessão iniciada"]);
  const [showSqlHelp, setShowSqlHelp] = useState(false);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 10));
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
      checkConnection();
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('ok');
      addLog("Conexão com Banco de Dados: OK");
    } catch (err: any) {
      setDbStatus('error');
      addLog("ERRO DE CONEXÃO: " + err.message);
    }
  };

  const fetchStats = async () => {
    try {
      const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
    } catch (err) {}
  };

  const fetchItems = async () => {
    if (activeTab === 'dashboard') return;
    setListLoading(true);
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
      addLog(`Lista ${table} atualizada`);
    } catch (err: any) {
      addLog(`Erro ao carregar lista: ${err.message}`);
    } finally { setListLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
      checkConnection();
    } else {
      alert('Usuário ou senha inválidos.');
    }
  };

  const getYTThumbnail = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=|shorts\/)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? `https://img.youtube.com/vi/${match[2]}/maxresdefault.jpg` : '';
  };

  const uploadToStorage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}-${Date.now()}.${fileExt}`;
    addLog(`Tentando upload de: ${fileName}...`);

    const { error: uploadError } = await supabase.storage.from('uploads').upload(fileName, file, {
      cacheControl: '3600',
      upsert: false
    });

    if (uploadError) {
      addLog(`❌ Falha no Storage: ${uploadError.message}`);
      if (uploadError.message.includes('row-level security') || uploadError.message.includes('policy')) {
        setShowSqlHelp(true);
        throw new Error("Erro de RLS: O Supabase bloqueou o upload por falta de permissão.");
      }
      throw new Error(`Upload Falhou: ${uploadError.message}`);
    }

    const { data } = supabase.storage.from('uploads').getPublicUrl(fileName);
    return data.publicUrl;
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    addLog("Iniciando publicação...");

    try {
      const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };

      if (!currentData.title) {
        setLoading(false);
        addLog("Erro: Título ausente");
        alert("O campo Título é obrigatório.");
        return;
      }

      let finalImg = "";
      if (selectedFile) {
        finalImg = await uploadToStorage(selectedFile);
        addLog("Imagem processada com sucesso");
      } else if (activeTab === 'videos' && currentData.video_url) {
        finalImg = getYTThumbnail(currentData.video_url);
      } else {
        finalImg = activeTab === 'videos' ? currentData.thumbnail : currentData.image_url;
      }

      const payload: any = { ...currentData };
      delete payload.id;
      delete payload.created_at;

      if (activeTab === 'videos') {
        payload.thumbnail = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      } else {
        payload.image_url = finalImg || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&q=80';
      }

      addLog(`Enviando dados para tabela: ${table}...`);

      let response;
      if (editingId) {
        response = await supabase.from(table).update(payload).eq('id', editingId);
      } else {
        response = await supabase.from(table).insert([payload]);
      }

      if (response.error) {
        addLog(`❌ Erro no Banco: ${response.error.message}`);
        throw new Error(response.error.message);
      }

      addLog("✅ Publicado com sucesso!");

      setEditingId(null);
      setSelectedFile(null);
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
      setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
      setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

      await fetchItems();
      await fetchStats();

      alert("Sucesso! O conteúdo já está no ar.");

    } catch (err: any) {
      addLog(`❌ Erro Fatal: ${err.message}`);
      alert(`Erro: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });

    document.getElementById('admin-form-container')?.scrollIntoView({ behavior: 'smooth' });
    addLog(`Modo edição: ${item.title}`);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Excluir este item permanentemente?')) return;
    const table = activeTab === 'eventos' ? 'events' : activeTab === 'videos' ? 'videos' : 'articles';
    addLog(`Excluindo ${id}...`);
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error) {
      addLog(`Erro ao excluir: ${error.message}`);
      alert(error.message);
    } else {
      addLog("Excluído.");
      fetchItems();
      fetchStats();
    }
  };

  const sqlFixCode = `-- SCRIPT DE CORREÇÃO TOTAL (LIMPA E RECRIA PERMISSÕES)
-- 1. LIMPAR POLÍTICAS ANTIGAS (EVITA ERRO 42710)
DROP POLICY IF EXISTS "Acesso Publico Upload" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico View" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico Update" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico Delete" ON storage.objects;

DROP POLICY IF EXISTS "Acesso Total Eventos" ON public.events;
DROP POLICY IF EXISTS "Acesso Total Videos" ON public.videos;
DROP POLICY IF EXISTS "Acesso Total Artigos" ON public.articles;
DROP POLICY IF EXISTS "Acesso Total Interacoes" ON public.interactions;

-- 2. CONFIGURAR STORAGE (BUCKET 'uploads')
INSERT INTO storage.buckets (id, name, public) 
VALUES ('uploads', 'uploads', true)
ON CONFLICT (id) DO UPDATE SET public = true;

CREATE POLICY "Acesso Publico Upload" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico View" ON storage.objects FOR SELECT USING (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico Update" ON storage.objects FOR UPDATE USING (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico Delete" ON storage.objects FOR DELETE USING (bucket_id = 'uploads');

-- 3. CONFIGURAR TABELAS (PUBLICAS PARA O ADMIN)
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interactions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Acesso Total Eventos" ON public.events FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Videos" ON public.videos FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Artigos" ON public.articles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Interacoes" ON public.interactions FOR ALL USING (true) WITH CHECK (true);`;

  if (!isLoggedIn) {
