          <h2 className="text-xl font-black text-center mb-8 uppercase tracking-widest text-primary">Acesso Master</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="admin" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none focus:border-primary" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="master-samba-2025" className="w-full bg-white/5 border border-white/10 p-4 rounded-xl text-white outline-none focus:border-primary" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs">Acessar Painel</button>
          </form>
        </div>
      </div>
    );
  }

  return (
