                    </div>

                    <button type="button" onClick={handleManualSubmit} disabled={loading} className={`w-full py-5 rounded-2xl font-black uppercase tracking-[0.3em] text-xs transition-all flex items-center justify-center gap-4 ${loading ? 'bg-white/10' : 'bg-primary text-white hover:scale-[1.02] shadow-2xl shadow-primary/30'}`}>
                      {loading ? 'Processando...' : (editingId ? 'Salvar Alterações' : 'Publicar Agora')}
                    </button>
                    {editingId && (
                      <button type="button" onClick={() => { setEditingId(null); setSelectedFile(null); }} className="w-full py-2 text-[9px] font-black uppercase opacity-20 hover:opacity-100 transition-all">Cancelar Edição</button>
                    )}
                  </div>
                </div>
              </div>

              <div className="lg:col-span-7">
                <div className="flex items-center justify-between mb-8">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/20">Cadastrados ({items.length})</h3>
                   {listLoading && <div className="w-4 h-4 border-2 border-primary/20 border-t-primary rounded-full animate-spin"></div>}
                </div>
                <div className="space-y-4">
                  {items.length === 0 && !listLoading ? (
                    <div className="text-center py-20 border border-dashed border-white/10 rounded-[3rem] opacity-20 uppercase font-black text-xs">Vazio</div>
                  ) : items.map(i => (
                    <div key={i.id} className={`bg-card-dark p-6 rounded-[2rem] border border-white/5 flex items-center justify-between group hover:border-primary/40 transition-all ${editingId === i.id ? 'ring-2 ring-primary border-transparent' : ''}`}>
                      <div className="flex items-center gap-6 overflow-hidden">
                        <div className="w-16 h-16 rounded-2xl bg-white/5 overflow-hidden shrink-0">
                          <img src={i.thumbnail || i.image_url} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" alt={i.title} />
                        </div>
                        <div className="truncate">
                          <p className="text-sm font-black uppercase truncate text-white/90">{i.title}</p>
                          <p className="text-[9px] text-primary/60 font-black uppercase mt-1">{i.location || i.category}</p>
                        </div>
                      </div>
                      <div className="flex gap-3 shrink-0 opacity-40 group-hover:opacity-100 transition-opacity">
                        <button type="button" onClick={() => startEdit(i)} className="w-10 h-10 rounded-xl bg-white/5 text-primary hover:bg-primary hover:text-white transition-all flex items-center justify-center shadow-lg"><span className="material-symbols-outlined text-lg">edit</span></button>
                        <button type="button" onClick={() => handleDelete(i.id)} className="w-10 h-10 rounded-xl bg-white/5 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center shadow-lg"><span className="material-symbols-outlined text-lg">delete</span></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'checking' | 'ok' | 'error'>('checking');
  const [logs, setLogs] = useState<string[]>(["Painel iniciado"]);
  const [showSqlHelp, setShowSqlHelp] = useState(false);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  // Mapeamento Garantido: Aba -> Tabela
  const TABLE_MAP: Record<string, string> = {
    'eventos': 'events',
    'videos': 'videos',
    'posts': 'articles'
  };

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 12));
    console.log(`[Admin] ${msg}`);
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
      checkConnection();
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('ok');
      addLog("Conexão com Banco: OK");
    } catch (err: any) {
      setDbStatus('error');
      addLog("Erro DB: " + err.message);
    }
  };

  const fetchStats = async () => {
    try {
      const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
    } catch (err) {}
  };

  const fetchItems = async () => {
    if (activeTab === 'dashboard') return;
    setListLoading(true);
    const table = TABLE_MAP[activeTab];
    if (!table) {
      setListLoading(false);
      return;
    }

    try {
      addLog(`Buscando itens de ${table}...`);
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
      addLog(`${data?.length || 0} itens carregados de ${table}`);
    } catch (err: any) {
      addLog(`Erro ao listar: ${err.message}`);
    } finally { setListLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
      checkConnection();
    } else {
      alert('Credenciais Master incorretas.');
    }
  };

  const getYTThumbnail = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=|shorts\/)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? `https://img.youtube.com/vi/${match[2]}/maxresdefault.jpg` : '';
  };

  const uploadToStorage = async (file: File) => {
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}-${Date.now()}.${fileExt}`;
    addLog(`Upload de imagem iniciado...`);

    const { error: uploadError } = await supabase.storage.from('uploads').upload(fileName, file);

    if (uploadError) {
      addLog(`Erro no Storage: ${uploadError.message}`);
      setShowSqlHelp(true);
      throw new Error(`Upload Falhou: ${uploadError.message}`);
    }

    const { data } = supabase.storage.from('uploads').getPublicUrl(fileName);
    return data.publicUrl;
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    addLog("Publicando conteúdo...");

    try {
      const table = TABLE_MAP[activeTab];
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };

      if (!currentData.title) {
        throw new Error("O título é obrigatório!");
      }

      let finalImg = "";
      if (selectedFile) {
        finalImg = await uploadToStorage(selectedFile);
      } else if (activeTab === 'videos' && currentData.video_url) {
        finalImg = getYTThumbnail(currentData.video_url);
      } else {
        finalImg = activeTab === 'videos' ? currentData.thumbnail : currentData.image_url;
      }

      const payload: any = { ...currentData };
      delete payload.id;
      delete payload.created_at;

      if (activeTab === 'videos') payload.thumbnail = finalImg;
      else payload.image_url = finalImg;

      let response;
      if (editingId) {
        response = await supabase.from(table).update(payload).eq('id', editingId);
        addLog(`Atualizando item ${editingId} em ${table}...`);
      } else {
        response = await supabase.from(table).insert([payload]);
        addLog(`Inserindo novo item em ${table}...`);
      }

      if (response.error) throw response.error;

      addLog("✅ Publicação realizada!");
      setEditingId(null);
      setSelectedFile(null);
      setEventForm({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
      setVideoForm({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
      setPostForm({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

      fetchItems();
      fetchStats();
      alert("Sucesso!");
    } catch (err: any) {
      addLog(`❌ Falha: ${err.message}`);
      alert(`Erro: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!id) return;
    if (!confirm('Excluir este item para sempre?')) return;

    const table = TABLE_MAP[activeTab];
    addLog(`Tentando excluir ID ${id} de ${table}...`);

    try {
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) {
        addLog(`❌ Erro Supabase: ${error.message}`);
        if (error.message.includes('permission denied') || error.message.includes('policy')) {
          setShowSqlHelp(true);
        }
        alert(`Erro ao excluir: ${error.message}`);
      } else {
        addLog(`✅ Sucesso: Item removido.`);
        setItems(prev => prev.filter(item => item.id !== id));
        fetchStats();
      }
    } catch (err: any) {
      addLog(`❌ Erro inesperado: ${err.message}`);
    }
  };

  const startEdit = (item: any) => {
    setEditingId(item.id);
    if (activeTab === 'eventos') setEventForm({ ...item });
    else if (activeTab === 'videos') setVideoForm({ ...item });
    else if (activeTab === 'posts') setPostForm({ ...item });
    addLog(`Editando item: ${item.title}`);
  };

  const sqlFixCode = `-- SCRIPT DE REPARO DEFINITIVO (COPIE E COLE NO SQL EDITOR)
-- 1. Limpa políticas duplicadas
DROP POLICY IF EXISTS "Acesso Total Eventos" ON public.events;
DROP POLICY IF EXISTS "Acesso Total Videos" ON public.videos;
DROP POLICY IF EXISTS "Acesso Total Artigos" ON public.articles;
DROP POLICY IF EXISTS "Acesso Total Interacoes" ON public.interactions;
DROP POLICY IF EXISTS "Acesso Publico Upload" ON storage.objects;
DROP POLICY IF EXISTS "Acesso Publico View" ON storage.objects;

-- 2. Recria as Tabelas se não existirem
CREATE TABLE IF NOT EXISTS public.events (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, created_at timestamp with time zone DEFAULT now(), title text, day text, month text, location text, image_url text, ticket_url text, price text, label text);
CREATE TABLE IF NOT EXISTS public.videos (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, created_at timestamp with time zone DEFAULT now(), title text, category text, thumbnail text, video_url text, duration text);
CREATE TABLE IF NOT EXISTS public.articles (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, created_at timestamp with time zone DEFAULT now(), title text, excerpt text, content text, category text, image_url text, read_time text);
CREATE TABLE IF NOT EXISTS public.interactions (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, created_at timestamp with time zone DEFAULT now(), content_id text, type text, user_insta text, text text);

-- 3. Habilita RLS
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interactions ENABLE ROW LEVEL SECURITY;

-- 4. Permissões GLOBAIS (ALL) para anon e authenticated
CREATE POLICY "Acesso Total Eventos" ON public.events FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Videos" ON public.videos FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Artigos" ON public.articles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Interacoes" ON public.interactions FOR ALL USING (true) WITH CHECK (true);

-- 5. Permissões de Storage
INSERT INTO storage.buckets (id, name, public) VALUES ('uploads', 'uploads', true) ON CONFLICT (id) DO UPDATE SET public = true;
CREATE POLICY "Acesso Publico Upload" ON storage.objects FOR ALL USING (bucket_id = 'uploads') WITH CHECK (bucket_id = 'uploads');
CREATE POLICY "Acesso Publico View" ON storage.objects FOR SELECT USING (bucket_id = 'uploads');`;

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-10 rounded-[2.5rem] shadow-2xl">
          <h2 className="text-2xl font-black text-center mb-8 uppercase tracking-widest text-primary">Master Panel</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="admin" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white outline-none focus:border-primary font-bold" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="master-samba-2025" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white outline-none focus:border-primary font-bold" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-5 rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl shadow-primary/20 hover:brightness-110 active:scale-95 transition-all">Sincronizar</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      {/* Sidebar */}
      <aside className="w-72 bg-card-dark border-r border-white/5 p-8 flex flex-col gap-8 shrink-0 relative">
        <div className="flex items-center gap-3 font-black text-sm uppercase text-primary">
          <span className="material-symbols-outlined text-sm">verified_user</span> 
          <span>Sistema Ativo</span>
        </div>

        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie_filter'},{id:'posts',l:'Crônicas',i:'history_edu'}].map(t => (
            <button key={t.id} type="button" onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-xl shadow-primary/20' : 'text-white/30 hover:bg-white/5 hover:text-white/60'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>

        <div className="mt-auto p-4 bg-black/30 rounded-2xl border border-white/5">
           <p className="text-[8px] font-black uppercase text-white/20 mb-3 tracking-widest">Logs em Tempo Real</p>
           <div className="space-y-2 max-h-32 overflow-y-auto no-scrollbar">
              {logs.map((log, i) => <p key={i} className="text-[8px] font-medium text-white/40 leading-tight border-l border-primary/30 pl-2">{log}</p>)}
           </div>
        </div>

        <button onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); }} className="w-full text-red-500/50 hover:text-red-500 text-[10px] font-black uppercase py-4 border border-red-500/10 rounded-2xl transition-all">Encerrar Sessão</button>
      </aside>

      {/* Main Container */}
      <main className="flex-1 overflow-y-auto p-12 bg-noise relative">
        {showSqlHelp && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-md">
            <div className="bg-card-dark border border-primary/30 p-10 rounded-[3rem] max-w-2xl w-full shadow-2xl animate-fade-in-up">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black text-primary uppercase tracking-tighter">Reparo de Banco de Dados</h3>
                <button onClick={() => setShowSqlHelp(false)} className="text-white/20 hover:text-white transition-colors"><span className="material-symbols-outlined">close</span></button>
              </div>
              <p className="text-white/60 text-sm mb-6 leading-relaxed">
                Parece haver um erro de permissão. Copie o script abaixo, vá ao <strong>SQL Editor</strong> do seu Supabase, cole e clique em <strong>RUN</strong>. Isso libera as funções de exclusão e upload.
              </p>
              <pre className="bg-black/60 p-5 rounded-2xl text-[10px] text-primary font-mono overflow-x-auto border border-white/10 mb-6 h-64 no-scrollbar select-all">
                {sqlFixCode}
              </pre>
              <button onClick={() => { navigator.clipboard.writeText(sqlFixCode); alert("Script Copiado!"); }} className="w-full bg-primary text-white py-4 rounded-xl font-black uppercase text-xs shadow-lg shadow-primary/20">Copiar Script Corretor</button>
            </div>
          </div>
        )}

        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-16">
            <div>
              <p className="text-primary font-black uppercase text-[10px] tracking-[0.4em] mb-2">Master Control</p>
              <h1 className="text-5xl font-black uppercase tracking-tighter leading-none">
                {editingId ? 'Editar Item' : (activeTab === 'dashboard' ? 'Dashboard' : `Gestão de ${activeTab}`)}
              </h1>
            </div>
            <div className="flex items-center gap-6">
               <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-5 py-2.5 rounded-full">
                  <div className={`w-2 h-2 rounded-full ${dbStatus === 'ok' ? 'bg-green-500' : 'bg-red-500'} animate-pulse`}></div>
                  <span className="text-[10px] font-black uppercase text-white/40 tracking-widest">{dbStatus === 'ok' ? 'Sincronizado' : 'Erro DB'}</span>
               </div>
               <button onClick={onClose} className="bg-white text-black px-6 py-2.5 rounded-full text-[10px] font-black uppercase hover:bg-primary hover:text-white transition-all">Voltar ao Site</button>
            </div>
          </header>

          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {[{l:'Agenda de Eventos',v:stats.events,i:'event'},{l:'Acervo de Vídeos',v:stats.videos,i:'movie'},{l:'Crônicas e Artigos',v:stats.articles,i:'description'}].map((s, idx) => (
                <div key={idx} className={`bg-card-dark p-12 rounded-[3.5rem] border border-white/5 flex flex-col gap-4 shadow-2xl relative overflow-hidden group`}>
                  <span className="material-symbols-outlined text-4xl text-primary/10 absolute top-8 right-8 group-hover:scale-110 transition-transform">{s.i}</span>
                  <p className="text-[10px] font-black uppercase text-white/20 tracking-widest">{s.l}</p>
                  <p className="text-7xl font-black tracking-tighter">{s.v}</p>
                </div>
              ))}
              <div className="md:col-span-3">
                 <button onClick={() => setShowSqlHelp(true)} className="flex items-center gap-6 bg-primary/10 border border-primary/20 p-8 rounded-[2.5rem] w-full text-left transition-all hover:bg-primary/20">
                    <div className="w-14 h-14 rounded-2xl bg-primary flex items-center justify-center shrink-0 shadow-lg">
                       <span className="material-symbols-outlined text-white">bolt</span>
                    </div>
                    <div>
                       <h4 className="font-black uppercase text-sm text-primary">Sincronizador de Permissões</h4>
                       <p className="text-white/40 text-[10px] font-bold uppercase tracking-widest">Execute este script caso não consiga excluir ou criar novos registros.</p>
                    </div>
