                    <div className="p-6 border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center gap-2 bg-white/5 hover:bg-white/10 transition-colors group cursor-pointer">
                      <input type="file" id="fileInp" className="hidden" accept="image/*" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
                      <label htmlFor="fileInp" className="cursor-pointer text-center w-full">
                        <span className="material-symbols-outlined text-3xl text-primary">{selectedFile ? 'task_alt' : 'add_photo_alternate'}</span>
                        <p className="text-[10px] font-black uppercase mt-1 text-white/40">{selectedFile ? selectedFile.name : 'Selecionar Foto'}</p>
                      </label>
                    </div>

                    <button type="button" onClick={handleManualSubmit} disabled={loading} className={`w-full py-5 rounded-2xl font-black uppercase tracking-[0.3em] text-xs transition-all flex items-center justify-center gap-4 ${loading ? 'bg-white/10 cursor-not-allowed' : 'bg-primary text-white hover:scale-[1.02] shadow-2xl shadow-primary/30'}`}>
                      {loading ? 'Sincronizando...' : (editingId ? 'Salvar Alterações' : 'Publicar Agora')}
                    </button>
                    {editingId && (
                      <button type="button" onClick={() => { setEditingId(null); setSelectedFile(null); }} className="w-full py-2 text-[9px] font-black uppercase opacity-20 hover:opacity-100 transition-all">Cancelar Edição</button>
                    )}
                  </div>
                </div>
              </div>

              {/* List */}
              <div className="lg:col-span-7">
                <div className="flex items-center justify-between mb-8">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/20">Acervo Cadastrado ({items.length})</h3>
                   {listLoading && <div className="w-4 h-4 border-2 border-primary/20 border-t-primary rounded-full animate-spin"></div>}
                </div>
                <div className="space-y-4">
                  {items.length === 0 && !listLoading ? (
                    <div className="text-center py-20 border border-dashed border-white/10 rounded-[3rem] opacity-20 uppercase font-black text-xs">Sem registros</div>
                  ) : items.map(i => (
                    <div key={i.id} className={`bg-card-dark p-6 rounded-[2rem] border border-white/5 flex items-center justify-between group hover:border-primary/40 transition-all ${editingId === i.id ? 'ring-2 ring-primary border-transparent' : ''}`}>
                      <div className="flex items-center gap-6 overflow-hidden">
                        <div className="w-16 h-16 rounded-2xl bg-white/5 overflow-hidden shrink-0 border border-white/10">
                          <img src={i.thumbnail || i.image_url} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" alt={i.title} />
                        </div>
                        <div className="truncate">
                          <p className="text-sm font-black uppercase truncate text-white/90">{i.title}</p>
                          <p className="text-[9px] text-primary/60 font-black uppercase mt-1 tracking-widest">{i.location || i.category}</p>
                        </div>
                      </div>
                      <div className="flex gap-3 shrink-0 opacity-40 group-hover:opacity-100 transition-opacity">
                        <button type="button" onClick={() => startEdit(i)} className="w-11 h-11 rounded-xl bg-white/5 text-primary hover:bg-primary hover:text-white transition-all flex items-center justify-center shadow-lg"><span className="material-symbols-outlined text-xl">edit</span></button>
                        <button type="button" onClick={() => handleDelete(i.id)} className="w-11 h-11 rounded-xl bg-white/5 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center shadow-lg"><span className="material-symbols-outlined text-xl">delete</span></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

