import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'checking' | 'ok' | 'error'>('checking');
  const [logs, setLogs] = useState<string[]>(["Painel iniciado"]);
  const [showSqlHelp, setShowSqlHelp] = useState(false);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Form States
  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  const TABLE_MAP: Record<string, string> = {
    'eventos': 'events',
    'videos': 'videos',
    'posts': 'articles'
  };

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 12));
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
      checkConnection();
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('ok');
    } catch (err: any) {
      setDbStatus('error');
    }
  };

  const fetchStats = async () => {
    try {
      const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
    } catch (err) {}
  };

  const fetchItems = async () => {
    if (activeTab === 'dashboard') return;
    setListLoading(true);
    const table = TABLE_MAP[activeTab];
    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      addLog(`Erro ao listar: ${err.message}`);
    } finally { setListLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
      checkConnection();
    } else {
      alert('Acesso negado.');
    }
  };

  const handleDelete = async (id: string) => {
    if (!id) return;
    if (!confirm('Tem certeza que deseja excluir permanentemente?')) return;

    const table = TABLE_MAP[activeTab];
    addLog(`Excluindo ID ${id} de ${table}...`);

    try {
      // Tenta excluir do banco
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) {
        addLog(`Erro: ${error.message}`);
        // Se o erro for de permissão (RLS), abre o modal de ajuda SQL
        if (error.message.includes('permission denied') || error.code === '42501') {
          setShowSqlHelp(true);
          alert("Erro de Permissão: Você precisa rodar o script SQL no Supabase para liberar a exclusão.");
        } else {
          alert(`Erro ao excluir: ${error.message}`);
        }
      } else {
        addLog(`✅ Sucesso: Item removido.`);
        setItems(prev => prev.filter(item => item.id !== id));
        fetchStats();
      }
    } catch (err: any) {
      addLog(`Erro inesperado: ${err.message}`);
    }
  };

  const sqlFixCode = `-- COPIE E COLE NO SQL EDITOR DO SUPABASE E CLIQUE EM RUN
-- Liberar permissão total para exclusão e inserção (anon/public)

DROP POLICY IF EXISTS "Acesso Total Eventos" ON public.events;
DROP POLICY IF EXISTS "Acesso Total Videos" ON public.videos;
DROP POLICY IF EXISTS "Acesso Total Artigos" ON public.articles;
DROP POLICY IF EXISTS "Acesso Total Interacoes" ON public.interactions;

CREATE POLICY "Acesso Total Eventos" ON public.events FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Videos" ON public.videos FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Artigos" ON public.articles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total Interacoes" ON public.interactions FOR ALL USING (true) WITH CHECK (true);

-- Garantir que as tabelas aceitam comandos
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interactions ENABLE ROW LEVEL SECURITY;`;

  const copySql = () => {
    navigator.clipboard.writeText(sqlFixCode).then(() => {
      alert("Script SQL Copiado! Agora cole no SQL Editor do Supabase e clique em RUN.");
    });
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    const table = TABLE_MAP[activeTab];
    try {
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };
      if (!currentData.title) throw new Error("Título obrigatório");

      let finalPayload = { ...currentData };
      delete finalPayload.id;
      delete finalPayload.created_at;

      let res;
      if (editingId) {
        res = await supabase.from(table).update(finalPayload).eq('id', editingId);
      } else {
        res = await supabase.from(table).insert([finalPayload]);
      }

      if (res.error) throw res.error;

      alert("Publicado!");
      setEditingId(null);
      fetchItems();
      fetchStats();
    } catch (err: any) {
      alert(err.message);
    } finally { setLoading(false); }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-10 rounded-[2.5rem] shadow-2xl">
          <h2 className="text-2xl font-black text-center mb-8 uppercase tracking-widest text-primary">Master Panel</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="admin" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white outline-none focus:border-primary font-bold" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="senha" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white outline-none focus:border-primary font-bold" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-5 rounded-2xl font-black uppercase text-xs tracking-[0.2em]">Acessar</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      {/* Sidebar */}
      <aside className="w-72 bg-card-dark border-r border-white/5 p-8 flex flex-col gap-8 shrink-0 relative">
        <div className="flex items-center gap-3 font-black text-sm uppercase text-primary">
          <span className="material-symbols-outlined text-sm">verified_user</span> 
          <span>Admin</span>
        </div>
        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie_filter'},{id:'posts',l:'Crônicas',i:'history_edu'}].map(t => (
            <button key={t.id} type="button" onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === t.id ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>
        <button onClick={() => setShowSqlHelp(true)} className="mt-auto text-[9px] font-black uppercase tracking-widest text-primary/40 hover:text-primary">Reparar Banco (SQL)</button>
        <button onClick={onClose} className="w-full text-white/30 hover:text-white text-[10px] font-black uppercase py-4 border border-white/5 rounded-2xl">Sair</button>
      </aside>

      {/* Main Container */}
      <main className="flex-1 overflow-y-auto p-12 bg-noise relative">
        {showSqlHelp && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-md">
            <div className="bg-card-dark border border-primary/30 p-10 rounded-[3.5rem] max-w-2xl w-full shadow-2xl relative">
              <button onClick={() => setShowSqlHelp(false)} className="absolute top-8 right-8 text-white/20 hover:text-white"><span className="material-symbols-outlined">close</span></button>
              <h3 className="text-xl font-black text-primary uppercase mb-4">Reparar Permissões de Exclusão</h3>
              <p className="text-white/60 text-sm mb-6">Se a lixeira não funciona, o Supabase está bloqueando a exclusão. Copie o script abaixo e rode no seu SQL Editor.</p>
              <pre className="bg-black/60 p-5 rounded-2xl text-[10px] text-primary/80 font-mono overflow-x-auto border border-white/10 mb-6 max-h-48 overflow-y-auto">
                {sqlFixCode}
              </pre>
              <button onClick={copySql} className="w-full bg-primary text-white py-5 rounded-2xl font-black uppercase text-xs flex items-center justify-center gap-3">
                <span className="material-symbols-outlined">content_copy</span> COPIAR SCRIPT SQL
              </button>
            </div>
          </div>
        )}

        <div className="max-w-6xl mx-auto">
          <header className="flex justify-between items-end mb-16">
            <div>
              <p className="text-primary font-black uppercase text-[10px] tracking-[0.4em] mb-2">Master Control</p>
              <h1 className="text-5xl font-black uppercase tracking-tighter leading-none">{activeTab}</h1>
            </div>
          </header>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
            <div className="lg:col-span-5">
               {/* Formulário simplificado aqui... (Mesma lógica anterior) */}
               <div className="bg-card-dark p-8 rounded-[2.5rem] border border-white/10 space-y-4">
                  <h4 className="text-[10px] font-black uppercase text-white/40 mb-4">Novo Registro</h4>
                  {activeTab === 'videos' && (
                    <div className="space-y-4">
                      <input type="text" placeholder="Título" className="w-full bg-white/5 p-4 rounded-xl outline-none" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                      <input type="text" placeholder="URL YouTube" className="w-full bg-white/5 p-4 rounded-xl outline-none" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                    </div>
                  )}
                  {activeTab === 'eventos' && (
                    <div className="space-y-4">
                      <input type="text" placeholder="Título" className="w-full bg-white/5 p-4 rounded-xl outline-none" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                    </div>
                  )}
                  <button onClick={handleManualSubmit} className="w-full bg-primary py-4 rounded-xl font-black uppercase text-xs">Publicar</button>
               </div>
            </div>

            <div className="lg:col-span-7">
              <div className="space-y-4">
                {items.map(i => (
                  <div key={i.id} className="bg-card-dark p-6 rounded-3xl border border-white/5 flex items-center justify-between group">
                    <div className="truncate pr-4">
                      <p className="text-sm font-black uppercase truncate">{i.title}</p>
                      <p className="text-[9px] text-white/20 uppercase tracking-widest">{i.location || i.category}</p>
                    </div>
                    <div className="flex gap-2">
                       <button onClick={() => handleDelete(i.id)} className="w-10 h-10 rounded-xl bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center">
                          <span className="material-symbols-outlined text-lg">delete</span>
                       </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

