        if (error.code === '42501' || error.message.includes('permission denied')) {
          setShowSqlHelp(true);
          alert("ERRO DE PERMISSÃO: O banco de dados bloqueou a exclusão. Você precisa rodar o script SQL de reparo.");
        } else {
          alert(`Erro: ${error.message}`);
        }
      } else {
        addLog(`✅ Sucesso! Item removido da tabela ${table}.`);
        setItems(prev => prev.filter(item => item.id !== id));
        fetchStats();
      }
    } catch (err: any) {
      addLog(`Erro crítico: ${err.message}`);
    }
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    const table = TABLE_MAP[activeTab];

    try {
      let currentData: any = activeTab === 'eventos' ? { ...eventForm } : activeTab === 'videos' ? { ...videoForm } : { ...postForm };
