  const sqlFixCode = `-- SCRIPT DE REPARO PARA LIBERAR EXCLUSÃO E INSERÇÃO
-- Rode este código no SQL Editor do seu Supabase para que a lixeira funcione.

-- 1. Remover políticas antigas para evitar conflitos
DROP POLICY IF EXISTS "Acesso Total Eventos" ON public.events;
DROP POLICY IF EXISTS "Acesso Total Videos" ON public.videos;
DROP POLICY IF EXISTS "Acesso Total Artigos" ON public.articles;
DROP POLICY IF EXISTS "Acesso Total Interacoes" ON public.interactions;

-- 2. Criar novas políticas que permitem TUDO (Insert, Select, Update, DELETE)
