ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.interactions ENABLE ROW LEVEL SECURITY;

-- 4. Dar permissões de bypass para o papel anon (usado pela chave pública)
GRANT ALL ON TABLE public.events TO anon;
GRANT ALL ON TABLE public.videos TO anon;
GRANT ALL ON TABLE public.articles TO anon;
GRANT ALL ON TABLE public.interactions TO anon;`;

  const copySql = () => {
    navigator.clipboard.writeText(sqlFixCode).then(() => {
      alert("Script SQL Copiado! Cole no SQL Editor do Supabase e clique em RUN.");
    });
  };

  if (!isLoggedIn) {
