                  {activeTab === 'posts' && (
                    <div className="space-y-4">
                      <input type="text" placeholder="Título da Crônica" className="w-full bg-white/5 p-4 rounded-xl outline-none focus:border-primary border border-transparent" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
