                </div>
              </div>

              <div className="lg:col-span-7">
                <div className="flex items-center justify-between mb-8 px-2">
                   <h3 className="text-[10px] font-black uppercase tracking-widest text-white/20">Registros Ativos ({items.length})</h3>
                   {listLoading && <div className="w-4 h-4 border-2 border-primary/20 border-t-primary rounded-full animate-spin"></div>}
                </div>
                <div className="space-y-4">
                  {items.map(i => (
                    <div key={i.id} className="bg-card-dark p-6 rounded-[2rem] border border-white/5 flex items-center justify-between group hover:border-primary/20 transition-all">
                      <div className="truncate pr-6">
                        <p className="text-sm font-black uppercase truncate text-white/90">{i.title}</p>
                        <p className="text-[9px] text-white/20 uppercase tracking-widest mt-1">{i.location || i.category || 'Registro'}</p>
                      </div>
                      <div className="flex gap-2">
                         <button onClick={() => { setEditingId(i.id); activeTab === 'videos' ? setVideoForm(i) : activeTab === 'eventos' ? setEventForm(i) : setPostForm(i); }} className="w-10 h-10 rounded-xl bg-white/5 text-primary hover:bg-primary hover:text-white transition-all flex items-center justify-center">
                            <span className="material-symbols-outlined text-lg">edit</span>
                         </button>
                         <button onClick={() => handleDelete(i.id)} className="w-10 h-10 rounded-xl bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center">
                            <span className="material-symbols-outlined text-lg">delete</span>
                         </button>
                      </div>
                    </div>
                  ))}
                  {items.length === 0 && !listLoading && (
                    <div className="text-center py-20 border border-dashed border-white/5 rounded-[3rem] text-white/10 uppercase font-black text-xs">Vazio</div>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

