-- LIBERAR TUDO PARA AS TABELAS (INSERT, SELECT, UPDATE, DELETE)
-- Isso permite que o painel de administração gerencie os dados sem autenticação complexa

DROP POLICY IF EXISTS "Acesso Total Eventos" ON public.events;
DROP POLICY IF EXISTS "Acesso Total Videos" ON public.videos;
