                    </div>
                  )}
                  <button onClick={handleManualSubmit} disabled={loading} className="w-full bg-primary py-5 rounded-2xl font-black uppercase text-xs">
                    {loading ? 'Processando...' : (editingId ? 'Salvar' : 'Publicar')}
                  </button>
                </div>
              </div>

              <div className="lg:col-span-7">
                <div className="space-y-4">
                  {items.map(i => (
                    <div key={i.id} className="bg-card-dark p-6 rounded-[2rem] border border-white/5 flex items-center justify-between group">
                      <div className="truncate pr-6">
                        <p className="text-sm font-black uppercase truncate text-white/90">{i.title}</p>
                        <p className="text-[9px] text-white/20 uppercase tracking-widest mt-1">{i.location || i.category}</p>
                      </div>
                      <div className="flex gap-2 shrink-0">
                         <button onClick={() => { setEditingId(i.id); activeTab === 'videos' ? setVideoForm(i) : activeTab === 'eventos' ? setEventForm(i) : setPostForm(i); }} className="w-10 h-10 rounded-xl bg-white/5 text-primary hover:bg-primary hover:text-white transition-all flex items-center justify-center">
                            <span className="material-symbols-outlined text-lg">edit</span>
                         </button>
                         <button onClick={() => handleDelete(i.id)} className="w-10 h-10 rounded-xl bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-all flex items-center justify-center">
                            <span className="material-symbols-outlined text-lg">delete</span>
                         </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminPanel;

