    const table = TABLE_MAP[activeTab];
    addLog(`Iniciando deleção do ID ${id} em ${table}...`);

    try {
      // Forçar a deleção usando o ID
      const { error, status } = await supabase.from(table).delete().match({ id: id });

      if (error) {
