        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie_filter'},{id:'posts',l:'Crônicas',i:'history_edu'}].map(t => (
            <button key={t.id} type="button" onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === t.id ? 'bg-primary text-white shadow-xl shadow-primary/20' : 'text-white/30 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>

        <div className="mt-auto p-4 bg-black/30 rounded-2xl border border-white/5">
           <p className="text-[8px] font-black uppercase text-white/20 mb-3 tracking-widest flex items-center gap-2">
              <span className={`w-1.5 h-1.5 rounded-full ${dbStatus === 'ok' ? 'bg-green-500' : 'bg-red-500 animate-pulse'}`}></span>
              Logs de Conexão
           </p>
           <div className="space-y-2 max-h-40 overflow-y-auto no-scrollbar">
              {logs.map((log, i) => <p key={i} className="text-[8px] font-medium text-white/40 leading-tight border-l border-primary/30 pl-2">{log}</p>)}
           </div>
        </div>

        <button onClick={onClose} className="w-full text-white/30 hover:text-white text-[10px] font-black uppercase py-4 border border-white/5 rounded-2xl transition-all">Fechar Painel</button>
      </aside>

      {/* Main Container */}
