const EventList: React.FC<{ onViewFullSchedule: () => void }> = ({ onViewFullSchedule }) => {
  const [events, setEvents] = useState<EventData[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const { data, error } = await supabase
          .from('events')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(3);

        if (error) throw error;
        if (data && data.length > 0) {
          setEvents(data);
        } else {
          setEvents(SITE_CONTENT.events.slice(0, 3));
        }
      } catch (err) {
        console.error('Erro ao buscar eventos:', err);
        setEvents(SITE_CONTENT.events.slice(0, 3));
      } finally {
        setLoading(false);
      }
    };

    fetchEvents();
  }, []);

  return (
    <section className="w-full">
      <div className="max-w-6xl mx-auto mb-16 relative">
        <h2 className="text-4xl md:text-6xl font-black text-white leading-none">ONDE A RODA <br/><span className="text-outline">ACONTECE</span></h2>
      </div>

      <div className="max-w-5xl mx-auto flex flex-col gap-10">
        {loading ? (
           <div className="flex justify-center py-20"><div className="w-8 h-8 border-4 border-primary/20 border-t-primary rounded-full animate-spin"></div></div>
        ) : events.length === 0 ? (
          <p className="text-center text-white/20 py-10 uppercase font-black text-xs tracking-widest">Nenhuma roda agendada para hoje.</p>
        ) : (
          events.map((event, idx) => (
            <EventCard key={event.id} {...event} image={event.image_url} align={idx % 2 === 0 ? 'start' : 'end'} />
          ))
        )}
      </div>

      <div className="flex justify-center mt-20">
        <button onClick={onViewFullSchedule} className="px-8 py-4 border border-white/20 rounded-full text-white font-bold hover:border-primary transition-all uppercase text-xs tracking-widest">Ver programação completa</button>
      </div>
    </section>
  );
};

export default EventList;

