                 <img src={event.image_url} alt={event.title} className="w-full h-full object-cover opacity-60 group-hover:scale-105 transition-transform duration-1000" />
                 <div className="absolute top-6 left-6 bg-white/10 backdrop-blur-md rounded-2xl p-4 text-center border border-white/20">
