import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'dashboard' | 'eventos' | 'videos' | 'posts'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [listLoading, setListLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });
  const [dbStatus, setDbStatus] = useState<'checking' | 'ok' | 'error'>('checking');
  const [logs, setLogs] = useState<string[]>(["Painel iniciado e pronto"]);

  const TABLE_MAP: Record<string, string> = {
    'eventos': 'events',
    'videos': 'videos',
    'posts': 'articles'
  };

  const [eventForm, setEventForm] = useState({ day: '', month: '', title: '', location: '', image_url: '', price: '', ticket_url: '', label: '' });
  const [videoForm, setVideoForm] = useState({ title: '', category: 'Ao Vivo', thumbnail: '', video_url: '', duration: '' });
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'História', image_url: '', read_time: '5 min' });

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 15));
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') {
      setIsLoggedIn(true);
      checkConnection();
    }
  }, []);

  useEffect(() => {
    if (isLoggedIn) {
      fetchItems();
      fetchStats();
    }
  }, [isLoggedIn, activeTab]);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('ok');
      addLog("Conexão Supabase OK.");
    } catch (err: any) {
      setDbStatus('error');
      addLog("Erro Conexão: " + err.message);
    }
  };

  const fetchStats = async () => {
    try {
      const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
      const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
      const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
      setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
    } catch (err) {}
  };

  const fetchItems = async () => {
    if (activeTab === 'dashboard') return;
    setListLoading(true);
    const table = TABLE_MAP[activeTab];
    try {
      const { data, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      addLog(`Erro ao listar: ${err.message}`);
    } finally { setListLoading(false); }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'master-samba-2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
      checkConnection();
    } else {
      alert('Acesso negado.');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Deseja excluir este item permanentemente?')) return;
    const table = TABLE_MAP[activeTab];
    try {
      const { error } = await supabase.from(table).delete().match({ id: id });
      if (error) throw error;
      setItems(prev => prev.filter(item => item.id !== id));
      fetchStats();
      addLog("Item excluído.");
    } catch (err: any) {
      alert("Erro ao excluir: " + err.message);
    }
  };

  const handleManualSubmit = async (e: React.MouseEvent) => {
    e.preventDefault();
    setLoading(true);
    const table = TABLE_MAP[activeTab];
    try {
      let currentData = activeTab === 'eventos' ? eventForm : activeTab === 'videos' ? videoForm : postForm;
      const payload = { ...currentData };

      let res;
      if (editingId) {
        res = await supabase.from(table).update(payload).eq('id', editingId);
      } else {
        res = await supabase.from(table).insert([payload]);
      }

      if (res.error) throw res.error;

      addLog("✅ Dados salvos no banco.");
      setEditingId(null);
      fetchItems();
      fetchStats();
      alert("Publicado com sucesso!");
    } catch (err: any) {
      addLog(`Erro ao salvar: ${err.message}`);
      alert("Erro ao salvar: " + err.message);
    } finally { setLoading(false); }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center p-6 font-display">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-10 rounded-[2.5rem] shadow-2xl">
          <h2 className="text-2xl font-black text-center mb-8 uppercase tracking-widest text-primary">Master Access</h2>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="usuário" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white outline-none focus:border-primary font-bold" value={loginForm.user} onChange={e => setLoginForm({...loginForm, user: e.target.value})} />
            <input type="password" placeholder="senha" className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white outline-none focus:border-primary font-bold" value={loginForm.pass} onChange={e => setLoginForm({...loginForm, pass: e.target.value})} />
            <button type="submit" className="w-full bg-primary text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest">Entrar</button>
          </form>
          <button onClick={onClose} className="w-full mt-4 text-white/20 text-[10px] uppercase font-bold">Voltar ao site</button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-full bg-background-dark text-white font-display overflow-hidden">
      <aside className="w-72 bg-card-dark border-r border-white/5 p-8 flex flex-col gap-6 shrink-0">
        <div className="font-black text-[10px] uppercase text-primary tracking-widest mb-4">Gerenciador de Conteúdo</div>
        <nav className="flex flex-col gap-2">
          {[{id:'dashboard',l:'Resumo',i:'grid_view'},{id:'eventos',l:'Agenda',i:'event'},{id:'videos',l:'Vídeos',i:'movie_filter'},{id:'posts',l:'Crônicas',i:'history_edu'}].map(t => (
            <button key={t.id} onClick={() => { setActiveTab(t.id as any); setEditingId(null); }} className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === t.id ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
            </button>
          ))}
        </nav>
        <div className="mt-auto p-4 bg-black/20 rounded-xl border border-white/5 max-h-40 overflow-y-auto no-scrollbar">
          {logs.map((log, i) => <p key={i} className="text-[8px] text-white/40 mb-1">{log}</p>)}
        </div>
        <button onClick={onClose} className="w-full py-4 border border-white/5 rounded-2xl text-[10px] font-black uppercase text-white/30 hover:text-white transition-all">Sair do Painel</button>
      </aside>

      <main className="flex-1 overflow-y-auto p-12 bg-noise">
        <div className="max-w-6xl mx-auto">
          <header className="mb-12">
            <h1 className="text-5xl font-black uppercase tracking-tighter">{activeTab}</h1>
          </header>

          {activeTab === 'dashboard' ? (
             <div className="grid grid-cols-3 gap-8">
               {[{l:'Agenda',v:stats.events},{l:'Vídeos',v:stats.videos},{l:'Artigos',v:stats.articles}].map((s, idx) => (
                 <div key={idx} className="bg-card-dark p-10 rounded-[2.5rem] border border-white/5">
                    <p className="text-[10px] font-black uppercase text-white/20 mb-2">{s.l}</p>
                    <p className="text-6xl font-black tracking-tighter">{s.v}</p>
                 </div>
               ))}
             </div>
          ) : (
            <div className="grid grid-cols-12 gap-12">
              <div className="col-span-5 bg-card-dark p-8 rounded-[2.5rem] border border-white/10 space-y-4">
                <p className="text-[10px] font-black uppercase text-primary tracking-widest">Novo Registro</p>

                {activeTab === 'eventos' && (
                  <>
                    <input type="text" placeholder="Título (ex: Quinta Carioca - Pagode 90)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none focus:border-primary" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
                    <div className="grid grid-cols-2 gap-4">
                      <input type="text" placeholder="Dia (ex: 22)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={eventForm.day} onChange={e => setEventForm({...eventForm, day: e.target.value})} />
                      <input type="text" placeholder="Mês (ex: JAN)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none uppercase" value={eventForm.month} onChange={e => setEventForm({...eventForm, month: e.target.value})} />
                    </div>
                    <input type="text" placeholder="Local e Horário" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={eventForm.location} onChange={e => setEventForm({...eventForm, location: e.target.value})} />
                    <input type="text" placeholder="Link da Imagem (Instagram/URL)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={eventForm.image_url} onChange={e => setEventForm({...eventForm, image_url: e.target.value})} />
                    <input type="text" placeholder="Destaque (ex: SPC, Soweto, Pixote...)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={eventForm.price} onChange={e => setEventForm({...eventForm, price: e.target.value})} />
                  </>
                )}

                {activeTab === 'videos' && (
                  <>
                    <input type="text" placeholder="Título do Vídeo" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={videoForm.title} onChange={e => setVideoForm({...videoForm, title: e.target.value})} />
                    <input type="text" placeholder="URL do Vídeo (YouTube)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={videoForm.video_url} onChange={e => setVideoForm({...videoForm, video_url: e.target.value})} />
                    <input type="text" placeholder="Thumbnail (URL)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={videoForm.thumbnail} onChange={e => setVideoForm({...videoForm, thumbnail: e.target.value})} />
                  </>
                )}

                {activeTab === 'posts' && (
                  <>
                    <input type="text" placeholder="Título da Crônica" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                    <textarea placeholder="Conteúdo..." className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none h-32 resize-none" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                    <input type="text" placeholder="Imagem de Capa (URL)" className="w-full bg-white/5 p-4 rounded-xl border border-white/10 text-white outline-none" value={postForm.image_url} onChange={e => setPostForm({...postForm, image_url: e.target.value})} />
