                <button onClick={handleManualSubmit} disabled={loading} className="w-full bg-primary py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:scale-[1.02] transition-all disabled:opacity-50">
                  {loading ? 'Sincronizando...' : (editingId ? 'Salvar Alteração' : 'Publicar')}
                </button>
              </div>

              <div className="col-span-7 space-y-4">
                <p className="text-[10px] font-black uppercase text-white/20 tracking-widest px-2">Itens Publicados</p>
                <div className="max-h-[60vh] overflow-y-auto pr-4 no-scrollbar space-y-3">
                  {items.map(item => (
                    <div key={item.id} className="bg-card-dark p-6 rounded-2xl border border-white/5 flex items-center justify-between group">
