import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  const model = 'gemini-3-flash-preview';

  const systemInstructions = {
    event: "Extraia informações de um evento de samba. Retorne JSON com: title (max 30 chars), day (apenas o número), month (3 letras maiúsculas ex: JAN), location (local e bairro), price (atrações principais ou preço), label (uma palavra de destaque).",
    video: "Extraia informações de um vídeo. Retorne JSON com: title (título limpo), category (Ao Vivo, Documentário ou Clipe).",
    article: "Extraia informações de um post/crônica. Retorne JSON com: title (título chamativo), excerpt (resumo de 2 linhas), category (História, Entrevista ou Opinião), read_time (ex: 5 min)."
  };

  const response = await ai.models.generateContent({
    model,
    contents: `Texto original: "${rawText}"`,
    config: {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json"
    }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Erro ao processar JSON da IA", e);
    return null;
  }
}

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { parseContentWithAI } from '../lib/gemini';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'sync' | 'eventos' | 'videos' | 'posts'>('sync');
  const [syncText, setSyncText] = useState('');
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  const TABLE_MAP: Record<string, string> = {
    'eventos': 'events',
    'videos': 'videos',
    'posts': 'articles'
  };

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') setIsLoggedIn(true);
  }, []);

  useEffect(() => {
    if (isLoggedIn) fetchStats();
  }, [isLoggedIn, activeTab]);

  const fetchStats = async () => {
    const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'samba2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else alert('Acesso negado.');
  };

  const handleSync = async (type: 'event' | 'video' | 'article') => {
    if (!syncText.trim()) return alert("Cole o texto ou link primeiro!");
    setLoading(true);
    try {
      const parsed = await parseContentWithAI(syncText, type);
      if (!parsed) throw new Error("IA não conseguiu processar.");

      const table = type === 'event' ? 'events' : type === 'video' ? 'videos' : 'articles';

      // Ajustes manuais de campos que a IA não pega sozinha (como URLs)
      const payload = { ...parsed };
      if (type === 'video') {
        payload.video_url = syncText.includes('http') ? syncText : '';
        const ytId = syncText.match(/(?:youtu\.be\/|youtube\.com\/watch\?v=)([^#&?]*)/)?.[1];
        payload.thumbnail = ytId ? `https://img.youtube.com/vi/${ytId}/maxresdefault.jpg` : 'https://images.unsplash.com/photo-1493225255756-d9584f8606e9?auto=format&fit=crop&q=80';
      }
      if (type === 'event') {
        payload.image_url = 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?auto=format&fit=crop&q=80';
      }
      if (type === 'article') {
        payload.image_url = 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&q=80';
        payload.content = syncText;
      }

      const { error } = await supabase.from(table).insert([payload]);
      if (error) throw error;

      alert(`${type.toUpperCase()} publicado com sucesso!`);
      setSyncText('');
      fetchStats();
    } catch (err: any) {
      alert("Erro no Sync: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="fixed inset-0 z-[100] bg-background-dark flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-card-dark border border-white/10 p-10 rounded-[2.5rem] shadow-2xl">
