            <button type="submit" className="w-full bg-primary text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest">Entrar</button>
          </form>
          <button onClick={onClose} className="w-full mt-4 text-white/20 text-[10px] uppercase font-bold">Cancelar</button>
        </div>
      </div>
    );
  }

  return (
