      <aside className="w-72 bg-card-dark border-r border-white/5 p-8 flex flex-col gap-6 shrink-0">
        <div className="font-black text-[10px] uppercase text-primary tracking-widest mb-4">Tem Samba Aí - Admin</div>
        <nav className="flex flex-col gap-2">
          {[{id:'sync',l:'Samba Sync ✨',i:'auto_awesome'},{id:'eventos',l:'Eventos',i:'event'},{id:'videos',l:'Vídeos',i:'movie_filter'},{id:'posts',l:'Crônicas',i:'history_edu'}].map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id as any)} className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === t.id ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
              <span className="material-symbols-outlined text-lg">{t.i}</span> {t.l}
