           <div className="text-center p-2 bg-white/5 rounded-xl"><p className="text-[8px] opacity-30">A</p><p className="font-black text-primary">{stats.articles}</p></div>
        </div>
        <button onClick={() => { localStorage.removeItem('admin_session'); setIsLoggedIn(false); onClose(); }} className="w-full py-4 border border-white/5 rounded-2xl text-[10px] font-black uppercase text-white/30 hover:text-white transition-all">Sair</button>
