        payload.content = syncText;
      }

      const { error } = await supabase.from(table).insert([payload]);
      if (error) throw error;

      alert(`Sucesso! ${type === 'event' ? 'Evento' : type === 'video' ? 'Vídeo' : 'Post'} publicado.`);
      setSyncText('');
      fetchStats();
