            {dbStatus === 'connected' ? 'Conectado e Pronto' : 'Tabelas não encontradas!'}
          </p>
        </div>

        <nav className="flex flex-col gap-2">
          <button onClick={() => setActiveTab('sync')} className={`flex items-center gap-4 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'sync' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
