import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { parseContentWithAI } from '../lib/gemini';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginForm, setLoginForm] = useState({ user: '', pass: '' });
  const [activeTab, setActiveTab] = useState<'sync' | 'manage'>('sync');
  const [syncText, setSyncText] = useState('');
  const [loading, setLoading] = useState(false);
  const [dbStatus, setDbStatus] = useState<'checking' | 'connected' | 'error'>('checking');
  const [errorMessage, setErrorMessage] = useState('');
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  useEffect(() => {
    const session = localStorage.getItem('admin_session');
    if (session === 'active') setIsLoggedIn(true);
    checkConnection();
  }, []);

  const checkConnection = async () => {
    setDbStatus('checking');
    try {
      const { data, error } = await supabase.from('events').select('id').limit(1);
      if (error) throw error;
      setDbStatus('connected');
      setErrorMessage('');
      fetchStats();
    } catch (err: any) {
      console.error("Erro Supabase:", err);
      setDbStatus('error');
      setErrorMessage(err.message || 'Erro desconhecido de conexão');
    }
  };

  const fetchStats = async () => {
    const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.user === 'admin' && loginForm.pass === 'samba2025') {
      setIsLoggedIn(true);
      localStorage.setItem('admin_session', 'active');
    } else alert('Usuário ou senha inválidos.');
  };

  const handleSync = async (type: 'event' | 'video' | 'article') => {
    if (dbStatus !== 'connected') {
      return alert(`Erro de Banco de Dados: ${errorMessage}\n\nVerifique se você rodou o SQL de desativação de RLS no Supabase!`);
    }
    if (!syncText.trim()) return alert("Cole o texto ou link primeiro!");

    setLoading(true);
    try {
      const parsed = await parseContentWithAI(syncText, type);
      if (!parsed) throw new Error("A IA não conseguiu processar esse texto. Tente copiar e colar novamente.");

      const table = type === 'event' ? 'events' : type === 'video' ? 'videos' : 'articles';
      const payload = { ...parsed };

      if (type === 'video') {
        const ytId = syncText.match(/(?:youtu\.be\/|youtube\.com\/watch\?v=)([^#&?]*)/)?.[1];
        payload.video_url = syncText.includes('http') ? syncText : `https://www.youtube.com/watch?v=${ytId}`;
        payload.thumbnail = ytId ? `https://img.youtube.com/vi/${ytId}/maxresdefault.jpg` : 'https://images.unsplash.com/photo-1493225255756-d9584f8606e9?auto=format&fit=crop&q=80';
      } else if (type === 'event') {
        payload.image_url = 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?auto=format&fit=crop&q=80';
      } else if (type === 'article') {
        payload.image_url = 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&q=80';
        payload.content = syncText;
      }

      const { error } = await supabase.from(table).insert([payload]);
      if (error) throw error;

      alert(`Publicado com Sucesso!`);
      setSyncText('');
      fetchStats();
    } catch (err: any) {
