import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  const model = 'gemini-3-flash-preview';
  const isUrl = rawText.trim().startsWith('http');

  const systemInstructions = {
    event: "Você é um assistente de eventos de samba. Extraia as informações e retorne APENAS um JSON válido com os campos: title (max 30 chars), day (número), month (3 letras maiúsculas), location (local), price (atrações ou valor), label (uma palavra chave), image_url (link da imagem se encontrar, senão null), search_term (termo em inglês para busca visual).",
    video: "Extraia informações de um vídeo. Retorne APENAS um JSON válido com: title (título limpo), category (Ao Vivo, Clipe, etc).",
    article: "Extraia informações de um post. Retorne APENAS um JSON válido com: title, excerpt, category, read_time."
  };

  try {
    const config: any = {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json",
      temperature: 0.1,
    };

    // Se for URL, ativa o Google Search para "ler" a página
    if (isUrl) {
      config.tools = [{ googleSearch: {} }];
    }

    const prompt = isUrl 
      ? `Acesse este link e extraia os detalhes solicitados: ${rawText}`
      : `Processe o seguinte conteúdo: "${rawText}"`;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config,
    });

    const result = response.text;
    if (!result) throw new Error("Resposta vazia da IA");

    // Extrai metadados de fontes se houver (Grounding)
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return {
      data: JSON.parse(result.trim()),
      sources: sources.map((s: any) => s.web?.uri).filter(Boolean)
    };
  } catch (e) {
    console.error("Erro na extração via Gemini:", e);
    return null;
  }
}

