import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  const model = 'gemini-3-flash-preview';
  const isUrl = rawText.trim().startsWith('http');

  const systemInstructions = {
    event: `Você é um assistente de eventos de samba. Extraia as informações e retorne APENAS um JSON válido.
    IMPORTANTE: Se o link for de rede social (Instagram/Facebook), use sua ferramenta de busca para encontrar a URL direta da imagem (display_url ou similar) ou o link da imagem de capa.
    Campos: 
    title (max 30 chars), 
    day (número), 
    month (3 letras maiúsculas), 
    location (local), 
    price (atrações ou valor), 
    label (uma palavra chave), 
    image_url (URL direta da imagem se encontrar, caso contrário null), 
    search_term (termo em inglês para busca visual caso image_url seja null).`,

    video: "Extraia informações de um vídeo. Retorne APENAS um JSON válido com: title (título limpo), category (Ao Vivo, Clipe, etc).",
    article: "Extraia informações de um post. Retorne APENAS um JSON válido com: title, excerpt, category, read_time."
  };

  try {
    const config: any = {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json",
      temperature: 0.1,
    };

    if (isUrl) {
      config.tools = [{ googleSearch: {} }];
    }

    const prompt = isUrl 
      ? `Acesse este link e extraia os detalhes. FOCO EM ENCONTRAR A IMAGEM DO POST se for Instagram: ${rawText}`
      : `Processe o seguinte conteúdo: "${rawText}"`;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config,
    });

    const result = response.text;
    if (!result) throw new Error("Resposta vazia da IA");

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return {
      data: JSON.parse(result.trim()),
      sources: sources.map((s: any) => s.web?.uri).filter(Boolean)
    };
  } catch (e) {
    console.error("Erro na extração via Gemini:", e);
    return null;
  }
}

