  const startSync = async (type: 'event' | 'video' | 'article') => {
    if (dbStatus !== 'connected') return alert("Erro de banco de dados.");
    if (!syncText.trim()) return alert("Cole o texto ou link primeiro.");

    setLoading(true);
    try {
      const result = await parseContentWithAI(syncText, type);
      if (!result || !result.data) throw new Error("A IA não conseguiu ler os dados. Tente copiar o texto manualmente.");

      const parsed = result.data;
