        const finalImageUrl = parsed.image_url || `https://images.unsplash.com/photo-1514525253361-bee8718a300a?auto=format&fit=crop&q=80&sig=${parsed.search_term || 'samba'}`;
        setPreviewData({ ...parsed, type, image_url: finalImageUrl, ticket_url: syncText.startsWith('http') ? syncText : '' });
