import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  const model = 'gemini-3-flash-preview';
  const isUrl = rawText.trim().startsWith('http');

  const systemInstructions = {
    event: `Você é um especialista em eventos culturais. Sua tarefa é extrair dados para um JSON.
    Se for um link (Instagram/Sympla/etc), use sua ferramenta de busca para encontrar:
    1. O título real do evento.
    2. A data exata.
    3. O local.
    4. A URL DIRETA DA IMAGEM (procure por links terminando em .jpg, .png ou display_url).

    Retorne APENAS um JSON:
    {
      "title": "string (max 30 chars)",
      "day": "string (número)",
      "month": "string (3 letras maiúsculas)",
      "location": "string",
      "price": "string",
      "label": "string (uma palavra)",
      "image_url": "string (URL da imagem encontrada ou null)",
      "search_term": "string (termo para Unsplash se image_url for null)"
    }`,
    video: "Extraia dados de vídeo para JSON: {title, category}.",
    article: "Extraia dados de editorial para JSON: {title, excerpt, category, read_time}."
  };

  try {
    const config: any = {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json",
      temperature: 0.1,
    };

    if (isUrl) {
      config.tools = [{ googleSearch: {} }];
    }

    const prompt = isUrl 
      ? `Analise este link e extraia os dados solicitados, especialmente a imagem do post: ${rawText}`
      : `Processe este texto: "${rawText}"`;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config,
    });

    const result = response.text;
    if (!result) throw new Error("IA não retornou dados.");

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return {
      data: JSON.parse(result.trim()),
      sources: sources.map((s: any) => s.web?.uri).filter(Boolean)
    };
  } catch (e) {
    console.error("Erro Gemini:", e);
    return null;
  }
}

