// Motor de Dados Local - Salva direto no navegador sem necessidade de chaves externas
const STORAGE_KEY = 'temsambaai_db';

const getStorage = () => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : { events: [], videos: [], articles: [], interactions: [] };
};

const saveStorage = (data: any) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const supabase = {
  from: (table: string) => ({
    select: (query: string = '*', options: any = {}) => {
      const db = getStorage();
      let data = db[table] || [];

      if (options.count === 'exact') {
        return Promise.resolve({ count: data.length, data: data, error: null });
      }

      // Simulação de ordenação por data de criação
      const sorted = [...data].sort((a, b) => 
        new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime()
      );

      return {
        order: () => ({
          limit: (n: number) => Promise.resolve({ data: sorted.slice(0, n), error: null }),
          then: (cb: any) => Promise.resolve({ data: sorted, error: null }).then(cb)
        }),
        eq: (col: string, val: any) => Promise.resolve({ data: data.filter((i: any) => i[col] === val), error: null }),
        limit: (n: number) => Promise.resolve({ data: sorted.slice(0, n), error: null }),
        then: (cb: any) => Promise.resolve({ data: sorted, error: null }).then(cb)
      };
    },
    insert: (payload: any[]) => {
      const db = getStorage();
      const newItems = payload.map(item => ({
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date().toISOString()
      }));
      db[table] = [...(db[table] || []), ...newItems];
      saveStorage(db);
      return Promise.resolve({ error: null });
    },
    delete: () => ({
      eq: (col: string, val: any) => {
        const db = getStorage();
        db[table] = (db[table] || []).filter((i: any) => i[col] !== val);
        saveStorage(db);
        return Promise.resolve({ error: null });
      }
    })
  })
};

