// Motor de Dados Local - Salva direto no navegador sem necessidade de chaves externas
const STORAGE_KEY = 'temsambaai_db';

const getStorage = () => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : { events: [], videos: [], articles: [], interactions: [] };
};

const saveStorage = (data: any) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

/**
 * Mock Supabase client providing a chainable and thenable interface.
 * This mimics the real Supabase SDK behavior to ensure compatibility with 
 * existing component logic and fix TypeScript property-not-found errors.
 */
export const supabase = {
  from: (table: string) => {
    const getItems = () => getStorage()[table] || [];

    const createQueryChain = (initialItems: any[]) => {
      let data = [...initialItems];
      let error: any = null;

      const chain: any = {
        // Implements thenable to allow 'await' on the chain itself
        then: (onfulfilled?: (value: any) => any) => {
          return Promise.resolve({ data, error, count: data.length }).then(onfulfilled);
        },
        order: (col: string, options: { ascending?: boolean } = {}) => {
          const ascending = options.ascending !== false;
          data.sort((a, b) => {
            const valA = a[col] || 0;
            const valB = b[col] || 0;
            if (valA < valB) return ascending ? -1 : 1;
            if (valA > valB) return ascending ? 1 : -1;
            return 0;
          });
          return chain;
        },
        eq: (col: string, val: any) => {
          data = data.filter((i: any) => i[col] === val);
          return chain;
        },
        limit: (n: number) => {
          data = data.slice(0, n);
          return chain;
        }
      };
      return chain;
    };

    return {
      select: (query: string = '*', options: any = {}) => {
        return createQueryChain(getItems());
      },
      insert: (payload: any[]) => {
        const db = getStorage();
        const newItems = payload.map(item => ({
          ...item,
          id: item.id || Math.random().toString(36).substr(2, 9),
          created_at: new Date().toISOString()
        }));
        db[table] = [...(db[table] || []), ...newItems];
        saveStorage(db);
        return Promise.resolve({ error: null });
      },
      delete: () => {
        const filters: { col: string; val: any }[] = [];
        const chain: any = {
          eq: (col: string, val: any) => {
            filters.push({ col, val });
            return chain;
          },
          then: (onfulfilled?: (value: any) => any) => {
            const db = getStorage();
            if (db[table]) {
              db[table] = db[table].filter((item: any) => {
                if (filters.length === 0) return true; // Safety: do not delete if no filters provided
                // Check if item matches ALL filters for deletion
                const matchesAll = filters.every(f => item[f.col] === f.val);
                return !matchesAll; // Keep if it doesn't match all filters
              });
              saveStorage(db);
            }
            return Promise.resolve({ error: null }).then(onfulfilled);
          }
        };
        return chain;
      }
    };
  }
};

import { GoogleGenAI, Type } from "@google/genai";

// Initialize the Google GenAI client correctly with named parameter
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Parses content from raw text or URLs using Gemini 3.
 * Adheres to guidelines for model selection and response handling.
 */
export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  // Use 'gemini-3-flash-preview' for basic text extraction tasks
  const model = 'gemini-3-flash-preview';
  const isUrl = rawText.trim().startsWith('http');

  const systemInstructions = {
    event: `Você é um scanner de eventos. Extraia dados para JSON. 
    Se o link for Instagram/Facebook/Sympla, use o Google Search para encontrar a URL DA IMAGEM PRINCIPAL (geralmente termina em .jpg ou .png). 
    No Instagram, procure por 'display_url' ou a imagem de capa do post.
    Retorne APENAS: { "title": "max 30 letras", "day": "00", "month": "3 letras", "location": "local", "price": "atrações", "image_url": "link_da_foto_real", "search_term": "busca_alternativa" }`,
    video: "Extraia: {title, category}. Se for YouTube, pegue o título real.",
    article: "Extraia: {title, excerpt, category, read_time}."
  };

  try {
    const config: any = {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json",
      temperature: 0.1,
    };

    // Only googleSearch tool is allowed for text grounding
    if (isUrl) config.tools = [{ googleSearch: {} }];

    const prompt = isUrl 
      ? `EXTRAIA A IMAGEM REAL DESTE POST: ${rawText}` 
      : `Analise este texto: "${rawText}"`;

    // Always call generateContent directly via ai.models.generateContent
    const response = await ai.models.generateContent({ 
      model, 
      contents: prompt, 
      config 
    });

    // Direct access to the .text property for extracted content
    const result = response.text;
    if (!result) return null;

    return {
      data: JSON.parse(result.trim()),
      // Extract grounding sources for UI attribution
      sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((s: any) => s.web?.uri).filter(Boolean) || []
    };
  } catch (e) {
    console.error("Erro Gemini:", e);
    return null;
  }
}

