// Motor de Persistência de Interações Sociais (LocalStorage)
const STORAGE_KEY = 'temsambaai_social_db';

const getSocialData = () => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : { interactions: [] };
};

const saveSocialData = (data: any) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const supabase = {
  from: (table: string) => {
    // The current mock persists everything in the 'interactions' key for simplicity.
    const getData = () => getSocialData().interactions;

    return {
      // Refactored select to support chained filters with correct AND logic and deferred execution
      select: (query: string = '*', options: any = {}) => {
        let filters: Array<{col: string, val: any}> = [];
        const chain: any = {
          eq: (col: string, val: any) => {
            filters.push({ col, val });
            return chain;
          },
          order: () => chain,
          limit: () => chain,
          // Support for await by implementing then()
          then: (onfulfilled?: (value: any) => any) => {
            let items = getData();
            // Apply all filters in sequence (AND logic)
            filters.forEach(f => {
              items = items.filter((i: any) => i[f.col] === f.val);
            });
            return Promise.resolve({ data: items, error: null, count: items.length }).then(onfulfilled);
          }
        };
        return chain;
      },
      insert: (payload: any[]) => {
        const db = getSocialData();
        const newItems = payload.map(item => ({
          ...item,
          id: Math.random().toString(36).substr(2, 9),
          created_at: new Date().toISOString()
        }));
        db.interactions = [...db.interactions, ...newItems];
        saveSocialData(db);
        return Promise.resolve({ error: null });
      },
      // Fixed delete method to support chained .eq() filters. 
      // Previously it returned a Promise after the first .eq(), causing errors on subsequent chain calls.
      delete: () => {
        let filters: Array<{col: string, val: any}> = [];
        const chain: any = {
          eq: (col: string, val: any) => {
            filters.push({ col, val });
            return chain;
          },
          // Support for await by implementing then()
          then: (onfulfilled?: (value: any) => any) => {
            const db = getSocialData();
            // We assume all delete operations apply to the 'interactions' collection in this mock
            db.interactions = db.interactions.filter((i: any) => {
              // Row should be deleted if it matches ALL filters
              if (filters.length === 0) return true; // If no filters, keep everything (safety)
              const matchesAll = filters.every(f => i[f.col] === f.val);
              // filter() returns true to keep, false to remove. 
              // So we return !matchesAll to remove rows that match all filters.
              return !matchesAll;
            });
            saveSocialData(db);
            return Promise.resolve({ error: null }).then(onfulfilled);
          }
        };
        return chain;
      }
    };
  }
};

