        setEvents(SITE_CONTENT.events.slice(0, 3));
        setIsLive(false);
      } finally {
        setLoading(false);
      }
    };

    fetchEvents();
  }, []);

  return (
    <section className="w-full">
      <div className="max-w-6xl mx-auto mb-20 relative flex flex-col md:flex-row md:items-end justify-between gap-8">
        <div>
