// Motor de Persistência de Interações Sociais (LocalStorage)
const STORAGE_KEY = 'temsambaai_social_db';

const getSocialData = () => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : { interactions: [], events: [], videos: [], articles: [] };
};

const saveSocialData = (data: any) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const supabase = {
  from: (table: string) => {
    const getData = () => {
      const db = getSocialData();
      return db[table] || db.interactions || [];
    };

    return {
      select: (query: string = '*', options: any = {}) => {
        let filters: Array<{col: string, val: any}> = [];
        const chain: any = {
          eq: (col: string, val: any) => {
            filters.push({ col, val });
            return chain;
          },
          order: () => chain,
          limit: () => chain,
          then: (onfulfilled?: (value: any) => any) => {
            let items = getData();
            filters.forEach(f => {
              items = items.filter((i: any) => i[f.col] === f.val);
            });
            return Promise.resolve({ data: items, error: null, count: items.length }).then(onfulfilled);
          }
        };
        return chain;
      },
      insert: (payload: any[]) => {
        const db = getSocialData();
        const tableKey = ['events', 'videos', 'articles'].includes(table) ? table : 'interactions';
        const newItems = payload.map(item => ({
          ...item,
          id: item.id || Math.random().toString(36).substr(2, 9),
          created_at: new Date().toISOString()
        }));
        db[tableKey] = [...(db[tableKey] || []), ...newItems];
        saveSocialData(db);
        return Promise.resolve({ error: null });
      },
      update: (payload: any) => {
        let filters: Array<{col: string, val: any}> = [];
        const chain: any = {
          eq: (col: string, val: any) => {
            filters.push({ col, val });
            return chain;
          },
          then: (onfulfilled?: (value: any) => any) => {
            const db = getSocialData();
            const tableKey = ['events', 'videos', 'articles'].includes(table) ? table : 'interactions';
            db[tableKey] = (db[tableKey] || []).map((i: any) => {
              const matchesAll = filters.every(f => i[f.col] === f.val);
              return matchesAll ? { ...i, ...payload } : i;
            });
            saveSocialData(db);
            return Promise.resolve({ error: null }).then(onfulfilled);
          }
        };
        return chain;
      },
      delete: () => {
        let filters: Array<{col: string, val: any}> = [];
        const chain: any = {
          eq: (col: string, val: any) => {
            filters.push({ col, val });
            return chain;
          },
          then: (onfulfilled?: (value: any) => any) => {
            const db = getSocialData();
            const tableKey = ['events', 'videos', 'articles'].includes(table) ? table : 'interactions';
            db[tableKey] = (db[tableKey] || []).filter((i: any) => {
              const matchesAll = filters.every(f => i[f.col] === f.val);
              return !matchesAll;
            });
            saveSocialData(db);
            return Promise.resolve({ error: null }).then(onfulfilled);
          }
        };
        return chain;
      }
    };
  }
};

import React, { useState, useEffect } from 'react';
