  const [manageType, setManageType] = useState<'events' | 'videos' | 'articles'>('events');
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [syncText, setSyncText] = useState('');
  const [editingItem, setEditingItem] = useState<any>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  useEffect(() => {
    fetchStats();
  }, []);

  useEffect(() => {
    if (activeTab === 'acervo') fetchItems();
  }, [activeTab, manageType]);

  const fetchStats = async () => {
    const { count: e } = await supabase.from('events').select('*', { count: 'exact' });
    const { count: v } = await supabase.from('videos').select('*', { count: 'exact' });
    const { count: a } = await supabase.from('articles').select('*', { count: 'exact' });
    setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
  };

  const fetchItems = async () => {
    setLoading(true);
    const { data } = await (supabase.from(manageType).select('*') as any);
    setItems(data || []);
    setLoading(false);
  };

  const handleSync = async (type: 'event' | 'video' | 'article') => {
    setLoading(true);
    try {
      const result = await parseContentWithAI(syncText, type);
      if (!result) throw new Error("A IA não conseguiu ler o conteúdo.");

      const parsed = result.data;
      setEditingItem({ 
        ...parsed, 
        id: Math.random().toString(36).substr(2, 9),
        type: type === 'event' ? 'events' : type === 'video' ? 'videos' : 'articles',
        image_url: parsed.image_url || 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?q=80',
        thumbnail: parsed.image_url || 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?q=80',
      });
      setSyncText('');
    } catch (e: any) {
      alert(e.message);
    } finally {
      setLoading(false);
    }
  };

  const saveItem = async () => {
    setLoading(true);
    try {
      const { type, ...payload } = editingItem;
      const table = type || manageType;

      const { data: existing } = await supabase.from(table).select('*').eq('id', payload.id);

      if (existing && existing.length > 0) {
        await supabase.from(table).update(payload).eq('id', payload.id);
      } else {
        await supabase.from(table).insert([payload]);
      }

      alert("Material salvo com sucesso!");
      setEditingItem(null);
      fetchItems();
      fetchStats();
    } catch (e) {
      alert("Erro ao salvar.");
    } finally {
      setLoading(false);
    }
  };

  const deleteItem = async (id: string) => {
    if (!confirm("Excluir definitivamente?")) return;
    await supabase.from(manageType).delete().eq('id', id);
    setItems(items.filter(i => i.id !== id));
    fetchStats();
  };

  if (!isLoggedIn) {
    return (
      <div className="fixed inset-0 z-[100] bg-black/98 flex items-center justify-center font-display">
        <div className="w-full max-w-sm p-10 bg-card-dark rounded-[3rem] border border-white/10 shadow-3xl text-center">
          <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-8">
            <span className="material-symbols-outlined text-primary text-4xl">admin_panel_settings</span>
          </div>
          <h2 className="text-2xl font-black uppercase tracking-tighter text-white mb-2">Área Administrativa</h2>
          <p className="text-white/40 text-[10px] uppercase tracking-widest mb-8">Gestão do Radar Tem Samba Aí</p>
          <input 
            type="password" 
            placeholder="Chave de Acesso" 
            className="w-full bg-white/5 border border-white/5 focus:border-primary outline-none p-5 rounded-2xl text-center mb-4 transition-all"
            value={pass}
            onChange={e => setPass(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && pass === 'samba2025' && setIsLoggedIn(true)}
          />
          <button 
            onClick={() => { if(pass==='samba2025') {setIsLoggedIn(true);} else alert('Chave incorreta'); }}
            className="w-full bg-primary hover:bg-white text-white hover:text-black font-black py-5 rounded-2xl uppercase text-xs tracking-widest transition-all"
          >
            Entrar no Sistema
          </button>
          <button onClick={onClose} className="mt-6 text-[10px] font-black text-white/20 hover:text-white uppercase tracking-widest">Voltar ao site</button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] bg-background-dark text-white font-display flex overflow-hidden">
      {/* Sidebar */}
      <aside className="w-24 md:w-72 bg-card-dark border-r border-white/5 flex flex-col p-6 md:p-10">
        <div className="flex items-center gap-4 mb-16">
          <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center shrink-0">
            <span className="material-symbols-outlined text-white text-2xl">hub</span>
          </div>
          <div className="hidden md:block">
            <h1 className="font-black text-sm uppercase tracking-tighter">SAMBA<span className="text-primary">SYNC</span></h1>
            <p className="text-[8px] text-white/30 uppercase font-bold tracking-widest">Painel de Controle</p>
          </div>
        </div>

        <nav className="space-y-4 flex-1">
          <button onClick={() => setActiveTab('radar')} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === 'radar' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
            <span className="material-symbols-outlined">bolt</span>
            <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Radar IA</span>
          </button>
          <button onClick={() => setActiveTab('acervo')} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === 'acervo' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
            <span className="material-symbols-outlined">inventory_2</span>
            <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Acervo</span>
          </button>
          <button onClick={() => setActiveTab('stats')} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === 'stats' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
            <span className="material-symbols-outlined">analytics</span>
            <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Estatísticas</span>
          </button>
        </nav>

        <button onClick={() => {setIsLoggedIn(false); onClose();}} className="flex items-center gap-4 p-4 rounded-2xl text-red-500/50 hover:text-red-500 hover:bg-red-500/5 transition-all mt-auto">
          <span className="material-symbols-outlined">logout</span>
          <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Sair</span>
        </button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-8 md:p-16 relative">
        {activeTab === 'radar' && (
          <div className="max-w-3xl mx-auto space-y-12 animate-fade-in-up">
            <header>
              <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter leading-none mb-4">CAPTURAR <br/><span className="text-primary">CONTEÚDO</span></h2>
              <p className="text-white/40 text-sm font-light uppercase tracking-widest">A IA do Radar busca as informações para você.</p>
            </header>

            <div className="bg-card-dark p-8 rounded-[3rem] border border-white/10 shadow-2xl relative group">
              <textarea 
                className="w-full bg-black/30 border border-white/5 p-8 rounded-[2rem] text-white outline-none focus:border-primary/50 h-56 font-light text-xl mb-8 placeholder:text-white/10 resize-none"
                placeholder="Cole aqui o link do Instagram, texto de zap ou informações do evento/post..."
                value={syncText}
                onChange={e => setSyncText(e.target.value)}
              />
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <button onClick={() => handleSync('event')} className="bg-white/5 hover:bg-primary p-8 rounded-3xl flex flex-col items-center justify-center gap-3 transition-all group/btn shadow-lg">
                  <span className="material-symbols-outlined text-4xl text-primary group-hover:btn:text-white transition-colors">event</span>
                  <span className="font-black text-[9px] uppercase tracking-widest">Novo Evento</span>
                </button>
                <button onClick={() => handleSync('video')} className="bg-white/5 hover:bg-primary p-8 rounded-3xl flex flex-col items-center justify-center gap-3 transition-all group/btn shadow-lg">
                  <span className="material-symbols-outlined text-4xl text-primary group-hover/btn:text-white transition-colors">movie</span>
                  <span className="font-black text-[9px] uppercase tracking-widest">Novo Vídeo</span>
                </button>
                <button onClick={() => handleSync('article')} className="bg-white/5 hover:bg-primary p-8 rounded-3xl flex flex-col items-center justify-center gap-3 transition-all group/btn shadow-lg">
                  <span className="material-symbols-outlined text-4xl text-primary group-hover/btn:text-white transition-colors">article</span>
                  <span className="font-black text-[9px] uppercase tracking-widest">Novo Artigo</span>
                </button>
              </div>
              {loading && (
                <div className="absolute inset-0 bg-black/90 backdrop-blur-xl rounded-[3rem] flex flex-col items-center justify-center z-50">
                  <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
                  <p className="font-black text-xs uppercase tracking-[0.4em] text-primary animate-pulse">Sincronizando Radar...</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'acervo' && (
          <div className="max-w-5xl mx-auto space-y-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-8 border-b border-white/5 pb-10">
              <div>
                <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter leading-none mb-4">GESTÃO DO <br/><span className="text-primary">ACERVO</span></h2>
                <div className="flex gap-4">
                  {(['events', 'videos', 'articles'] as const).map(t => (
                    <button key={t} onClick={() => setManageType(t)} className={`px-6 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${manageType === t ? 'bg-primary border-primary text-white' : 'border-white/10 text-white/30 hover:text-white'}`}>
                      {t==='events'?'Agenda':t==='videos'?'Vídeos':'Posts'}
                    </button>
                  ))}
                </div>
              </div>
              <button 
                onClick={() => setEditingItem({ id: Math.random().toString(36).substr(2, 9), type: manageType, title: '', image_url: '', location: '', price: '', day: '', month: '', category: '', excerpt: '', content: '' })}
                className="bg-white text-black px-10 py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-primary hover:text-white transition-all shadow-xl"
              >
                + Adicionar Manual
              </button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {loading ? (
                <div className="col-span-full py-20 text-center"><div className="w-10 h-10 border-4 border-primary/20 border-t-primary rounded-full animate-spin mx-auto"></div></div>
              ) : items.length > 0 ? (
                items.map(item => (
                  <div key={item.id} className="bg-card-dark border border-white/5 rounded-3xl p-6 flex flex-col gap-6 hover:border-primary/40 transition-all group relative overflow-hidden">
                    <div className="flex items-center gap-4">
                      <div className="w-16 h-16 rounded-2xl overflow-hidden bg-black shrink-0 border border-white/5">
                        <img src={item.image_url || item.thumbnail} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <h4 className="font-black uppercase text-xs truncate text-white leading-tight mb-1">{item.title}</h4>
                        <p className="text-[8px] text-white/30 font-bold uppercase truncate tracking-widest">{item.location || item.category || 'Sem Local'}</p>
                      </div>
                    </div>
                    <div className="flex gap-2 mt-auto">
                      <button onClick={() => setEditingItem({...item, type: manageType})} className="flex-1 bg-white/5 py-3 rounded-xl font-black uppercase text-[9px] hover:bg-primary transition-all">Editar</button>
                      <button onClick={() => deleteItem(item.id)} className="w-12 bg-red-500/10 text-red-500 py-3 rounded-xl hover:bg-red-500 hover:text-white transition-all flex items-center justify-center">
                        <span className="material-symbols-outlined text-lg">delete</span>
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="col-span-full py-32 text-center bg-white/5 rounded-[3rem] border border-dashed border-white/10">
                  <span className="material-symbols-outlined text-6xl text-white/5 mb-4">folder_open</span>
                  <p className="text-white/20 font-black uppercase text-xs tracking-widest">Nada encontrado nesta seção.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="max-w-4xl mx-auto space-y-12 animate-fade-in">
             <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter mb-12">NÚMEROS DO <br/><span className="text-primary">SAMBA</span></h2>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/5 text-center">
                   <h4 className="text-primary font-black text-6xl mb-2">{stats.events}</h4>
                   <p className="text-[10px] uppercase font-black tracking-widest text-white/30">Eventos Ativos</p>
                </div>
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/5 text-center">
                   <h4 className="text-primary font-black text-6xl mb-2">{stats.videos}</h4>
                   <p className="text-[10px] uppercase font-black tracking-widest text-white/30">Vídeos no Acervo</p>
                </div>
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/5 text-center">
                   <h4 className="text-primary font-black text-6xl mb-2">{stats.articles}</h4>
                   <p className="text-[10px] uppercase font-black tracking-widest text-white/30">Artigos Publicados</p>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Edit Modal */}
      {editingItem && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6 overflow-y-auto font-display">
          <div className="w-full max-w-2xl bg-card-dark border border-white/10 rounded-[3rem] p-10 shadow-3xl animate-fade-in-up">
            <header className="flex justify-between items-center mb-10">
              <div>
                <h3 className="text-3xl font-black uppercase text-primary tracking-tighter">Editar Material</h3>
                <p className="text-[9px] uppercase font-bold text-white/30 tracking-widest">Revise os campos abaixo antes de salvar</p>
              </div>
              <button onClick={() => setEditingItem(null)} className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center hover:bg-red-500 transition-all">
                <span className="material-symbols-outlined">close</span>
              </button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
              <div className="col-span-full">
                <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Título do Item</label>
                <input 
                  type="text" 
                  value={editingItem.title} 
                  onChange={e => setEditingItem({...editingItem, title: e.target.value})}
                  className="w-full bg-white/5 border border-white/5 focus:border-primary p-5 rounded-2xl outline-none font-bold"
                />
              </div>

              {editingItem.type === 'events' && (
                <>
                  <div>
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Dia</label>
                    <input type="text" value={editingItem.day} onChange={e => setEditingItem({...editingItem, day: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" placeholder="Ex: 22" />
                  </div>
                  <div>
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Mês</label>
                    <input type="text" value={editingItem.month} onChange={e => setEditingItem({...editingItem, month: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" placeholder="Ex: JAN" />
                  </div>
                  <div className="col-span-full">
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Localização / Horário</label>
                    <input type="text" value={editingItem.location} onChange={e => setEditingItem({...editingItem, location: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" />
                  </div>
                </>
              )}

              {editingItem.type === 'videos' && (
                <>
                  <div className="col-span-full">
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">URL do Vídeo (Youtube)</label>
                    <input type="text" value={editingItem.video_url} onChange={e => setEditingItem({...editingItem, video_url: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" />
                  </div>
                  <div>
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Categoria</label>
                    <input type="text" value={editingItem.category} onChange={e => setEditingItem({...editingItem, category: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" />
                  </div>
                </>
              )}

              <div className="col-span-full">
                <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">URL da Imagem / Capa</label>
                <input 
                  type="text" 
                  value={editingItem.image_url || editingItem.thumbnail} 
                  onChange={e => setEditingItem({...editingItem, image_url: e.target.value, thumbnail: e.target.value})}
                  className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none text-[10px]"
                />
              </div>
            </div>

            <div className="flex gap-4">
              <button onClick={() => setEditingItem(null)} className="flex-1 py-5 border border-white/10 rounded-2xl font-black uppercase text-xs tracking-widest">Cancelar</button>
              <button onClick={saveItem} className="flex-1 py-5 bg-primary text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-2xl shadow-primary/30">Salvar Alterações</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface SocialActionsProps {
  contentId: string;
}

const SocialActions: React.FC<SocialActionsProps> = ({ contentId }) => {
  const [likes, setLikes] = useState(0);
  const [hasLiked, setHasLiked] = useState(false);
  const [showCommentInput, setShowCommentInput] = useState(false);
  const [comment, setComment] = useState('');
  const [instagram, setInstagram] = useState('');
  const [commentsList, setCommentsList] = useState<{user_insta: string, text: string}[]>([]);

  useEffect(() => {
    fetchInteractions();
  }, [contentId, instagram]);

  const fetchInteractions = async () => {
    try {
      // Buscar curtidas
      const { count } = await supabase.from('interactions').select('*', { count: 'exact', head: true }).eq('content_id', contentId).eq('type', 'like');
      setLikes(count || 0);

      // Buscar se o usuário já curtiu
      if (instagram) {
          const { data } = await supabase.from('interactions').select('*').eq('content_id', contentId).eq('type', 'like').eq('user_insta', instagram);
          if (data && data.length > 0) setHasLiked(true);
          else setHasLiked(false);
      }

      // Buscar comentários
      const { data: comments } = await supabase.from('interactions').select('user_insta, text').eq('content_id', contentId).eq('type', 'comment').order('created_at', { ascending: false });
      setCommentsList(comments || []);
    } catch (err) { console.error(err); }
  };

  const handleLike = async () => {
    let currentInsta = instagram;
    if (!currentInsta) {
      const input = prompt("Para interagir, digite seu @ do Instagram:");
      if (input) {
        currentInsta = input.startsWith('@') ? input : `@${input}`;
        setInstagram(currentInsta);
      } else return;
    }

    try {
      if (hasLiked) {
        await supabase.from('interactions').delete().eq('content_id', contentId).eq('type', 'like').eq('user_insta', currentInsta);
        setHasLiked(false);
        setLikes(prev => prev - 1);
      } else {
        await supabase.from('interactions').insert([{ content_id: contentId, type: 'like', user_insta: currentInsta }]);
        setHasLiked(true);
        setLikes(prev => prev + 1);
      }
    } catch (err) { alert('Erro na conexão.'); }
  };

  const handleComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!comment.trim()) return;

    let currentInsta = instagram;
    if (!currentInsta) {
      const input = prompt("Seu @ do Instagram para comentar:");
      if (input) {
        currentInsta = input.startsWith('@') ? input : `@${input}`;
        setInstagram(currentInsta);
      } else return;
    }

    try {
      const { error } = await supabase.from('interactions').insert([{ content_id: contentId, type: 'comment', user_insta: currentInsta, text: comment }]);
      if (error) throw error;
      setCommentsList(prev => [{ user_insta: currentInsta, text: comment }, ...prev]);
      setComment('');
    } catch (err: any) { alert(err.message); }
  };

  return (
    <div className="w-full space-y-4">
      <div className="flex items-center gap-6">
        <button onClick={handleLike} className={`flex items-center gap-2 group transition-all ${hasLiked ? 'text-primary' : 'text-white/40 hover:text-white'}`}>
          <span className={`material-symbols-outlined text-2xl ${hasLiked ? 'filled' : ''}`}>{hasLiked ? 'favorite' : 'favorite'}</span>
          <span className="text-[10px] font-black uppercase tracking-widest">{likes} curtidas</span>
        </button>

        <button onClick={() => setShowCommentInput(!showCommentInput)} className="flex items-center gap-2 text-white/40 hover:text-white group">
          <span className="material-symbols-outlined text-2xl group-hover:rotate-12 transition-transform">chat_bubble</span>
          <span className="text-[10px] font-black uppercase tracking-widest">{commentsList.length}</span>
        </button>

        {instagram && (
          <div className="ml-auto flex items-center gap-2 opacity-30">
             <span className="text-[9px] font-black text-primary uppercase">{instagram}</span>
             <button onClick={() => { setInstagram(''); }} className="material-symbols-outlined text-xs">close</button>
          </div>
        )}
      </div>

      {showCommentInput && (
        <div className="pt-4 animate-fade-in-up">
          <form onSubmit={handleComment} className="flex gap-2 mb-4">
            <input type="text" value={comment} onChange={e => setComment(e.target.value)} placeholder="Comentar..." className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:border-primary outline-none" />
            <button type="submit" className="bg-primary text-white px-4 py-2 rounded-xl"><span className="material-symbols-outlined text-sm">send</span></button>
          </form>
          <div className="space-y-3 max-h-[120px] overflow-y-auto pr-2 no-scrollbar">
            {commentsList.map((c, i) => (
              <div key={i} className="flex flex-col gap-1 border-l border-primary/20 pl-3">
                <span className="text-primary font-bold text-[10px]">{c.user_insta}</span>
                <span className="text-white/60 text-xs font-light">{c.text}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

