import { GoogleGenAI, Type } from "@google/genai";

/**
 * Parses content from raw text or URLs using Gemini 3.
 * Adheres to guidelines for model selection and response handling.
 */
export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  // Always create a new GoogleGenAI instance right before making an API call 
  // to ensure it always uses the most up-to-date API key from the environment.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Use 'gemini-3-flash-preview' for basic text extraction tasks
  const model = 'gemini-3-flash-preview';
  const isUrl = rawText.trim().startsWith('http');

  const systemInstructions = {
    event: `Você é um scanner de eventos. Extraia dados para JSON. 
    Se o link for Instagram/Facebook/Sympla, use o Google Search para encontrar a URL DA IMAGEM PRINCIPAL (geralmente termina em .jpg ou .png). 
    No Instagram, procure por 'display_url' ou a imagem de capa do post.
    Retorne APENAS: { "title": "max 30 letras", "day": "00", "month": "3 letras", "location": "local", "price": "atrações", "image_url": "link_da_foto_real", "search_term": "busca_alternativa" }`,
    video: "Extraia: {title, category}. Se for YouTube, pegue o título real.",
    article: "Extraia: {title, excerpt, category, read_time}."
  };

  try {
    const config: any = {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json",
      temperature: 0.1,
    };

    // Only googleSearch tool is allowed for text grounding
    if (isUrl) config.tools = [{ googleSearch: {} }];

    const prompt = isUrl 
      ? `EXTRAIA A IMAGEM REAL DESTE POST: ${rawText}` 
      : `Analise este texto: "${rawText}"`;

    // Always call generateContent directly via ai.models.generateContent
    const response = await ai.models.generateContent({ 
      model, 
      contents: prompt, 
      config 
    });

    // Direct access to the .text property for extracted content
    const result = response.text;
    if (!result) return null;

    return {
      data: JSON.parse(result.trim()),
      // Extract grounding sources for UI attribution
      sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((s: any) => s.web?.uri).filter(Boolean) || []
    };
  } catch (e) {
    console.error("Erro Gemini:", e);
    return null;
  }
}

