      // IDs gerados pela IA ou temporários geralmente não existem no banco.
      let result;

      // Tentamos buscar se o ID existe de fato no banco (evita erros de chave primária duplicada)
      const { data: existing } = editingItem.id ? await supabase.from(table).select('id').eq('id', editingItem.id).single() : { data: null };

      if (existing) {
