                    <textarea value={editingItem.content || ''} onChange={e => setEditingItem({...editingItem, content: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none h-48" />
                  </div>
                  <div>
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Tempo de Leitura</label>
                    <input type="text" value={editingItem.read_time || ''} onChange={e => setEditingItem({...editingItem, read_time: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" placeholder="Ex: 5 min" />
                  </div>
                  <div>
                    <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">Categoria</label>
                    <input type="text" value={editingItem.category || ''} onChange={e => setEditingItem({...editingItem, category: e.target.value})} className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none" />
                  </div>
                </>
              )}

              <div className="col-span-full">
                <label className="text-[9px] font-black uppercase text-white/20 mb-2 block tracking-widest">URL da Imagem / Capa</label>
                <input 
                  type="text" 
                  value={editingItem.image_url || editingItem.thumbnail || ''} 
                  onChange={e => setEditingItem({...editingItem, image_url: e.target.value, thumbnail: e.target.value})}
                  className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl outline-none text-[10px]"
                />
              </div>
            </div>

            <div className="flex gap-4">
              <button onClick={() => setEditingItem(null)} className="flex-1 py-5 border border-white/10 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-white/5 transition-all">Cancelar</button>
              <button onClick={saveItem} disabled={loading} className="flex-1 py-5 bg-primary text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50">
                {loading ? 'Salvando...' : 'Confirmar e Salvar'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { parseContentWithAI } from '../lib/gemini';
import type { Session } from '@supabase/supabase-js';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [session, setSession] = useState<Session | null>(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const [activeTab, setActiveTab] = useState<'radar' | 'acervo' | 'stats'>('radar');
  const [manageType, setManageType] = useState<'events' | 'videos' | 'articles'>('events');
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [syncText, setSyncText] = useState('');
  const [editingItem, setEditingItem] = useState<any>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  // 1. Monitorar estado de autenticação
  useEffect(() => {
    // Pegar sessão inicial
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
    });

    // Escutar mudanças (login/logout)
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      fetchStats();
      if (activeTab === 'acervo') fetchItems();
    }
  }, [session, activeTab, manageType]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password
      });
      if (error) throw error;
    } catch (err: any) {
      alert("Erro ao entrar: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    onClose();
  };

  const fetchStats = async () => {
    const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
  };

  const fetchItems = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from(manageType)
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      console.error(`Erro ao buscar ${manageType}:`, err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async (type: 'event' | 'video' | 'article') => {
    if (!syncText.trim()) return alert("Cole o conteúdo para a IA analisar.");
    setLoading(true);
    try {
      const result = await parseContentWithAI(syncText, type);
      if (!result) throw new Error("A IA não conseguiu processar este conteúdo.");

      const parsed = result.data;
      const targetTable = type === 'event' ? 'events' : type === 'video' ? 'videos' : 'articles';

      setEditingItem({ 
        ...parsed,
        type: targetTable,
        image_url: parsed.image_url || parsed.thumbnail || 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?q=80',
        thumbnail: parsed.image_url || parsed.thumbnail || 'https://images.unsplash.com/photo-1514525253361-bee8718a300a?q=80',
      });
      setSyncText('');
      setActiveTab('acervo');
    } catch (e: any) {
      alert(e.message);
    } finally {
      setLoading(false);
    }
  };

  const saveItem = async () => {
    if (!editingItem.title) return alert("O título é obrigatório.");
    setLoading(true);
    try {
      const table = editingItem.type || manageType;
      const { type, created_at, ...payload } = editingItem;

      let result;
      const { data: existing } = editingItem.id ? await supabase.from(table).select('id').eq('id', editingItem.id).single() : { data: null };

      if (existing) {
        result = await supabase.from(table).update(payload).eq('id', editingItem.id);
      } else {
        const { id, ...newPayload } = payload;
        result = await supabase.from(table).insert([newPayload]);
      }

      if (result.error) throw result.error;

      alert("Salvo com sucesso!");
      setEditingItem(null);
      fetchItems();
      fetchStats();
    } catch (e: any) {
      console.error("Erro ao salvar:", e);
      alert("Erro ao salvar: " + e.message);
    } finally {
      setLoading(false);
    }
  };

  const deleteItem = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir permanentemente?")) return;
    setLoading(true);
    try {
      const { error } = await supabase.from(manageType).delete().eq('id', id);
      if (error) throw error;

      setItems(items.filter(i => i.id !== id));
      fetchStats();
    } catch (e: any) {
      alert("Erro ao excluir: " + e.message);
    } finally {
      setLoading(false);
    }
  };

  // TELA DE LOGIN
  if (!session) {
    return (
      <div className="fixed inset-0 z-[100] bg-black/98 flex items-center justify-center font-display p-6">
        <div className="w-full max-w-sm p-10 bg-card-dark rounded-[3rem] border border-white/10 shadow-3xl text-center">
          <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-8">
            <span className="material-symbols-outlined text-primary text-4xl">lock_open</span>
          </div>
          <h2 className="text-2xl font-black uppercase tracking-tighter text-white mb-2">Login Administrativo</h2>
          <p className="text-white/40 text-[10px] uppercase tracking-widest mb-8">Acesso restrito ao radar</p>

          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              type="email" 
              placeholder="E-mail" 
              className="w-full bg-white/5 border border-white/5 focus:border-primary outline-none p-5 rounded-2xl text-center transition-all text-white"
              value={email}
              onChange={e => setEmail(e.target.value)}
              required
            />
            <input 
              type="password" 
              placeholder="Senha" 
              className="w-full bg-white/5 border border-white/5 focus:border-primary outline-none p-5 rounded-2xl text-center transition-all text-white"
              value={password}
              onChange={e => setPassword(e.target.value)}
              required
            />
            <button 
              type="submit"
              disabled={loading}
              className="w-full bg-primary hover:bg-white text-white hover:text-black font-black py-5 rounded-2xl uppercase text-xs tracking-widest transition-all disabled:opacity-50"
            >
              {loading ? 'Entrando...' : 'Acessar Sistema'}
            </button>
          </form>

          <button onClick={onClose} className="mt-6 text-[10px] font-black text-white/20 hover:text-white uppercase tracking-widest">Voltar ao site</button>
        </div>
      </div>
    );
  }

  // DASHBOARD PROTEGIDO
  return (
    <div className="fixed inset-0 z-[100] bg-background-dark text-white font-display flex overflow-hidden">
      {/* Sidebar */}
      <aside className="w-24 md:w-72 bg-card-dark border-r border-white/5 flex flex-col p-6 md:p-10">
        <div className="flex items-center gap-4 mb-16">
          <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center shrink-0">
            <span className="material-symbols-outlined text-white text-2xl">hub</span>
          </div>
          <div className="hidden md:block">
            <h1 className="font-black text-sm uppercase tracking-tighter">SAMBA<span className="text-primary">SYNC</span></h1>
            <p className="text-[8px] text-white/30 uppercase font-bold tracking-widest">{session.user.email}</p>
          </div>
        </div>

        <nav className="space-y-4 flex-1">
          <button onClick={() => setActiveTab('radar')} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === 'radar' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
            <span className="material-symbols-outlined">bolt</span>
            <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Radar IA</span>
          </button>
          <button onClick={() => setActiveTab('acervo')} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === 'acervo' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
            <span className="material-symbols-outlined">inventory_2</span>
            <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Acervo</span>
          </button>
          <button onClick={() => setActiveTab('stats')} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all ${activeTab === 'stats' ? 'bg-primary text-white' : 'text-white/30 hover:bg-white/5'}`}>
            <span className="material-symbols-outlined">analytics</span>
            <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Estatísticas</span>
          </button>
        </nav>

        <button onClick={handleLogout} className="flex items-center gap-4 p-4 rounded-2xl text-red-500/50 hover:text-red-500 hover:bg-red-500/5 transition-all mt-auto">
          <span className="material-symbols-outlined">logout</span>
          <span className="hidden md:block font-black text-[10px] uppercase tracking-widest">Sair</span>
        </button>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-8 md:p-16 relative">
        {activeTab === 'radar' && (
          <div className="max-w-3xl mx-auto space-y-12 animate-fade-in-up">
            <header>
              <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter leading-none mb-4">CAPTURAR <br/><span className="text-primary">CONTEÚDO</span></h2>
              <p className="text-white/40 text-sm font-light uppercase tracking-widest">A IA do Radar busca as informações para você.</p>
            </header>

            <div className="bg-card-dark p-8 rounded-[3rem] border border-white/10 shadow-2xl relative group">
              <textarea 
                className="w-full bg-black/30 border border-white/5 p-8 rounded-[2rem] text-white outline-none focus:border-primary/50 h-56 font-light text-xl mb-8 placeholder:text-white/10 resize-none"
                placeholder="Cole aqui o link do Instagram, texto de zap ou informações do evento/post..."
                value={syncText}
                onChange={e => setSyncText(e.target.value)}
              />
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <button onClick={() => handleSync('event')} className="bg-white/5 hover:bg-primary p-8 rounded-3xl flex flex-col items-center justify-center gap-3 transition-all group/btn shadow-lg">
                  <span className="material-symbols-outlined text-4xl text-primary group-hover:btn:text-white transition-colors">event</span>
                  <span className="font-black text-[9px] uppercase tracking-widest">Novo Evento</span>
                </button>
                <button onClick={() => handleSync('video')} className="bg-white/5 hover:bg-primary p-8 rounded-3xl flex flex-col items-center justify-center gap-3 transition-all group/btn shadow-lg">
                  <span className="material-symbols-outlined text-4xl text-primary group-hover/btn:text-white transition-colors">movie</span>
                  <span className="font-black text-[9px] uppercase tracking-widest">Novo Vídeo</span>
                </button>
                <button onClick={() => handleSync('article')} className="bg-white/5 hover:bg-primary p-8 rounded-3xl flex flex-col items-center justify-center gap-3 transition-all group/btn shadow-lg">
                  <span className="material-symbols-outlined text-4xl text-primary group-hover/btn:text-white transition-colors">article</span>
                  <span className="font-black text-[9px] uppercase tracking-widest">Novo Artigo</span>
                </button>
              </div>
              {loading && (
                <div className="absolute inset-0 bg-black/90 backdrop-blur-xl rounded-[3rem] flex flex-col items-center justify-center z-50">
                  <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-6"></div>
                  <p className="font-black text-xs uppercase tracking-[0.4em] text-primary animate-pulse">Sincronizando Radar...</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'acervo' && (
          <div className="max-w-5xl mx-auto space-y-12">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-8 border-b border-white/5 pb-10">
              <div>
                <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter leading-none mb-4">GESTÃO DO <br/><span className="text-primary">ACERVO</span></h2>
                <div className="flex gap-4">
                  {(['events', 'videos', 'articles'] as const).map(t => (
                    <button key={t} onClick={() => setManageType(t)} className={`px-6 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${manageType === t ? 'bg-primary border-primary text-white' : 'border-white/10 text-white/30 hover:text-white'}`}>
                      {t==='events'?'Agenda':t==='videos'?'Vídeos':'Posts'}
                    </button>
                  ))}
                </div>
              </div>
              <button 
                onClick={() => setEditingItem({ id: null, type: manageType, title: '', image_url: '', location: '', price: '', day: '', month: '', category: '', excerpt: '', content: '', video_url: '', read_time: '', ticket_url: '' })}
                className="bg-white text-black px-10 py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-primary hover:text-white transition-all shadow-xl"
              >
                + Adicionar Manual
              </button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {loading && items.length === 0 ? (
                <div className="col-span-full py-20 text-center"><div className="w-10 h-10 border-4 border-primary/20 border-t-primary rounded-full animate-spin mx-auto"></div></div>
              ) : items.length > 0 ? (
                items.map(item => (
                  <div key={item.id} className="bg-card-dark border border-white/5 rounded-3xl p-6 flex flex-col gap-6 hover:border-primary/40 transition-all group relative overflow-hidden">
                    <div className="flex items-center gap-4">
                      <div className="w-16 h-16 rounded-2xl overflow-hidden bg-black shrink-0 border border-white/5">
                        <img src={item.image_url || item.thumbnail} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <h4 className="font-black uppercase text-xs truncate text-white leading-tight mb-1">{item.title}</h4>
                        <p className="text-[8px] text-white/30 font-bold uppercase truncate tracking-widest">{item.location || item.category || 'Sem Local'}</p>
                      </div>
                    </div>
                    <div className="flex gap-2 mt-auto">
                      <button onClick={() => setEditingItem({...item, type: manageType})} className="flex-1 bg-white/5 py-3 rounded-xl font-black uppercase text-[9px] hover:bg-primary transition-all">Editar</button>
                      <button onClick={() => deleteItem(item.id)} className="w-12 bg-red-500/10 text-red-500 py-3 rounded-xl hover:bg-red-500 hover:text-white transition-all flex items-center justify-center">
                        <span className="material-symbols-outlined text-lg">delete</span>
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="col-span-full py-32 text-center bg-white/5 rounded-[3rem] border border-dashed border-white/10">
                  <span className="material-symbols-outlined text-6xl text-white/5 mb-4">folder_open</span>
                  <p className="text-white/20 font-black uppercase text-xs tracking-widest">Nada encontrado nesta seção.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'stats' && (
          <div className="max-w-4xl mx-auto space-y-12 animate-fade-in">
             <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter mb-12">NÚMEROS DO <br/><span className="text-primary">SAMBA</span></h2>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/5 text-center">
                   <h4 className="text-primary font-black text-6xl mb-2">{stats.events}</h4>
                   <p className="text-[10px] uppercase font-black tracking-widest text-white/30">Eventos Ativos</p>
                </div>
                <div className="bg-card-dark p-10 rounded-[3rem] border border-white/5 text-center">
                   <h4 className="text-primary font-black text-6xl mb-2">{stats.videos}</h4>
