                    <button key={t} onClick={() => setManageType(t)} className={`px-6 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${manageType === t ? 'bg-primary border-primary text-white shadow-lg' : 'border-white/10 text-white/30 hover:text-white hover:border-white/30'}`}>
