import { GoogleGenAI, Type } from "@google/genai";

/**
 * Parses content from raw text or URLs using Gemini 3.
 */
export async function parseContentWithAI(rawText: string, type: 'event' | 'video' | 'article') {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';
  const isUrl = rawText.trim().startsWith('http');

  const systemInstructions = {
    event: `Você é um scanner de eventos. Extraia dados para JSON. 
    Se o link for Instagram/Facebook/Sympla, use o Google Search para encontrar a URL DA IMAGEM PRINCIPAL. 
    Retorne APENAS: { "title": "max 30 letras", "day": "00", "month": "3 letras", "location": "local", "price": "atrações", "image_url": "link_da_foto_real", "search_term": "busca_alternativa" }`,
    video: "Extraia: {title, category}. Se for YouTube, pegue o título real.",
    article: "Extraia: {title, excerpt, category, read_time}."
  };

  try {
    const config: any = {
      systemInstruction: systemInstructions[type],
      responseMimeType: "application/json",
      temperature: 0.1,
    };

    if (isUrl) config.tools = [{ googleSearch: {} }];

    const prompt = isUrl 
      ? `EXTRAIA A IMAGEM REAL DESTE POST: ${rawText}` 
      : `Analise este texto: "${rawText}"`;

    const response = await ai.models.generateContent({ 
      model, 
      contents: prompt, 
      config 
    });

    const result = response.text;
    if (!result) return null;

    return {
      data: JSON.parse(result.trim()),
      sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((s: any) => s.web?.uri).filter(Boolean) || []
    };
  } catch (e) {
    console.error("Erro Gemini:", e);
    return null;
  }
}

/**
 * Revisa textos mantendo a identidade cultural afro-brasileira.
 */
export async function reviseContentWithAI(text: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  const systemInstruction = `Você é um editor de conteúdo cultural afro-brasileiro. 
  Seu trabalho é: resumir textos, melhorar clareza, manter identidade cultural, 
  NÃO remover termos ancestrais e NÃO simplificar expressões culturais. 
  Mantenha o tom respeitoso, vibrante e ancestral.
  Saída: APENAS o texto revisado, bem formatado, pronto para publicação.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Revise o seguinte texto: "${text}"`,
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    return response.text?.trim() || null;
  } catch (e) {
    console.error("Erro na Revisão IA:", e);
    return null;
  }
}

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { parseContentWithAI, reviseContentWithAI } from '../lib/gemini';
import type { Session } from '@supabase/supabase-js';

interface AdminPanelProps {
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onClose }) => {
  const [session, setSession] = useState<Session | null>(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [authError, setAuthError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<'radar' | 'redacao' | 'acervo' | 'stats'>('radar');
  const [manageType, setManageType] = useState<'events' | 'videos' | 'articles'>('events');
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [syncText, setSyncText] = useState('');
  const [redacaoInput, setRedacaoInput] = useState('');
  const [redacaoOutput, setRedacaoOutput] = useState('');
  const [editingItem, setEditingItem] = useState<any>(null);
  const [stats, setStats] = useState({ events: 0, videos: 0, articles: 0 });

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) setAuthError(null);
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      fetchStats();
      if (activeTab === 'acervo') fetchItems();
    }
  }, [session, activeTab, manageType]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setAuthError(null);
    try {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) throw error;
    } catch (err: any) {
      setAuthError(err.message === 'Invalid login credentials' ? 'E-mail ou senha incorretos.' : err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    onClose();
  };

  const fetchStats = async () => {
    const { count: e } = await supabase.from('events').select('*', { count: 'exact', head: true });
    const { count: v } = await supabase.from('videos').select('*', { count: 'exact', head: true });
    const { count: a } = await supabase.from('articles').select('*', { count: 'exact', head: true });
    setStats({ events: e || 0, videos: v || 0, articles: a || 0 });
  };

  const fetchItems = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from(manageType).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setItems(data || []);
    } catch (err: any) {
      console.error(`Erro ao buscar ${manageType}:`, err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async (type: 'event' | 'video' | 'article') => {
    if (!syncText.trim()) return alert("Cole o conteúdo para a IA analisar.");
    setLoading(true);
    try {
      const result = await parseContentWithAI(syncText, type);
