import { createClient } from '@supabase/supabase-js';

/**
 * Utilitário para recuperar variáveis de ambiente de forma segura em diferentes contextos (Vite ou Node/Shim).
 */
const getEnv = (key: string): string | undefined => {
  try {
    // Tenta obter do padrão Vite (import.meta.env)
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[key]) {
      // @ts-ignore
      return import.meta.env[key];
    }
  } catch (e) {}

  try {
    // Tenta obter do padrão process.env (Node ou ambientes com shim)
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key];
    }
  } catch (e) {}

  return undefined;
};

const supabaseUrl = getEnv('VITE_SUPABASE_URL');
const supabaseAnonKey = getEnv('VITE_SUPABASE_ANON_KEY');

// Log de aviso amigável no console em vez de crash fatal
if (!supabaseUrl || !supabaseAnonKey) {
  console.warn(
    'Supabase: Variáveis de ambiente VITE_SUPABASE_URL ou VITE_SUPABASE_ANON_KEY não encontradas.\n' +
    'Certifique-se de adicioná-las nas configurações do seu projeto no Vercel/Netlify.'
  );
}

/**
 * Inicialização do cliente Supabase.
 * Para evitar o erro "Uncaught Error: supabaseUrl is required", fornecemos URLs de fallback
 * que são validas como string mas falharão de forma segura nas requisições, permitindo
 * que a interface do site carregue (em vez de ficar uma tela branca).
 */
export const supabase = createClient(
  supabaseUrl || 'https://seu-projeto.supabase.co', 
  supabaseAnonKey || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.placeholder'
);

import { createClient } from '@supabase/supabase-js';

const getEnv = (key: string): string | undefined => {
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[key]) {
      // @ts-ignore
      return import.meta.env[key];
    }
  } catch (e) {}

  try {
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key];
    }
  } catch (e) {}

  return undefined;
};

const supabaseUrl = getEnv('VITE_SUPABASE_URL');
const supabaseAnonKey = getEnv('VITE_SUPABASE_ANON_KEY');

// Verifica se as chaves são as de exemplo ou estão vazias
const isConfigured = 
  supabaseUrl && 
  supabaseUrl !== 'https://seu-projeto.supabase.co' && 
  supabaseAnonKey && 
  supabaseAnonKey !== 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.placeholder';

if (!isConfigured) {
  console.warn(
    'Supabase: Chaves de API não configuradas. O site está operando em MODO LOCAL/DEMO.\n' +
    'Para habilitar o banco de dados e a IA, configure VITE_SUPABASE_URL e VITE_SUPABASE_ANON_KEY.'
  );
}

/**
 * Se não estiver configurado, criamos um cliente que não fará nada (evita o erro "Failed to fetch").
 * Se estiver configurado, usamos as credenciais reais.
 */
export const supabase = createClient(
  isConfigured ? supabaseUrl : 'https://localhost:9999', 
  isConfigured ? supabaseAnonKey : 'no-key-provided',
  {
    auth: {
      persistSession: isConfigured, // Desabilita persistência se não houver URL real
      autoRefreshToken: isConfigured,
      detectSessionInUrl: isConfigured
    }
  }
);

